window.EXAM_QUESTIONS = [{"id": 2, "domain": "common_occupational_skills", "question": "What is the main function of a WHMIS pictogram on a welding supply container?", "options": {"A": "Display the product expiration date.", "B": "Show the manufacturer's contact information.", "C": "Provide quick identification of specific hazards.", "D": "Indicate the storage temperature requirement."}, "correct": "C", "explanation": "A WHMIS pictogram gives quick visual identification of the specific hazard class so a worker can recognize the danger at a glance. It is not designed to show contact information, an expiration date, or a storage temperature. Those details live in the label text or the Safety Data Sheet, not in the pictogram."}, {"id": 7, "domain": "common_occupational_skills", "question": "What welding helmet filter lens shade is typically used for stick welding at higher amperages?", "options": {"A": "Shade 2 to 4.", "B": "Shade 5 to 8.", "C": "Shade 10 to 14.", "D": "Shade 15 to 18."}, "correct": "C", "explanation": "Stick welding at higher amperages calls for a filter lens in the shade 10 to 14 range to block the bright arc radiation. Shades 5 to 8 and 2 to 4 are far too light and are meant for cutting or torch work, letting harmful light reach the eyes. Shade 15 to 18 is darker than needed and is reserved for very high current processes."}, {"id": 8, "domain": "common_occupational_skills", "question": "Which material is acceptable for body protection when welding if it is untreated and tightly woven?", "options": {"A": "Nylon.", "B": "Polyester.", "C": "Cotton.", "D": "Acrylic."}, "correct": "C", "explanation": "Untreated tightly woven cotton is acceptable for body protection because it resists ignition better than synthetics and does not melt onto the skin. Polyester, nylon, and acrylic are synthetic fabrics that melt and stick to the skin when sparks land, making burns much worse. That melting behavior is why synthetics are not allowed near welding."}, {"id": 9, "domain": "common_occupational_skills", "question": "Auto-darkening welding helmets must be tested regularly because a failure can result in what condition?", "options": {"A": "Permanent eye damage from infrared only.", "B": "Thermal burns to the face.", "C": "Dehydration of the cornea.", "D": "Arc eye from exposure to arc radiation."}, "correct": "D", "explanation": "An auto-darkening helmet that fails to darken exposes the eyes to the arc and causes arc eye, a painful flash burn of the cornea. Thermal burns, corneal dehydration, and infrared-only damage are not the main result of a darkening failure. Because the lens may not switch in time, regular testing of the helmet protects against arc eye."}, {"id": 23, "domain": "common_occupational_skills", "question": "What is the most important safety rule when using an angle grinder with a cutting disc?", "options": {"A": "Wear a face shield and approved safety glasses.", "B": "Always use both hands and maintain firm control.", "C": "Keep the guard positioned between operator and wheel.", "D": "Never use the face of a cutting disc for side grinding."}, "correct": "D", "explanation": "The most important rule with a cutting disc is to never use its flat face for side grinding, because the thin disc can shatter and throw fragments. Two-hand control, guard position, and a face shield are all good practices but do not address the unique shattering danger of side-loading a cutting disc. Cutting discs are built for edge cutting only."}, {"id": 24, "domain": "common_occupational_skills", "question": "How should you verify that a grinding wheel is safe to mount on a grinder?", "options": {"A": "Check that the maximum RPM rating matches the spindle speed.", "B": "Inspect it visually for obvious damage only.", "C": "Spin it at low speed first to test stability.", "D": "Perform a ring test to detect internal cracks."}, "correct": "D", "explanation": "A ring test, tapping the wheel and listening for a clear ring, detects internal cracks before mounting a grinding wheel. Matching the RPM rating is also required but it confirms speed, not hidden cracks. A visual check or a low-speed spin will not reveal an internal flaw the way a ring test does."}, {"id": 27, "domain": "common_occupational_skills", "question": "What common error should be avoided when using a tape measure for layout work?", "options": {"A": "Measuring directly on paper instead of using written dimensions.", "B": "Using a tape longer than 5 metres.", "C": "Measuring diagonals without adjusting for scale.", "D": "Holding the tape too tightly during measurement."}, "correct": "A", "explanation": "A common layout error is measuring directly on the drawing paper instead of reading the written dimensions, because paper and print scale can be off. Tape length, diagonal scaling, and grip tightness are not the typical source of layout mistakes. Trusting the written numbers avoids built-in scaling errors."}, {"id": 29, "domain": "common_occupational_skills", "question": "Which measuring tool is used to transfer angles from one piece to another?", "options": {"A": "A framing square.", "B": "A combination square.", "C": "A protractor with fixed angles only.", "D": "A bevel gauge or sliding T-bevel."}, "correct": "D", "explanation": "A bevel gauge, or sliding T-bevel, is the tool used to transfer an existing angle from one piece to another. A combination square sets fixed common angles, a fixed protractor reads set angles, and a framing square gives right angles. The adjustable blade of the bevel gauge captures and copies any angle."}, {"id": 36, "domain": "common_occupational_skills", "question": "Why is mousing a hook with wire or a pin important in rigging operations?", "options": {"A": "Prevents accidental disengagement of the sling.", "B": "Strengthens the hook for heavier loads.", "C": "Makes the load more stable during lifting.", "D": "Reduces friction on the hook surface."}, "correct": "A", "explanation": "Mousing a hook with wire or a pin closes the throat so the sling cannot accidentally jump off during the lift. It does not increase the hook's rated strength, stabilize the load on its own, or reduce friction. The mousing keeps the sling captured in the hook."}, {"id": 40, "domain": "common_occupational_skills", "question": "For oxy-fuel equipment inspection, what distinguishes oxygen hose from fuel gas hose?", "options": {"A": "Only size and thickness distinguish them.", "B": "Oxygen hose is red and fuel gas hose is green.", "C": "Both are the same color but labeled differently.", "D": "Oxygen hose is green and fuel gas hose is red."}, "correct": "D", "explanation": "Oxygen hose is green and fuel gas hose is red, a color code that prevents mixing up the two gases. The reverse pairing is wrong, the hoses are not the same color, and color rather than size is the distinguishing feature. Green for oxygen and red for fuel is the standard identification."}, {"id": 41, "domain": "common_occupational_skills", "question": "What is the key difference between oxygen fittings and fuel gas fittings on regulators?", "options": {"A": "Oxygen uses right-hand threads, fuel gas uses left-hand threads.", "B": "Oxygen uses left-hand threads, fuel gas uses right-hand threads.", "C": "They are interchangeable with different adapters.", "D": "The difference is only in the gauge markings."}, "correct": "A", "explanation": "Oxygen fittings use right-hand threads while fuel gas fittings use left-hand threads, which stops the connections from being swapped. The reverse is incorrect, the fittings are not interchangeable with adapters, and the difference is in the thread direction, not just gauge markings. The left-hand fuel thread, often marked with a notch, keeps the gases separate."}, {"id": 51, "domain": "common_occupational_skills", "question": "What should you do if you discover a nick or cut in welding lead insulation?", "options": {"A": "Have a technician inspect but continue work.", "B": "Tape over the damage with electrical tape.", "C": "Use the lead only in controlled conditions.", "D": "Replace the damaged lead immediately."}, "correct": "D", "explanation": "A nick or cut in welding lead insulation calls for replacing the damaged lead right away to avoid shock and arcing. Taping over it, using it in limited conditions, or continuing while waiting for inspection all leave live exposed conductor. Damaged insulation means the lead comes out of service."}, {"id": 56, "domain": "common_occupational_skills", "question": "In confined space work, what range indicates oxygen deficiency in the atmosphere?", "options": {"A": "Below 15 percent oxygen concentration.", "B": "Below 19.5 percent oxygen concentration.", "C": "Below 17 percent oxygen concentration.", "D": "Below 20.5 percent oxygen concentration."}, "correct": "B", "explanation": "Oxygen below 19.5 percent indicates an oxygen-deficient atmosphere in confined space work. Readings of 15 or 17 percent are already dangerously low but fall below the action point rather than at it, and 20.5 percent is within the normal range. The 19.5 percent mark is the recognized line for oxygen deficiency."}, {"id": 57, "domain": "common_occupational_skills", "question": "What is the role of a trained attendant during confined space welding operations?", "options": {"A": "Assist the welder with electrode changes.", "B": "Prepare equipment inside before the welder enters.", "C": "Stay stationed outside monitoring the entrant.", "D": "Operate the ventilation system."}, "correct": "C", "explanation": "A trained attendant stays stationed outside the confined space, monitoring the entrant and ready to summon rescue. The attendant does not go inside to prep equipment, change electrodes, or run the ventilation, since leaving the post would abandon the entrant. Staying outside and watching the worker is the attendant's defined role."}, {"id": 58, "domain": "common_occupational_skills", "question": "Which inert gases used as shielding gas can displace oxygen in confined spaces?", "options": {"A": "Helium in very small quantities only.", "B": "Only argon at high flow rates.", "C": "Argon and helium without any warning signs.", "D": "Nitrogen and argon together."}, "correct": "C", "explanation": "Inert shielding gases such as argon and helium can quietly displace oxygen in a confined space with no smell or warning. The hazard is not limited to high argon flow, tiny helium amounts, or only a nitrogen-argon mix. Both argon and helium are heavier or lighter inert gases that can push out breathable air silently."}, {"id": 60, "domain": "common_occupational_skills", "question": "What should you check first on a newly opened jar of welding electrodes before use?", "options": {"A": "The expiration date on the container label.", "B": "That the electrodes appear dry and the package is intact.", "C": "The color of the flux coating.", "D": "The manufacturer's warehouse code."}, "correct": "B", "explanation": "Before using a newly opened jar of electrodes you check that the rods look dry and the package was intact, since moisture ruins them. An expiration date, flux color, or warehouse code are not the key concern. Confirming dry, undamaged electrodes guards against porosity and cracking."}, {"id": 72, "domain": "layout_and_fabrication", "question": "Why are root opening and root face critical tolerances in weld joint preparation?", "options": {"A": "They only matter for visual appearance.", "B": "They determine the color of the finished weld.", "C": "They control the welding current required.", "D": "They directly affect penetration and weld quality."}, "correct": "D", "explanation": "Root opening and root face are critical because they directly control how deeply the weld penetrates and therefore the joint's quality and strength. They do not set the weld color, the welding current, or just the appearance. Getting these dimensions right governs proper root fusion."}, {"id": 78, "domain": "layout_and_fabrication", "question": "What type of weld joint is formed when two pieces overlap each other?", "options": {"A": "A lap joint.", "B": "A butt joint.", "C": "A corner joint.", "D": "An edge joint."}, "correct": "A", "explanation": "When two pieces overlap each other the weld joint formed is a lap joint. A butt joint is edge to edge, a corner joint forms an L, and an edge joint runs along aligned edges. Overlapping plates make the lap joint."}, {"id": 81, "domain": "layout_and_fabrication", "question": "How is a V-groove prepared compared to a bevel groove in fabrication?", "options": {"A": "Bevel grooves are always used on thicker material.", "B": "V-grooves bevel both pieces; bevel grooves bevel only one.", "C": "V-grooves produce better weld quality.", "D": "Bevel grooves require no edge preparation."}, "correct": "B", "explanation": "A V-groove bevels both pieces so the two angled faces form a V, while a bevel groove angles only one piece. Bevel grooves are not tied to thicker material only, V-grooves are not automatically better quality, and bevel grooves still need edge preparation. Beveling both versus one piece is the distinction."}, {"id": 84, "domain": "layout_and_fabrication", "question": "In welding symbols, what does the reference line position tell you about weld placement?", "options": {"A": "The position depends on the arrow direction.", "B": "Both above and below indicate the same weld location.", "C": "Below line means arrow side; above line means other side.", "D": "It only indicates the joint type, not location."}, "correct": "C", "explanation": "In welding symbols a symbol below the reference line means the arrow side and a symbol above the line means the other side of the joint. Both positions do not mean the same location, the meaning does not flip with arrow direction, and the position indicates side, not just joint type. Below for arrow side and above for other side is the rule."}, {"id": 85, "domain": "layout_and_fabrication", "question": "What information is included when a fillet weld is specified on a welding symbol?", "options": {"A": "Leg size to left of symbol, weld length to right.", "B": "Total weld length and depth of penetration.", "C": "Material thickness and welding process only.", "D": "Number of passes and the electrode type."}, "correct": "A", "explanation": "A fillet weld symbol places the leg size to the left of the symbol and the weld length to the right. It does not show penetration depth, material thickness, process, passes, or electrode in those positions. Size on the left and length on the right is the standard fillet notation."}, {"id": 86, "domain": "layout_and_fabrication", "question": "What does a circle at the bend of the reference line arrow indicate in welding symbols?", "options": {"A": "The weld starts at that point.", "B": "Weld-all-around the entire joint.", "C": "Field welding is required.", "D": "The weld requires backing bar support."}, "correct": "B", "explanation": "A circle at the bend, or elbow, of the reference line arrow means weld all the way around the joint. It does not mark a weld start point, field welding, or a backing bar requirement. The circle at the kink calls for a weld-all-around."}, {"id": 92, "domain": "layout_and_fabrication", "question": "What is a datum line in layout work and why is it important?", "options": {"A": "A reference point from which all other measurements are taken.", "B": "The first line marked on the metal during layout.", "C": "The edge of the workpiece used for alignment.", "D": "The center line of any symmetrical part."}, "correct": "A", "explanation": "A datum line is a reference from which all other measurements are taken, which keeps layout errors from adding up. It is not simply the first line marked, the workpiece edge, or the centerline by definition. Measuring everything from one datum keeps the layout consistent and accurate."}, {"id": 102, "domain": "layout_and_fabrication", "question": "What is hydrogen-induced cracking and why is it a concern in welding?", "options": {"A": "Surface porosity that leaks hydrogen gas.", "B": "Immediate cracking visible during the cooling process.", "C": "Cracks caused by rapid heating of the electrode.", "D": "Delayed cracking from hydrogen and stress in high-strength steels."}, "correct": "D", "explanation": "Hydrogen-induced cracking is delayed cracking caused by trapped hydrogen combined with stress and a hard microstructure in high-strength steels, often appearing hours after the weld cools. That delay and the hydrogen source are what make it dangerous and hard to catch. It is not immediate cracking during cooling, not caused by electrode heating, and is not simple surface porosity."}, {"id": 110, "domain": "layout_and_fabrication", "question": "What is the purpose of tack welds in the fabrication process?", "options": {"A": "Temporary welds that are completely removed later.", "B": "Small welds to hold pieces in alignment before final welding.", "C": "Test welds to verify procedure qualification.", "D": "Welds used only on critical structural work."}, "correct": "B", "explanation": "Tack welds are small welds that hold the pieces in correct alignment before the final welding is done. They keep the fit-up and root opening from shifting while the main weld is laid. They are usually re-melted into the final weld rather than fully removed, are not procedure test welds, and are used on far more than just critical structural work."}, {"id": 114, "domain": "layout_and_fabrication", "question": "What does pre-setting in distortion control mean in fabrication work?", "options": {"A": "Intentionally positioning pieces out of alignment before welding.", "B": "Using fixtures to hold parts completely rigid.", "C": "Calculating the distortion before welding begins.", "D": "Heating the base metal evenly before starting."}, "correct": "A", "explanation": "Pre-setting means intentionally positioning the pieces slightly out of alignment before welding so that the expected weld shrinkage pulls them into the correct final position. The welder predicts the pull and offsets for it in advance. It is not rigid fixturing, not just calculating distortion, and not even preheating of the base metal."}, {"id": 119, "domain": "layout_and_fabrication", "question": "What general rule applies to preheat temperature based on carbon equivalent?", "options": {"A": "All steel requires minimum 150°C preheat.", "B": "CE below 0.40 no preheat; 0.40-0.60 needs 100-200°C preheat.", "C": "Preheat temperature increases as thickness decreases.", "D": "Carbon equivalent has no effect on preheat requirements."}, "correct": "B", "explanation": "A common rule is that steel with a carbon equivalent below 0.40 generally needs no preheat, while a carbon equivalent of 0.40 to 0.60 calls for roughly 100 to 200 degrees Celsius of preheat. This links preheat directly to hardenability. Not all steel needs 150 degrees, preheat rises with thickness rather than falling, and carbon equivalent clearly does affect preheat."}, {"id": 120, "domain": "layout_and_fabrication", "question": "How is preheat applied to the work and how far must it extend?", "options": {"A": "Using torch or electric blanket, extending 75 mm on each side.", "B": "Applied only to the immediate joint area.", "C": "Extended the entire length of the workpiece.", "D": "Applied only to the base metal, not the joint."}, "correct": "A", "explanation": "Preheat is applied with a torch or electric heating blanket and must extend about 75 mm on each side of the joint so the heat spreads evenly and the joint zone is fully warmed. Heating only the immediate joint leaves cold metal that pulls heat away, heating the whole workpiece is wasteful, and skipping the joint itself defeats the purpose."}, {"id": 128, "domain": "layout_and_fabrication", "question": "What carbon content designation in stainless steel wire reduces sensitization risk?", "options": {"A": "Carbon content does not affect sensitization.", "B": "High carbon grades for improved strength.", "C": "Medium carbon content for balanced properties.", "D": "Low carbon grades such as 304L."}, "correct": "D", "explanation": "Low carbon grades such as 304L have reduced carbon, which limits the chromium carbides that form during heating and so lowers the risk of sensitization. High carbon grades make sensitization worse rather than better, medium carbon is not the answer, and carbon content clearly does affect sensitization. The L designation marks the low-carbon protection."}, {"id": 129, "domain": "layout_and_fabrication", "question": "Why should carbon steel wire brushes never be used on stainless steel?", "options": {"A": "The brush bristles will bend and break.", "B": "It will contaminate the stainless surface with iron.", "C": "It will change the color of the stainless steel.", "D": "It will remove the chromium oxide protective layer."}, "correct": "B", "explanation": "A carbon steel wire brush leaves tiny iron particles embedded in the stainless surface, and that iron contamination later rusts and breaks down the corrosion resistance of the stainless. The bristles bending or color change are not the real concern, and a brush does not strip the chromium oxide the way embedded iron contamination harms the surface. A dedicated stainless brush avoids this."}, {"id": 132, "domain": "layout_and_fabrication", "question": "What heat treatment process follows welding in some applications to refine grain?", "options": {"A": "Quenching uses rapid oil cooling.", "B": "Annealing requires heating above the melting point.", "C": "Normalizing involves heating and air cooling.", "D": "Tempering is applied before any other process."}, "correct": "C", "explanation": "Normalizing heats the steel above its transformation range and then cools it in still air, which refines and makes the grain structure more uniform after welding. Annealing does not require heating above the melting point, quenching uses rapid cooling rather than the slow refinement described, and tempering follows hardening rather than coming before everything. Normalizing fits the grain-refining description."}, {"id": 135, "domain": "layout_and_fabrication", "question": "Why can high heat input cause problems in the heat-affected zone?", "options": {"A": "It has no negative effect on the HAZ.", "B": "It prevents the base metal from reaching working temperature.", "C": "It makes slag removal more difficult.", "D": "It causes grain coarsening, which reduces toughness."}, "correct": "D", "explanation": "High heat input keeps the metal hot longer and causes grain coarsening in the heat-affected zone, and coarse grains reduce toughness and make the joint more brittle. It does not prevent the base metal from reaching temperature, does not mainly affect slag removal, and certainly does have a negative effect on the heat-affected zone. Controlling heat input protects toughness."}, {"id": 136, "domain": "layout_and_fabrication", "question": "What is residual stress in a weld and what causes it?", "options": {"A": "Stress from uneven contraction during cooling after welding.", "B": "Stress that only occurs during the welding process.", "C": "External load applied to the finished structure.", "D": "Stress intentionally designed into the weld."}, "correct": "A", "explanation": "Residual stress is locked-in stress left in the weld and surrounding metal from the uneven contraction that happens as different regions cool at different rates after welding, and it remains in the part with no external load applied. It is not only present during welding, not an external service load, and not intentionally designed in. The uneven cooling as the metal shrinks is what causes residual stress to stay locked in the joint."}, {"id": 149, "domain": "layout_and_fabrication", "question": "What does a weld crack represent in terms of code acceptance?", "options": {"A": "Acceptable if it is in the HAZ only.", "B": "Acceptable if it does not exceed maximum size.", "C": "Can be repaired and the weld requalified.", "D": "Always a defect that is never acceptable under any code."}, "correct": "D", "explanation": "A weld crack is always treated as a defect and is never acceptable under welding codes because cracks propagate under load and lead to failure. There is no allowable maximum size that makes a crack acceptable, codes do not let a cracked weld simply be requalified as-is, and a crack in the heat-affected zone is no more acceptable than elsewhere. Cracks must be removed."}, {"id": 151, "domain": "layout_and_fabrication", "question": "What is weld reinforcement and why can excessive reinforcement be rejected?", "options": {"A": "Reinforcement is purely an appearance issue.", "B": "Reinforcement always increases weld strength.", "C": "The thickness of weld metal in the joint.", "D": "Metal above base metal surface; excess creates stress concentrations."}, "correct": "D", "explanation": "Weld reinforcement is the weld metal that sits above the base metal surface, and excessive reinforcement creates a sharp transition that concentrates stress and can be cause for rejection. It does not always increase strength, is not simply the thickness of metal in the joint, and is more than just an appearance issue. Controlling reinforcement avoids stress risers."}, {"id": 152, "domain": "layout_and_fabrication", "question": "What must be cleaned from each weld pass before the next pass is deposited?", "options": {"A": "Only the top layer of the previous bead.", "B": "Only visible spatter, not slag.", "C": "All slag using chipping hammer and wire brush.", "D": "Cleaning is optional between passes."}, "correct": "C", "explanation": "All slag must be removed between passes using a chipping hammer and wire brush, because trapped slag becomes a buried inclusion in the next pass. Removing only visible spatter and not slag leaves defects, cleaning only the top layer is not enough, and cleaning is not optional between passes. Full slag removal keeps each pass sound."}, {"id": 153, "domain": "layout_and_fabrication", "question": "Why should you inspect each weld pass after cleaning and before depositing the next?", "options": {"A": "To find defects before they are buried under more weld.", "B": "To measure the height of each pass.", "C": "To ensure the electrode holder is working properly.", "D": "Inspection is only required on the final cap."}, "correct": "A", "explanation": "Each pass is inspected after cleaning and before the next pass so any defect is found while it can still be fixed, instead of being buried under more weld metal. It is not mainly to measure pass height, not to check the electrode holder, and inspection is not limited to only the final cap. Catching problems early prevents trapped defects."}, {"id": 154, "domain": "layout_and_fabrication", "question": "What determines whether root passes are the integrity foundation for multi-pass welds?", "options": {"A": "Root quality is irrelevant if fill passes are perfect.", "B": "Root passes are only for appearance purposes.", "C": "The cap pass determines overall weld quality.", "D": "Poor root fusion or cracks cannot be fixed by perfect cap."}, "correct": "D", "explanation": "The root pass is the integrity foundation because poor root fusion or a root crack cannot be repaired by laying a perfect cap on top, so a bad root dooms the whole weld. Root passes are not just for appearance, the cap alone does not determine overall quality, and root quality is never irrelevant even with perfect fill passes. The root must be sound first."}, {"id": 155, "domain": "layout_and_fabrication", "question": "What are the key requirements for a cap pass in multi-pass weld completion?", "options": {"A": "Height and appearance only matter, not fusion.", "B": "Any smooth bead meets code requirements.", "C": "Cap pass does not require visual inspection.", "D": "Smooth appearance, clean tie-in, meets dimensional requirements."}, "correct": "D", "explanation": "A good cap pass needs a smooth appearance, a clean tie-in to the base metal at the toes, and it must meet the dimensional requirements of the weld. Not just any smooth bead passes code, the cap does require visual inspection, and fusion matters as much as height and appearance. The cap must look right and fit the spec."}, {"id": 157, "domain": "layout_and_fabrication", "question": "Why must groove angle remain within specified tolerances during joint fit-up?", "options": {"A": "Tolerance is only for documentation purposes.", "B": "Groove angle is purely a visual specification.", "C": "It directly affects heat input and weld penetration characteristics.", "D": "Groove angle has no effect on weld quality."}, "correct": "C", "explanation": "Groove angle must stay within tolerance because it directly affects how much heat goes into the joint and how well the weld penetrates the root and sidewalls. It is not just a visual spec, the tolerance is not only for paperwork, and groove angle clearly does affect weld quality. Holding the angle keeps penetration and fusion consistent."}, {"id": 158, "domain": "layout_and_fabrication", "question": "What is the critical measurement that keeps edges from melting away during root pass?", "options": {"A": "Groove angle prevents edge separation.", "B": "Root opening controls edge melting.", "C": "The root face dimension provides this protection.", "D": "Base metal thickness determines edge stability."}, "correct": "C", "explanation": "The root face, or land, is the critical measurement that keeps the joint edges from melting away during the root pass because it leaves a controlled amount of metal at the bottom. The root opening is the gap and controls penetration access rather than edge melting, groove angle does not prevent edge separation, and base metal thickness alone does not set edge stability. The root face protects the edges."}, {"id": 163, "domain": "common_occupational_skills", "question": "When rigging and slinging a heavy steel beam for an overhead lift, the angle between the two sling legs increases as they spread wider apart. What happens to the tension load carried by each individual sling leg as that included angle gets larger?", "options": {"A": "Tension in each sling leg decreases steadily as it spreads.", "B": "Tension in each sling leg increases as the angle widens.", "C": "Tension stays equal to half the total load weight.", "D": "Tension shifts entirely onto the shorter sling leg only."}, "correct": "B", "explanation": "As the included angle between two sling legs widens, each leg must pull at a flatter angle, which increases the tension carried by each individual leg for the same load. Tension does not decrease as the angle widens, it does not stay fixed at half the load once the legs are angled, and it does not shift entirely onto one leg. Wider angles mean higher leg tension."}, {"id": 174, "domain": "cutting_and_gouging", "question": "A welder is selecting a cutting tip for oxy-fuel work on three-inch thick steel plate. Tip selection directly affects cut quality and gas consumption. Which factor most directly determines the correct cutting tip size and orifice to choose for a given job?", "options": {"A": "The brand of regulator attached to the cylinders.", "B": "The length of the cutting hoses being used.", "C": "The ambient temperature inside the work shop.", "D": "The thickness of the material being cut."}, "correct": "D", "explanation": "Cutting tip size and orifice are chosen mainly based on the thickness of the material being cut, since thicker plate needs more preheat and a larger oxygen stream. The regulator brand, hose length, and shop ambient temperature do not determine the correct tip. Matching the tip to the plate thickness gives a clean efficient cut."}, {"id": 180, "domain": "cutting_and_gouging", "question": "When oxy-fuel cutting is progressing well, the operator watches the stream of sparks and slag leaving the underside of the plate. A good cut produces a particular spark pattern below the work. Which spark behaviour indicates the oxygen is properly cutting through the full thickness?", "options": {"A": "Sparks blow back upward toward the torch tip.", "B": "Sparks shower outward in random unstable directions.", "C": "Sparks stop completely once preheat is reached.", "D": "A steady stream of sparks exits straight downward."}, "correct": "D", "explanation": "A good oxy-fuel cut sends a steady stream of sparks straight downward out of the bottom of the plate, showing the oxygen is cutting cleanly through the full thickness. Sparks blowing back up toward the tip means the cut is not penetrating, random unstable sparks signal a poor cut, and sparks stopping at preheat means no cutting is happening. The steady downward stream confirms full penetration."}, {"id": 182, "domain": "cutting_and_gouging", "question": "Pressure settings for oxy-fuel cutting come from the manufacturer's tip chart based on material thickness. A welder ignores the chart and sets the cutting oxygen pressure much higher than recommended for the tip. What problem commonly results from this excessive oxygen pressure during cutting?", "options": {"A": "Drag lines become perfectly vertical and very smooth.", "B": "The preheat flames immediately extinguish at the tip.", "C": "The steel fails to reach kindling temperature at all.", "D": "A turbulent oxygen stream causing a wider rougher kerf."}, "correct": "D", "explanation": "Setting cutting oxygen pressure much higher than the tip chart recommends creates a turbulent oxygen stream that widens and roughens the kerf. The preheat flames do not immediately go out from high oxygen pressure, the steel still reaches kindling temperature, and the drag lines do not become perfectly smooth. Excess oxygen pressure makes a turbulent, rough, wide cut."}, {"id": 184, "domain": "cutting_and_gouging", "question": "Drag lines on an oxy-fuel cut face reveal information about the cut. A welder sees drag lines that curve sharply backward, lagging well behind the direction of travel near the bottom of the cut. What does this backward drag line pattern most likely indicate?", "options": {"A": "The cutting oxygen pressure was set excessively high.", "B": "The preheat flame was adjusted too oxidizing.", "C": "The travel speed was too fast for full penetration.", "D": "The tip was held too far from the work."}, "correct": "C", "explanation": "Drag lines that curve sharply backward and lag well behind the travel direction near the bottom indicate the travel speed was too fast for full penetration, so the oxygen jet falls behind through the thickness. Excessive oxygen pressure roughens the kerf rather than causing this lag, an oxidizing preheat is a flame issue, and tip distance affects the cut differently. Backward-lagging drag lines mean travel was too fast."}, {"id": 201, "domain": "cutting_and_gouging", "question": "An apprentice asks why oxygen must never be used to blow dust off clothing or to cool down in hot weather. Oxygen behaves dangerously in certain situations. What is the key hazard of allowing pure oxygen to saturate clothing or contact oil and grease?", "options": {"A": "Oxygen makes clothing burn violently and ignite easily.", "B": "Oxygen causes immediate frostbite on contact with skin.", "C": "Oxygen is toxic and harmful to breathe directly.", "D": "Oxygen corrodes cotton fabric within a few minutes."}, "correct": "A", "explanation": "Pure oxygen saturates fabric and makes clothing ignite and burn violently from even a small spark, and it reacts violently with oil and grease. Oxygen itself is not toxic to breathe and does not cause frostbite the way a cryogenic liquid would. Option D is wrong because oxygen does not corrode cotton, the real danger is rapid combustion."}, {"id": 202, "domain": "cutting_and_gouging", "question": "A welder is choosing between oxy-fuel and plasma to cut a stack of thin aluminum sheets. Material type and thickness guide the choice of cutting process. Considering the properties of aluminum, why is oxy-fuel cutting generally unsuitable for cutting aluminum plate?", "options": {"A": "Aluminum melts too slowly under the preheat flames.", "B": "Aluminum does not oxidize in the way oxy-fuel needs.", "C": "Aluminum reflects the cutting oxygen jet completely away.", "D": "Aluminum requires far higher acetylene pressures to cut."}, "correct": "B", "explanation": "Oxy-fuel cutting works by burning the metal in a jet of oxygen, but aluminum does not oxidize in the rapid way steel does, so the process cannot sustain the cut. Aluminum also forms a tough refractory oxide that resists the reaction rather than melting slowly or reflecting the jet. Higher acetylene pressure cannot fix this because the chemistry of aluminum oxidation is the limiting factor."}, {"id": 207, "domain": "cutting_and_gouging", "question": "A cutting tip orifice becomes partially clogged with slag spatter, distorting the oxygen stream and ruining cut quality. The welder needs to restore the tip. Which tool and method correctly cleans a clogged oxy-fuel cutting tip orifice without enlarging or damaging it?", "options": {"A": "A twist drill bit chucked into a hand drill.", "B": "A proper tip cleaner file set of correct size.", "C": "A steel wire pushed in with strong pressure.", "D": "A grinder applied lightly to the tip face."}, "correct": "B", "explanation": "A clogged cutting tip orifice should be cleaned with a proper tip cleaner file set of the correct size so the hole keeps its shape. A twist drill or a grinder will enlarge or distort the orifice and ruin the oxygen stream. Forcing a steel wire in with strong pressure can scratch or enlarge the precise opening."}, {"id": 209, "domain": "cutting_and_gouging", "question": "Plasma cutting gas selection affects cut quality on different metals. A welder is setting up to cut mild steel and chooses the cutting gas. Which gas is most commonly used as the plasma and cutting gas for general mild steel plasma cutting work?", "options": {"A": "Pure argon gas for the cleanest mild steel cuts.", "B": "Acetylene gas to add heat to the plasma stream.", "C": "Pure helium for the deepest penetration possible.", "D": "Compressed air or oxygen for mild steel cutting."}, "correct": "D", "explanation": "Compressed air or oxygen is the gas most commonly used for general plasma cutting of mild steel because it produces clean cuts at low cost. Pure argon makes a poor cut on mild steel, and helium is expensive and not standard for this work. Acetylene is a fuel gas and is not used as a plasma cutting gas."}, {"id": 220, "domain": "cutting_and_gouging", "question": "A welder must decide the order of operations when fabricating a beveled butt joint from plate that needs both cutting to length and edge preparation. Planning the cuts improves efficiency and accuracy. Which approach best produces an accurate beveled edge ready for welding?", "options": {"A": "Weld the joint first, then cut the bevel afterward.", "B": "Bevel both faces randomly without measuring the angle.", "C": "Cut to size, then bevel the edge with controlled torch angle.", "D": "Skip beveling and rely on extra weld passes instead."}, "correct": "C", "explanation": "The best approach is to cut the piece to size first, then bevel the edge with a controlled torch angle, giving an accurate edge ready for welding. Welding the joint before cutting the bevel makes no sense, and beveling randomly without measuring ruins fit-up. Skipping the bevel and relying on extra passes does not produce a proper prepared joint."}, {"id": 222, "domain": "cutting_and_gouging", "question": "During air carbon arc gouging, carbon migrates from the electrode into the gouged surface when the air stream is delayed or weak. This leaves a hardened, high-carbon layer behind. What term describes this contamination that must be removed before welding over the gouge?", "options": {"A": "Excessive dross adhering tightly along the lower edge.", "B": "Slag inclusion trapped beneath the new weld bead.", "C": "Undercut along both top edges of the groove.", "D": "Carbon deposit or carbon pickup on the gouge surface."}, "correct": "D", "explanation": "When the air stream is weak or delayed during CAC-A, carbon migrates into the surface and leaves a carbon deposit or carbon pickup that must be removed before welding. Dross, undercut, and slag inclusion are different defects not caused by carbon transferring from the electrode. The hardened high-carbon layer is specifically called carbon pickup."}, {"id": 224, "domain": "cutting_and_gouging", "question": "Scarfing is used to remove surface flaws from steel billets or slabs before further processing. A welder must produce a smooth, shallow depression without cutting too deep into the parent metal. What is the main goal when scarfing a surface defect from a steel workpiece?", "options": {"A": "Remove only the flawed surface layer while limiting depth.", "B": "Build up extra metal over the flaw with filler rod.", "C": "Create a vertical wall around the entire flawed region.", "D": "Pierce completely through the section to drain the defect."}, "correct": "A", "explanation": "The main goal of scarfing is to remove only the flawed surface layer while limiting how deep the cut goes into the parent metal. Piercing through the section or building up filler over the flaw defeats the purpose. Creating a vertical wall around the flaw is not the smooth shallow depression scarfing aims to produce."}, {"id": 228, "domain": "cutting_and_gouging", "question": "After a mechanized oxyfuel cut, an inspector examines the cut face for quality indicators. Curved lines run vertically down the cut face showing how the cutting stream traveled. What are these vertical lines on an oxyfuel cut face called, and what do they indicate?", "options": {"A": "Mill scale lines, which form before any cutting begins.", "B": "Drag lines, which reveal travel speed and cut quality.", "C": "Stress cracks, which mean the plate must be scrapped.", "D": "Heat checks, which show the plate was overheated badly."}, "correct": "B", "explanation": "The curved vertical lines on an oxyfuel cut face are drag lines, and they reveal travel speed and overall cut quality. They are not mill scale, heat checks, or stress cracks, which are unrelated conditions. Reading the drag lines helps the inspector judge whether the cut speed was correct."}, {"id": 229, "domain": "cutting_and_gouging", "question": "A welder makes an oxyfuel cut and finds a heavy, hard layer of resolidified metal and oxide clinging to the bottom edge of the cut. It must be chipped or ground away before the part can be used. What is this clinging material on the bottom cut edge called?", "options": {"A": "Spatter thrown upward from the molten cut zone.", "B": "Dross, the resolidified slag adhering to the cut.", "C": "Kerf buildup formed by the preheat flame cones.", "D": "Porosity left inside the cooled cut surface region."}, "correct": "B", "explanation": "The heavy hard layer of resolidified metal and oxide clinging to the bottom cut edge is called dross. Spatter is thrown molten droplets, kerf buildup from preheat cones is not a standard term for this, and porosity is internal voids. Dross must be chipped or ground away before the part is used."}, {"id": 233, "domain": "cutting_and_gouging", "question": "Proper air carbon arc gouging requires the compressed air jet to strike behind the arc and blow molten metal out of the groove. On a standard gouging torch, where should the air holes be positioned relative to the electrode for the air stream to work correctly?", "options": {"A": "Underneath the electrode, between it and the workpiece.", "B": "At the rear, so air blows along behind the arc.", "C": "On the side facing forward in the direction of travel.", "D": "Above the electrode, blowing air upward away from work."}, "correct": "B", "explanation": "On a CAC-A gouging torch the air holes sit at the rear so the air blows along behind the arc and clears molten metal out of the groove. Placing the air under, ahead of, or above the electrode would not sweep the molten pool out properly. The rear air position is what makes the gouging action work."}, {"id": 234, "domain": "cutting_and_gouging", "question": "A welder reviews a finished U-groove gouge prepared for back welding and checks that the profile is smooth and even. Why does a uniform, smooth gouge profile matter before depositing a weld bead into the gouged groove on a back-gouged joint?", "options": {"A": "It promotes good fusion and reduces trapped slag or defects.", "B": "It guarantees the joint needs no further inspection at all.", "C": "It allows welding without removing any carbon contamination.", "D": "It lets the welder skip preheat on thick sections entirely."}, "correct": "A", "explanation": "A uniform smooth gouge profile matters because it promotes good fusion and reduces trapped slag or defects in the back weld. A smooth profile does not remove the need for inspection, does not excuse leaving carbon contamination, and does not let the welder skip required preheat. Good fusion and fewer trapped defects are the real reasons."}, {"id": 235, "domain": "cutting_and_gouging", "question": "A plasma cutting operator finds the cut edge is bevelled the same way on both sides and the kerf is widening over time. The electrode and nozzle were recently changed. Which often-overlooked consumable, when worn or installed crooked, can cause this symmetrical bevel problem?", "options": {"A": "The ground clamp attached to the cutting table frame.", "B": "The swirl ring whose gas-flow ports have become clogged.", "C": "The power cable connecting the torch to the supply.", "D": "The torch trigger switch wiring inside the handle."}, "correct": "B", "explanation": "When the kerf is symmetrically beveled and widening after a fresh electrode and nozzle, the often-overlooked culprit is the swirl ring whose gas-flow ports have clogged or whose seat is crooked. The ground clamp, power cable, and trigger wiring do not shape the cutting arc. A worn or misaligned swirl ring upsets the gas swirl and causes the symmetrical bevel."}, {"id": 241, "domain": "welding_processes", "question": "In the SMAW electrode classification system, the E6010 number contains coded information about the electrode and its weld. In the designation E6010, what does the first two-digit number 60 specifically tell the welder about the deposited weld metal it produces?", "options": {"A": "The recommended welding current measured in amperes for the rod.", "B": "The minimum tensile strength of the weld is roughly 60,000 psi.", "C": "The diameter of the electrode core wire in millimetres.", "D": "The maximum allowable plate thickness for the electrode."}, "correct": "B", "explanation": "In E6010 the first two digits, 60, give the minimum tensile strength of the deposited weld metal as roughly 60,000 psi. The number does not state the welding current, the core wire diameter, or a maximum plate thickness. Tensile strength is the meaning of the leading digits in the SMAW classification."}, {"id": 242, "domain": "welding_processes", "question": "An SMAW electrode is marked E7018, and the welder needs to know what the last two digits, 18, reveal about this electrode and how it runs. In the classification E7018, what do the digits 1 and 8 together indicate about welding position and coating type?", "options": {"A": "Flat position only paired with a high-cellulose sodium coating.", "B": "Vertical down only with an acid mineral coating.", "C": "Horizontal fillets only with a rutile titania coating.", "D": "All welding positions paired with a low-hydrogen iron-powder coating."}, "correct": "D", "explanation": "In E7018 the digits 1 and 8 together mean the rod welds in all positions and uses a low-hydrogen iron-powder coating. They do not indicate flat only with cellulose, horizontal fillets with rutile, or vertical down with an acid coating. The 1 marks all positions and the 8 marks the low-hydrogen iron-powder type."}, {"id": 246, "domain": "welding_processes", "question": "A welder running SMAW holds too long an arc and notices increased spatter, a wide weak bead, and more porosity. Arc length strongly affects weld quality. Which statement best describes the correct arc length for most SMAW electrodes during welding?", "options": {"A": "Roughly equal to the diameter of the electrode core wire.", "B": "About three times the diameter of the electrode core wire.", "C": "As long as possible to see the molten puddle clearly.", "D": "Zero gap, dragging the coating against the base metal."}, "correct": "A", "explanation": "The correct arc length for most SMAW electrodes is roughly equal to the diameter of the electrode core wire. Three times the diameter is far too long and causes spatter and porosity, and the longest possible arc gives a weak wide bead. Dragging the coating with zero gap is not a correct general arc length."}, {"id": 250, "domain": "welding_processes", "question": "Low-hydrogen E7018 electrodes absorb moisture from the surrounding air, which can later cause hydrogen cracking in the weld. Proper storage protects them. After opening a sealed container, how should E7018 electrodes normally be stored to keep moisture pickup under control?", "options": {"A": "In an open bin on the shop floor near the welding area.", "B": "Submerged in clean oil to block all contact with air.", "C": "In a sealed plastic bag inside a cold refrigerated cabinet.", "D": "In a heated rod oven held at the manufacturer's temperature."}, "correct": "D", "explanation": "After opening the sealed container, E7018 electrodes should be kept in a heated rod oven at the manufacturer's temperature to control moisture pickup. An open bin, a cold refrigerated cabinet, or submerging in oil would not protect them and could ruin the rods. The heated holding oven keeps the low-hydrogen coating dry."}, {"id": 265, "domain": "welding_processes", "question": "The prefix letter E in an SMAW electrode designation such as E7018 has a specific meaning defined by the classification system used in the trade. What does the letter E at the very start of an SMAW electrode classification number actually stand for?", "options": {"A": "Extra-strength, meaning the rod exceeds normal strength ratings.", "B": "The electrode is rated for export-grade structural steel only.", "C": "Electrode, indicating it is used for electric arc welding work.", "D": "Enclosed, meaning the coating fully seals the inner core wire."}, "correct": "C", "explanation": "The letter E at the start of an SMAW designation stands for electrode, indicating it is used for electric arc welding. It does not mean export-grade, extra-strength, or enclosed. E simply identifies the filler as an electrode."}, {"id": 270, "domain": "welding_processes", "question": "A welder pulls a fresh E7018 electrode from a sealed manufacturer container that has never been opened before this shift. Before placing leftover electrodes into a holding oven, what general practice applies to brand-new low-hydrogen electrodes taken from a properly sealed package?", "options": {"A": "They must always be baked once before any welding use.", "B": "They must be soaked in water to activate the flux first.", "C": "They are ready to use and only need oven storage afterward.", "D": "They should be left in open air overnight before welding."}, "correct": "C", "explanation": "Brand-new low-hydrogen electrodes from a properly sealed package are ready to use and only need oven storage afterward to keep them dry. They do not need to be baked first, soaked in water, or left in open air overnight. A factory-sealed package keeps them dry until opened."}, {"id": 273, "domain": "welding_processes", "question": "A welder must select an electrode diameter for welding thin 3 mm sheet metal in the flat position with SMAW. Choosing too large a diameter causes burn-through. Which general principle guides electrode diameter selection relative to base metal thickness in SMAW?", "options": {"A": "Use only the thinnest electrode regardless of plate thickness.", "B": "Always use the largest diameter the machine can power.", "C": "Diameter has no relationship to base metal thickness at all.", "D": "Match electrode diameter to thickness, using smaller on thin metal."}, "correct": "D", "explanation": "The guiding principle is to match electrode diameter to base metal thickness, using smaller diameters on thin metal to avoid burn-through. Always using the largest diameter the machine can power, or claiming diameter has no relationship to thickness, would cause defects. Matching size to thickness gives proper control."}, {"id": 276, "domain": "welding_processes", "question": "A welder reviews the coating type behind each electrode class. E6010 uses a high-cellulose sodium coating that burns to create a deep digging arc. What is the main effect of the high-cellulose coating on the E6010 arc and the resulting weld penetration?", "options": {"A": "It produces a soft shallow arc with minimal penetration.", "B": "It limits the electrode to flat-position welding only.", "C": "It creates a forceful deep-penetrating digging arc action.", "D": "It eliminates all slag and leaves a bare clean bead."}, "correct": "C", "explanation": "The high-cellulose coating on E6010 burns to create a forceful deep-penetrating digging arc. It does not give a soft shallow arc, limit the rod to flat position, or leave a bare slag-free bead. The cellulose coating is what produces the deep digging action."}, {"id": 281, "domain": "welding_processes", "question": "A welder is joining thin 16-gauge sheet metal in the vertical position and wants a transfer mode that produces a fast-freezing puddle with low heat input and minimal burn-through. Which metal transfer mode best suits this thin material and out-of-position welding requirement?", "options": {"A": "Globular transfer, which throws large irregular drops across the arc.", "B": "Spray transfer, which floods the joint with high deposition heat.", "C": "Short circuit transfer, which gives low heat and controls the thin puddle.", "D": "Pulsed spray transfer, which always needs heavy plate thicknesses."}, "correct": "C", "explanation": "Short circuit transfer gives low heat input and a fast-freezing puddle, making it the best mode for thin 16-gauge sheet welded out of position. Spray and globular transfer put too much heat into thin metal, and pulsed spray is not limited to thick plate but offers more heat than needed here. Short circuit transfer controls the thin puddle with minimal burn-through."}, {"id": 284, "domain": "welding_processes", "question": "A welder notices heavy spatter, a loud erratic crackling arc, and large droplets dropping across a wide arc gap while using straight CO2 shielding on heavy plate. Which metal transfer mode is most likely occurring during this welding operation?", "options": {"A": "Spray transfer with a smooth quiet hissing arc sound.", "B": "Pulsed transfer producing one droplet per current pulse cleanly.", "C": "Globular transfer producing large droplets and considerable spatter.", "D": "Short circuit transfer with the wire dipping into the puddle."}, "correct": "C", "explanation": "Heavy spatter, a loud erratic crackling arc, and large droplets crossing a wide gap with straight CO2 on heavy plate describe globular transfer. Spray transfer is smooth and quiet, pulsed transfer drops one clean droplet per pulse, and short circuit transfer dips the wire into the puddle. The large spattery droplets identify globular transfer."}, {"id": 287, "domain": "welding_processes", "question": "A common tri-mix shielding gas used for GMAW on stainless steel combines argon as the base gas with small additions of two other gases. Which combination correctly describes a typical stainless steel tri-mix shielding gas blend?", "options": {"A": "Argon with helium and a very small carbon dioxide addition.", "B": "Carbon dioxide with nitrogen and a large hydrogen addition.", "C": "Helium with oxygen and a heavy argon dilution component.", "D": "Nitrogen with argon and a moderate acetylene gas addition."}, "correct": "A", "explanation": "A typical stainless steel tri-mix is argon with helium and a very small carbon dioxide addition. Carbon dioxide with nitrogen and large hydrogen, helium with oxygen and heavy argon, or nitrogen with argon and acetylene are not standard stainless tri-mix blends. The argon, helium, and small CO2 mix is the common stainless tri-mix."}, {"id": 295, "domain": "welding_processes", "question": "What polarity is standard for almost all GMAW welding with solid wire on carbon steel, providing a stable arc and good penetration when the electrode wire carries this charge from the power source?", "options": {"A": "Direct current electrode negative, often called straight polarity.", "B": "Alternating current cycling between positive and negative rapidly.", "C": "Variable polarity switching automatically with the wire feed speed.", "D": "Direct current electrode positive, often called reverse polarity."}, "correct": "D", "explanation": "Almost all GMAW with solid wire on carbon steel uses direct current electrode positive, also called reverse polarity, for a stable arc and good penetration. DCEN, AC, or an automatically variable polarity are not the standard for solid-wire GMAW. DCEP is the normal polarity for this process."}, {"id": 297, "domain": "welding_processes", "question": "Excessive spatter is plaguing a welder running short circuit transfer with CO2 shielding on mild steel. Besides gas choice, which voltage and wire feed relationship adjustment is most likely to reduce the spatter being produced at the arc?", "options": {"A": "Lowering the gas flow to five cubic feet per hour.", "B": "Increasing the contact tip to work distance to twice the normal.", "C": "Switching the polarity to direct current electrode negative output.", "D": "Fine tuning the voltage to match the wire feed speed properly."}, "correct": "D", "explanation": "Excessive spatter in short circuit CO2 welding is most likely reduced by fine tuning the voltage to match the wire feed speed properly. Doubling the stickout, switching to DCEN, or dropping gas flow to five cubic feet per hour would not fix the spatter and could create new problems. Balancing voltage to wire feed smooths the short circuit transfer."}, {"id": 298, "domain": "welding_processes", "question": "In the ER70S-6 wire classification, the S indicates a solid electrode and the 6 refers to the chemical composition. The number 6 specifically signals higher levels of which two deoxidizing elements that help the wire tolerate dirtier base metal?", "options": {"A": "Higher chromium and nickel for corrosion resistant deposits.", "B": "Higher carbon and sulfur for increased weld hardness.", "C": "Higher copper and tin for improved electrical conductivity.", "D": "Higher silicon and manganese acting as deoxidizers in the puddle."}, "correct": "D", "explanation": "In ER70S-6 the number 6 signals higher levels of silicon and manganese, which act as deoxidizers so the wire tolerates dirtier base metal. It does not mean higher chromium and nickel, carbon and sulfur, or copper and tin. The added silicon and manganese deoxidizers define the 6 classification."}, {"id": 299, "domain": "welding_processes", "question": "A welder must choose the GMAW transfer mode for welding heavy plate where high deposition and deep penetration matter and out-of-position work is not required. The arc draws current above the transition level into a fine droplet stream. Which mode is this?", "options": {"A": "Globular transfer with large erratic droplets and high spatter.", "B": "Short circuit transfer with the wire shorting many times per second.", "C": "Spray transfer with a fine axial stream of tiny droplets.", "D": "Pulsed transfer with one droplet detached on each current peak."}, "correct": "C", "explanation": "Welding heavy plate in the flat position for high deposition and deep penetration with a fine droplet stream above the transition current describes spray transfer. Globular transfer has large erratic droplets, short circuit shorts many times per second, and pulsed transfer detaches one droplet per peak. The fine axial stream of tiny droplets is spray transfer."}, {"id": 305, "domain": "welding_processes", "question": "A welder runs GMAW outdoors and the weld keeps showing porosity even though the gas cylinder is full and the regulator works. Which environmental factor is the most probable cause of the recurring porosity in this outdoor situation?", "options": {"A": "Direct current electrode positive polarity used on carbon steel.", "B": "Wire feed speed set perfectly to match the voltage chart.", "C": "Wind blowing away the shielding gas coverage from the weld.", "D": "Contact tip to work distance held at the recommended length."}, "correct": "C", "explanation": "Outdoors, wind blowing away the shielding gas exposes the molten pool to air and causes porosity even with a full cylinder. A wire feed speed matched to the chart and a correct contact tip distance both help weld quality rather than cause porosity. Electrode positive polarity is the normal correct setting for carbon steel and does not cause porosity."}, {"id": 306, "domain": "welding_processes", "question": "Which range of shielding gas flow rate is generally recommended for typical GMAW on carbon steel in a shop environment with no drafts, balancing adequate coverage against wasteful turbulence at the nozzle during welding?", "options": {"A": "Roughly two to five cubic feet per hour for coverage.", "B": "Roughly twenty to forty cubic feet per hour for coverage.", "C": "Roughly one hundred to one fifty cubic feet per hour.", "D": "Roughly two hundred to three hundred cubic feet per hour."}, "correct": "B", "explanation": "Roughly twenty to forty cubic feet per hour gives good coverage without wasteful turbulence for typical GMAW on carbon steel. Two to five cubic feet per hour is far too low to shield the pool. One hundred and above causes turbulence that pulls air into the weld and wastes gas."}, {"id": 311, "domain": "welding_processes", "question": "In GMAW, the term constant voltage describes the type of power source most commonly used. What key self-regulating behavior does a constant voltage power source provide that makes it well suited to the wire-fed GMAW process?", "options": {"A": "It holds wire feed speed steady regardless of the trigger position.", "B": "It supplies pure alternating current to clean the base metal.", "C": "It increases voltage sharply whenever the stickout gets shorter.", "D": "It self-adjusts amperage to maintain a steady arc length automatically."}, "correct": "D", "explanation": "A constant voltage power source self-adjusts amperage to hold a steady arc length automatically, which suits the wire-fed GMAW process. It does not hold wire feed speed, since the feeder does that, and it does not spike voltage when stickout shortens. It also supplies direct current for GMAW, not pure alternating current."}, {"id": 319, "domain": "welding_processes", "question": "A welder must read a wire spool label that says ER70S-6, 0.035 inch. The 0.035 inch figure on the spool refers to which physical property of the solid electrode wire wound on that particular spool?", "options": {"A": "The minimum tensile strength rating of the deposited weld.", "B": "The total length of wire remaining on the spool.", "C": "The recommended shielding gas flow in cubic feet hourly.", "D": "The diameter of the solid electrode wire in inches."}, "correct": "D", "explanation": "On the spool label, 0.035 inch is the diameter of the solid electrode wire. The minimum tensile strength is shown by the 70 in ER70S-6, not by the diameter. The number does not state gas flow or the length of wire remaining on the spool."}, {"id": 321, "domain": "welding_processes", "question": "A welder needs to join galvanized steel with GMAW and is concerned about fumes and weld quality. Which precaution and material consideration is most important when welding zinc-coated galvanized steel using the GMAW process in a shop?", "options": {"A": "Removing all shielding gas to let the zinc burn off freely.", "B": "Providing good ventilation because zinc fumes are hazardous to breathe.", "C": "Using only direct current electrode negative on galvanized steel.", "D": "Welding faster than normal so the zinc never gets hot."}, "correct": "B", "explanation": "Welding zinc-coated galvanized steel releases hazardous zinc fumes, so good ventilation is the most important precaution. Removing the shielding gas would ruin the weld and expose the pool to air. Electrode negative is not standard for this work, and simply welding faster does not control the fume hazard."}, {"id": 322, "domain": "welding_processes", "question": "In a constant voltage GMAW system, what is the role of the wire feed speed setting in determining welding amperage, given that the operator does not directly dial in amperage on a typical constant voltage machine front panel?", "options": {"A": "Wire feed speed has no relationship to welding amperage.", "B": "Wire feed speed only sets the shielding gas flow rate.", "C": "Wire feed speed directly determines the welding amperage drawn.", "D": "Wire feed speed controls only the open circuit voltage."}, "correct": "C", "explanation": "On a constant voltage machine the wire feed speed setting directly determines the welding amperage drawn. Wire feed speed does not set gas flow or open circuit voltage. It is closely tied to amperage, so saying it has no relationship is wrong."}, {"id": 323, "domain": "welding_processes", "question": "A welder observes that increasing the carbon dioxide content in an argon carbon dioxide shielding gas mixture changes the weld characteristics. What general effect does adding more carbon dioxide to the mix have on penetration and spatter?", "options": {"A": "It decreases penetration and reduces spatter to nearly zero.", "B": "It eliminates penetration entirely and smooths the arc fully.", "C": "It increases penetration but also tends to increase spatter.", "D": "It has no measurable effect on penetration or spatter levels."}, "correct": "C", "explanation": "Adding more carbon dioxide to an argon mix increases penetration but also increases spatter because the arc becomes more globular. It does not reduce both penetration and spatter, and it does not eliminate penetration. Carbon dioxide content clearly does affect penetration and spatter, so no measurable effect is wrong."}, {"id": 325, "domain": "welding_processes", "question": "When grinding into a GMAW weld, an inspector finds a worm-track of elongated gas porosity just under the surface. Besides shielding gas loss, which base metal surface condition commonly causes this porosity when welding carbon steel with solid wire?", "options": {"A": "A correctly bevelled joint edge prepared to specification.", "B": "Perfectly clean and dry ground metal surface before welding.", "C": "Rust, mill scale, oil, paint, or moisture on the base metal.", "D": "An electrode positive polarity used on the carbon steel."}, "correct": "C", "explanation": "Rust, mill scale, oil, paint, or moisture on the base metal commonly causes porosity in solid-wire welds besides shielding gas loss. A perfectly clean, dry surface prevents porosity rather than causing it. A correctly bevelled edge and standard electrode positive polarity are good conditions, not porosity causes."}, {"id": 332, "domain": "welding_processes", "question": "A welder reads a procedure that specifies direct current electrode positive for GMAW. What practical benefit does electrode positive polarity provide that makes it the standard choice for solid wire GMAW on carbon steel applications?", "options": {"A": "It allows welding without any shielding gas coverage needed.", "B": "It produces the coolest possible arc for thin sheet only.", "C": "It gives a stable arc, good penetration, and minimal spatter.", "D": "It automatically doubles the wire feed speed during welding."}, "correct": "C", "explanation": "Direct current electrode positive gives a stable arc, good penetration, and minimal spatter, which is why it is standard for solid-wire GMAW on carbon steel. It is not the coolest arc reserved for thin sheet, and it cannot weld without shielding gas. It also does not double the wire feed speed."}, {"id": 342, "domain": "welding_processes", "question": "In the AWS electrode classification E71T-1, the number 7 stands for a specific mechanical property of the deposited weld metal. A welder reading this designation should understand that the 7 indicates a minimum tensile strength value. Which tensile strength does the 7 represent?", "options": {"A": "Seven percent maximum elongation across the tested weld sample.", "B": "Seventy thousand pounds per square inch minimum tensile strength.", "C": "Seven hundred amperes maximum recommended welding current for the wire.", "D": "Seventy degrees minimum preheat temperature measured in degrees Fahrenheit."}, "correct": "B", "explanation": "In E71T-1 the 7 means seventy thousand pounds per square inch minimum tensile strength of the deposited weld metal. It does not stand for percent elongation or a maximum welding current. It also has nothing to do with preheat temperature."}, {"id": 353, "domain": "welding_processes", "question": "The T-1 designation in flux-cored wires refers to a particular slag system that influences weldability and bead appearance. T-1 wires are known for a smooth arc, low spatter, and easy slag removal. Which slag system is associated with the T-1 flux-cored classification?", "options": {"A": "A cellulosic slag chosen mainly for deep penetrating pipe welds.", "B": "A rutile, titanium-dioxide-based slag giving smooth easy operation.", "C": "A basic, lime-based slag favoured for very high impact toughness.", "D": "A fluoride slag developed for welding aluminum bronze alloys."}, "correct": "B", "explanation": "The T-1 classification uses a rutile, titanium-dioxide-based slag that gives a smooth arc, low spatter, and easy slag removal. A cellulosic slag is used for deep penetrating pipe welds, not T-1. A basic lime slag and a fluoride slag belong to other classifications, not T-1."}, {"id": 363, "domain": "welding_processes", "question": "A flux-cored wire is marked E71T-11. This is a popular self-shielded, all-position wire used in light fabrication and on portable equipment. Field welders like it because it runs on small machines with no gas bottle. On which polarity is the common E71T-11 wire run?", "options": {"A": "Direct current electrode positive, reverse polarity, for deep penetration.", "B": "Alternating current to balance electrode and workpiece heating evenly.", "C": "Direct current electrode negative, straight polarity, as the wire requires.", "D": "Any polarity, since self-shielded wires ignore the current direction."}, "correct": "C", "explanation": "E71T-11 is a self-shielded all-position flux-cored wire that runs on direct current electrode negative (DCEN), also called straight polarity. It does not run on DCEP or alternating current. Self-shielded wires are not polarity neutral; the AWS A5.20 classification specifies DCEN for E71T-11 and the polarity must be set correctly before welding."}, {"id": 364, "domain": "welding_processes", "question": "Compared with solid-wire GMAW, flux-cored arc welding generally gives deeper penetration and much better gap bridging on thick structural steel. A welder must weigh these clear benefits against the drawbacks. Which disadvantage of FCAW compared to solid-wire GMAW should the welder reasonably expect?", "options": {"A": "FCAW cannot weld any steel thicker than six millimetres.", "B": "FCAW deposits weld metal far more slowly than solid GMAW wire.", "C": "FCAW produces slag that must be chipped and cleaned between passes.", "D": "FCAW requires alternating current that most shop machines lack."}, "correct": "C", "explanation": "Compared with solid-wire GMAW, FCAW produces slag that must be chipped and cleaned between passes, which is a real drawback. It can weld steel far thicker than six millimetres, so that limit is false. It deposits metal faster, not slower, and it does not require alternating current."}, {"id": 369, "domain": "welding_processes", "question": "A welder must select a flux-cored wire that gives good low-temperature impact toughness for a structure exposed to cold Canadian winters. Some classifications are tested for Charpy toughness at low temperatures. Which feature of a wire classification indicates rated impact toughness performance?", "options": {"A": "An impact-toughness designator listed after the main classification.", "B": "A higher tensile digit such as eight in place of seven.", "C": "A larger wire diameter stamped on the outside of the spool.", "D": "A copper coating applied to the surface of the tubular wire."}, "correct": "A", "explanation": "An impact-toughness designator listed after the main classification indicates the wire has rated Charpy toughness at a low temperature. A higher tensile digit relates to strength, not toughness rating, and wire diameter has nothing to do with toughness testing. A copper coating does not indicate impact performance."}, {"id": 375, "domain": "welding_processes", "question": "A welder reads CSA W48, the Canadian standard that classifies filler metals including flux-cored and metal-cored electrodes. Knowing which standard applies helps when choosing wire to match a W59 procedure. Which family of products does CSA W48 cover for the Red Seal welder?", "options": {"A": "Welding power sources and their electrical safety ratings.", "B": "Inspection and acceptance criteria for the completed welds.", "C": "Personal protective equipment requirements for all arc welders.", "D": "Filler metals and electrodes used in Canadian arc welding."}, "correct": "D", "explanation": "CSA W48 covers filler metals and electrodes used in Canadian arc welding, including flux-cored and metal-cored wires. It does not cover welding power sources or their electrical ratings. Inspection and acceptance criteria fall under other standards, and PPE rules are not the focus of W48."}, {"id": 376, "domain": "welding_processes", "question": "A welder runs gas-shielded flux-cored wire vertical-up and the bead is convex and ropey with poor tie-in at the toes. The procedure allows a slight weave. What technique adjustment most improves toe tie-in and bead profile on vertical-up FCAW fillets?", "options": {"A": "Increase travel speed greatly to flatten the convex bead crown.", "B": "Drop the voltage far below the recommended operating range.", "C": "Use a controlled weave with brief pauses at the joint sidewalls.", "D": "Switch to straight polarity to soften the molten pool flow."}, "correct": "C", "explanation": "Using a controlled weave with brief pauses at the joint sidewalls improves toe tie-in and bead profile on vertical-up FCAW fillets. Increasing travel speed greatly worsens tie-in, and dropping voltage far below range causes a ropey, convex bead. Straight polarity is the wrong setting for these wires."}, {"id": 377, "domain": "welding_processes", "question": "Self-shielded flux-cored wires often contain strong denitriding and deoxidizing elements such as aluminum. These reactive elements protect the molten weld in the complete absence of any external gas shield. Why are these particular reactive elements deliberately added to the core of a self-shielded FCAW electrode?", "options": {"A": "To combine with nitrogen and oxygen so they do not embrittle the weld.", "B": "To increase the wire melting point and slow deposition.", "C": "To act as the sole electrical conductor inside the tube.", "D": "To produce a thicker copper coating on the outer surface."}, "correct": "A", "explanation": "Reactive elements like aluminum combine with nitrogen and oxygen so they do not embrittle the weld, protecting it without an external gas shield. They are not added to raise the melting point and slow deposition. They are not the sole electrical conductor, and they do not produce a copper coating."}, {"id": 391, "domain": "welding_processes", "question": "A welder must qualify a procedure where toughness at minus twenty-nine degrees Celsius is required. He compares an E71T-1 with a higher-toughness E71T-9 of the same strength. What is the practical reason a fabricator might specify the T-9 over the T-1 for this service?", "options": {"A": "The T-9 offers improved low-temperature impact toughness for cold service.", "B": "The T-9 deposits at a far lower rate, reducing distortion.", "C": "The T-9 is self-shielded and needs no shielding gas at all.", "D": "The T-9 runs only on straight polarity, simplifying machine setup."}, "correct": "A", "explanation": "An E71T-9 offers improved low-temperature impact toughness over an E71T-1, so it suits service requiring toughness at minus twenty-nine degrees Celsius. The T-9 is not self-shielded and does not deposit at a far lower rate as its advantage. It does not run only on straight polarity."}, {"id": 393, "domain": "welding_processes", "question": "Gas-shielded flux-cored wire commonly runs with either carbon dioxide or an argon and carbon dioxide mix. The choice of shielding gas clearly affects both penetration and spatter levels. Compared with the argon-rich mix, what does pure carbon dioxide shielding generally give on a gas-shielded FCAW weld?", "options": {"A": "No penetration change but a complete elimination of slag.", "B": "Less penetration, more spatter, and a much smoother fine spray arc.", "C": "Deeper penetration with more spatter and a harsher globular arc.", "D": "A guaranteed large increase in low-temperature impact toughness."}, "correct": "C", "explanation": "Pure carbon dioxide on gas-shielded FCAW gives deeper penetration with more spatter and a harsher globular arc compared with an argon-rich mix. It does not give less penetration with a fine smooth spray arc, which describes the argon-rich blend. It does not eliminate slag or guarantee a large toughness increase."}, {"id": 398, "domain": "welding_processes", "question": "A welder evaluates whether to choose FCAW or SMAW for a windy outdoor structural job that still needs decent productivity. Both processes resist wind reasonably well. Which factor most favours self-shielded FCAW over SMAW for this windy outdoor structural work?", "options": {"A": "Self-shielded FCAW combines wind tolerance with higher continuous deposition.", "B": "SMAW feeds wire continuously, so it deposits metal much faster.", "C": "SMAW never produces slag, removing all cleanup from the job.", "D": "Self-shielded FCAW needs a gas bottle that SMAW cannot use outdoors."}, "correct": "A", "explanation": "Self-shielded FCAW combines wind tolerance with higher continuous deposition than SMAW, which favours it for windy outdoor structural work. SMAW does not feed wire continuously, so it does not deposit metal much faster. SMAW does produce slag, and self-shielded FCAW does not need a gas bottle."}, {"id": 409, "domain": "cutting_and_gouging", "question": "After air carbon arc gouging a section of steel, a welder must prepare the gouged surface before depositing new weld metal. Carbon arc gouging can leave a thin carbon-rich layer. What step properly conditions the gouged groove so the repair weld does not develop hard brittle spots?", "options": {"A": "Apply a thin oil film to shield the groove before welding.", "B": "Wire brush the loose dust and weld over it immediately.", "C": "Quench the hot groove with water then weld at once.", "D": "Grind the gouged surface lightly to remove carbon pickup."}, "correct": "D", "explanation": "Light grinding removes the carbon-enriched skin left by the carbon electrode so the repair weld stays sound and ductile. Wire brushing alone leaves carbon pickup that can cause hard brittle zones. Water quenching can crack the steel and an oil film adds hydrogen and contamination that promote porosity and cracking."}, {"id": 412, "domain": "cutting_and_gouging", "question": "Using the cutting diagram shown, a welder is selecting the cutting oxygen pressure for oxy-fuel cutting of 50 mm thick steel. Manufacturer charts list pressures by plate thickness and tip size. If the cutting oxygen pressure is set too high for the tip, what cutting defect is the operator most likely to see?", "options": {"A": "A narrow clean kerf with very little slag at all.", "B": "Excessive drag lines slanting badly behind the cut.", "C": "A cut that stalls and refuses to penetrate the plate.", "D": "A turbulent ragged kerf with a wide bell-mouthed top."}, "correct": "D", "explanation": "Excess cutting oxygen pressure makes the stream turbulent, widening the kerf and flaring the top edge into a bell-mouth shape. A clean narrow kerf is the sign of correct pressure, not too high. Stalled penetration and severe trailing drag lines come from too little oxygen or too fast travel, not excessive pressure.", "image": "question_images/q412.png"}, {"id": 426, "domain": "cutting_and_gouging", "question": "A welder sets up to bevel a pipe end for a groove weld using a hand-held oxy-fuel torch and a pipe bevelling guide ring. To produce a uniform bevel angle around the full circumference of the pipe, how should the welder manage the cut around the curve?", "options": {"A": "Keep the torch fixed and rotate the pipe past the flame.", "B": "Hold the torch angle to the guide and follow the ring fully around.", "C": "Cut halfway then flip the torch hand to finish the second half.", "D": "Vary the angle around the pipe to match the changing curve."}, "correct": "B", "explanation": "Riding the torch against the bevelling guide ring at a fixed angle and following it all the way around keeps the bevel uniform on the pipe. Rotating a heavy pipe past a fixed torch is awkward and inconsistent. Flipping hands midway or varying the angle around the curve produces an uneven bevel that fails the weld prep."}, {"id": 430, "domain": "cutting_and_gouging", "question": "A welder must select gas pressures and a tip for oxy-acetylene cutting and recalls that acetylene has a safe working pressure limit. To avoid the danger of unstable decomposition of the fuel gas, what is the maximum acetylene working pressure the welder must never exceed?", "options": {"A": "Acetylene may be used safely up to about 100 kPa working.", "B": "Acetylene may run to about 200 kPa for thick plate cutting.", "C": "Acetylene must never exceed about 103 kPa or 15 psi working.", "D": "Acetylene has no working pressure limit for cutting work."}, "correct": "C", "explanation": "Acetylene becomes unstable and can decompose explosively above roughly 103 kPa, or 15 psi, so that is the working pressure limit the welder must never exceed. Running it higher for thick plate is dangerous, not allowed. The claim that acetylene has no working pressure limit is false and unsafe."}, {"id": 431, "domain": "cutting_and_gouging", "question": "A welder is gouging with air carbon arc and the carbon electrode is burning back very fast and producing a rough irregular groove. The amperage is set near the lower end of the range for the electrode size. What adjustment most directly improves the gouging action?", "options": {"A": "Lower the amperage further to slow the electrode burn-off.", "B": "Reduce the air pressure so less metal is blown away.", "C": "Extend the electrode stickout far past the holder jaws.", "D": "Raise the amperage into the proper range for the electrode size."}, "correct": "D", "explanation": "Raising the amperage into the correct range for the electrode diameter gives a stable arc and a smooth even gouge. Lowering amperage further weakens an already unstable arc and worsens the groove. Cutting air pressure leaves molten metal in the cut, and excessive stickout overheats the electrode and increases burn-back."}, {"id": 446, "domain": "cutting_and_gouging", "question": "A welder is cutting in a position where the oxy-fuel cut must be made overhead on a beam. Slag falls and the torch is held inverted. To make a sound overhead cut safely and keep slag from blowing back, how should the torch and body position be managed?", "options": {"A": "Stand directly under the cut for the best torch control.", "B": "Hold the torch flat against the beam and cut slowly.", "C": "Stand to the side and angle the torch so slag falls clear.", "D": "Cut with maximum oxygen so slag is blown straight down."}, "correct": "C", "explanation": "Standing to the side and angling the torch so the molten slag falls clear of the operator makes the overhead cut safe and clean. Standing directly under the cut puts the welder in the path of falling slag. Holding the torch flat or blasting oxygen does not control where the slag goes and adds hazard."}, {"id": 447, "domain": "cutting_and_gouging", "question": "A welder must true up a saddle cut on a pipe-to-pipe joint after rough oxy-fuel cutting left an uneven fit. The branch pipe must seat tightly on the main run. What tool and method best refine the contoured saddle cut to achieve a tight fit-up?", "options": {"A": "Force the branch down hard to crush it into the gaps.", "B": "Fill the gaps with extra weld metal during the root pass.", "C": "Add shims under the high spots to level the branch pipe.", "D": "Grind the saddle to the contour and test-fit until it seats."}, "correct": "D", "explanation": "Grinding the saddle to match the run pipe contour and repeatedly test-fitting brings the branch into a tight seat for a sound joint. Forcing the branch down distorts it without closing the gaps. Filling large gaps with weld or shimming high spots creates weak joints and poor fit-up that fail inspection."}, {"id": 456, "domain": "cutting_and_gouging", "question": "A welder lights the cutting torch and the flame produces a feathery white plume extending past the inner cone, with a slightly sooty appearance. To convert this carburizing flame to the neutral flame needed for cutting steel, what adjustment should the welder make at the torch?", "options": {"A": "Add more oxygen until the feather draws back into the inner cone.", "B": "Reduce the oxygen flow until the inner cone grows longer.", "C": "Add more acetylene to brighten the outer envelope of the flame.", "D": "Close the preheat oxygen and reopen the acetylene valve fully."}, "correct": "A", "explanation": "A carburizing flame has excess fuel that shows as a white acetylene feather beyond the inner cone. Adding preheat oxygen burns off that excess fuel and pulls the feather back until only the sharp inner cone remains. That clean defined cone marks the neutral flame suitable for cutting steel."}, {"id": 465, "domain": "cutting_and_gouging", "question": "A welder sets up a track-mounted oxy-fuel cutting machine to make long straight production cuts on plate. Compared to hand cutting, what is the main advantage that justifies setting up the machine torch on a motorized track for this work?", "options": {"A": "It eliminates the need to preheat the plate before cutting.", "B": "It allows much higher acetylene pressure than a hand torch.", "C": "It removes the requirement for eye and face protection entirely.", "D": "It maintains constant speed and standoff for a uniform kerf."}, "correct": "D", "explanation": "A motorized track carries the torch at a steady set speed while holding a fixed standoff above the plate. This consistency produces a straight uniform kerf that hand cutting cannot match over long distances. Preheat and personal protection are still required exactly as with hand cutting."}, {"id": 466, "domain": "cutting_and_gouging", "question": "A welder must cut cast iron, which contains high carbon and silicon and does not cut cleanly with a standard oxy-fuel steel cutting technique. Which modification to the oxy-fuel technique improves results when severing cast iron sections in a repair situation?", "options": {"A": "Use a sharp neutral flame and travel as fast as possible.", "B": "Hold the tip far from the work to avoid melting the casting.", "C": "Lower the preheat and raise cutting oxygen pressure sharply.", "D": "Use an oscillating tip motion with extra preheat and slower travel."}, "correct": "D", "explanation": "Cast iron resists clean oxygen cutting because its carbon and silicon hinder the oxidizing reaction that severs steel. Oscillating the tip with heavier preheat and slower travel adds enough heat to keep the molten reaction going through the section. This crude but effective method lets the welder sever castings during repair work."}, {"id": 474, "domain": "welding_processes", "question": "Based on the weld cross-section shown, a welder running FCAW with a gas-shielded flux-cored wire on a windy outdoor site notices porosity scattered through the welds. The wire and machine settings are correct. Which on-site condition is the most likely cause of the porosity, and what is the practical fix?", "options": {"A": "Travel angle too steep; flatten the gun toward the work.", "B": "Wire feed speed too low; increase the feed rate sharply.", "C": "Wind blowing the shielding gas away; set up wind screens.", "D": "Contact tip worn; the arc length is wandering randomly."}, "correct": "C", "explanation": "Gas-shielded FCAW relies on an external shielding gas that wind easily disperses, leaving the molten pool exposed to air and causing porosity. Erecting wind screens around the work restores the shielding envelope and clears the defect. Switching to a self-shielded wire is the other common outdoor solution.", "image": "question_images/q474.png"}, {"id": 483, "domain": "welding_processes", "question": "A welder makes a multi-pass groove weld in thick plate using SMAW and must clean between passes. Slag left from the previous pass can become trapped and cause inclusions. What is the correct interpass procedure before depositing the next bead in the groove?", "options": {"A": "Leave thin slag in place to preheat the next pass.", "B": "Deposit the next pass immediately over the hot slag layer.", "C": "Add extra current to burn through any remaining slag.", "D": "Chip and wire brush all slag from the previous bead first."}, "correct": "D", "explanation": "Each completed pass must have its slag chipped and wire brushed off before the next bead is laid. Slag left in the groove gets trapped under the new metal and forms slag inclusions that weaken the joint and fail inspection. Thorough interpass cleaning is essential for sound multi-pass welds."}, {"id": 494, "domain": "welding_processes", "question": "A welder must control distortion while welding a long butt joint on thin plate. Continuous welding builds heat and warps the plate. Which welding sequence technique reduces overall distortion by spreading heat input along the joint rather than concentrating it?", "options": {"A": "Use back-step or skip welding in short alternating segments.", "B": "Tack only the centre and weld outward in one pass.", "C": "Weld the entire joint in one direction with heavy current.", "D": "Weld one continuous pass quickly from end to end."}, "correct": "A", "explanation": "Back-step and skip welding break the joint into short segments welded in an alternating order so heat is distributed rather than concentrated. Spreading the heat input this way reduces the localized expansion and contraction that warps thin plate. A single continuous pass concentrates heat and produces the worst distortion."}, {"id": 500, "domain": "welding_processes", "question": "A welder is setting GTAW amperage with a foot pedal on a thin stainless part. The pedal controls current during welding. How does using the foot pedal help the welder manage heat and the weld pool through the start, body, and finish of the weld?", "options": {"A": "It locks the current at one fixed value for the whole weld.", "B": "It lets the welder ramp current up and down to control heat.", "C": "It feeds filler wire automatically as the pedal is pressed.", "D": "It switches polarity between AC and DC during the weld."}, "correct": "B", "explanation": "The foot pedal gives the welder live control of welding current throughout the weld. This lets the welder ramp up to establish the pool, hold steady through the body, and taper off to fill the crater and avoid burn-through at the finish. That control is especially valuable on thin stainless where heat must be managed carefully."}, {"id": 503, "domain": "cutting_and_gouging", "question": "A plasma arc cutting machine is leaving heavy dross on the bottom edge of 6 mm stainless steel cuts. The amperage matches the consumable rating and the gas pressure is correct. Which change to the cutting parameters is the best first step to reduce the bottom dross?", "options": {"A": "Lower the cutting amperage well below the consumable rating value.", "B": "Increase the standoff distance between the torch tip and plate.", "C": "Reduce the gas flow rate so the plasma jet narrows considerably.", "D": "Increase the cutting travel speed toward the optimum range."}, "correct": "D", "explanation": "Low dross on the bottom of a plasma cut is usually caused by travelling too slowly, which lets molten metal fuse to the underside. Increasing speed toward the recommended range produces a cleaner, dross-free edge. Excessive standoff or wrong amperage tends to worsen cut quality rather than fix bottom dross."}, {"id": 504, "domain": "cutting_and_gouging", "question": "A welder must pierce a hole in the centre of a 16 mm steel plate using an oxy-fuel cutting torch before cutting an internal opening. To pierce safely without blowing molten slag back onto the tip, what is the correct piercing procedure?", "options": {"A": "Hold the tip flat on the surface and open the oxygen lever immediately.", "B": "Use only the preheat flames to melt completely through the plate.", "C": "Angle and raise the tip slightly, then slowly open the cutting oxygen.", "D": "Preheat from the underside, then plunge the tip into the plate."}, "correct": "C", "explanation": "Piercing begins by preheating a spot, then raising and slightly angling the tip so blown slag is directed away from the tip orifices. The cutting oxygen is opened slowly so the jet penetrates progressively rather than ejecting slag straight back. Holding the tip flat and opening oxygen fast clogs the tip with molten metal."}, {"id": 509, "domain": "welding_processes", "question": "Based on the weld cross-section shown, a welder using FCAW with a gas-shielded flux-cored wire is producing welds with worm-track porosity appearing as channels under the slag. The gas flow and wire are correct. Which procedural change is most likely to eliminate this worm-tracking defect?", "options": {"A": "Switch to a smaller diameter wire and double the wire feed speed.", "B": "Increase the travel speed dramatically to outrun the escaping gas.", "C": "Reduce the arc voltage slightly and lower the travel speed somewhat.", "D": "Change polarity to electrode negative to cool the weld puddle."}, "correct": "C", "explanation": "Worm-track porosity in FCAW often comes from excessive voltage and gases trapped by a fast-freezing slag. Lowering the voltage slightly and slowing travel lets the trapped gases escape before the slag solidifies over the bead. Most gas-shielded flux-cored wires also require electrode-positive polarity, so switching to negative would worsen results.", "image": "question_images/q509.png"}, {"id": 511, "domain": "welding_processes", "question": "A welder must store E7018 low-hydrogen electrodes that were removed from a sealed container earlier in the shift. To keep the electrodes within code limits and prevent hydrogen-related cracking, what is the correct procedure for handling these exposed electrodes?", "options": {"A": "Leave them on the bench and reuse them whenever they are needed.", "B": "Soak them in clean water to remove any surface contamination present.", "C": "Store them in a heated rod oven at the recommended holding temperature.", "D": "Place them in a freezer to lock out atmospheric moisture absorption."}, "correct": "C", "explanation": "Low-hydrogen E7018 electrodes absorb moisture from the air, so once removed from sealed packaging they must be kept in a heated holding oven. The oven holds them at a controlled temperature that prevents moisture pickup and the hydrogen cracking it can cause. Wetting or freezing them adds moisture and ruins the low-hydrogen coating."}, {"id": 518, "domain": "welding_processes", "question": "A GTAW welder is welding thin-walled stainless tubing and the backside of the weld is turning grey and grainy, showing oxidation. The face side looks acceptable. Which procedure should the welder use to protect the root and produce a clean, bright underside?", "options": {"A": "Increase the torch argon flow until the back side stops oxidizing.", "B": "Add filler metal to the root to cover the oxidized surface area.", "C": "Weld faster so the back side has no time to oxidize at all.", "D": "Use a backing or purge gas inside the tube to shield the root."}, "correct": "D", "explanation": "A grey, sugared underside on stainless GTAW means the hot root is oxidizing from exposure to air. A backing or purge gas, usually argon, is flowed inside the tube to displace oxygen and protect the root as it solidifies. Torch-side gas cannot reach the back of the weld, so a separate purge is required."}, {"id": 530, "domain": "welding_processes", "question": "A welder is GMAW welding and the gun nozzle keeps filling with spatter, which disrupts the gas shield and causes porosity. The parameters are reasonable for the wire. Which routine procedure best maintains shielding gas coverage during a long production run?", "options": {"A": "Clean the nozzle regularly and apply anti-spatter compound to it.", "B": "Increase the gas flow far above normal to blow spatter out of the nozzle.", "C": "Pull the nozzle back off the contact tip to let spatter fall away.", "D": "Lower the voltage drastically so no spatter is produced at all."}, "correct": "A", "explanation": "Spatter buildup is managed by routinely cleaning the nozzle and using anti-spatter compound or nozzle gel so spatter releases easily. A clogged nozzle blocks even gas flow and lets air reach the puddle, causing porosity. Simply raising gas flow creates turbulence, and pulling the nozzle back disturbs the shielding envelope."}, {"id": 533, "domain": "welding_processes", "question": "Based on the weld cross-section shown, a welder is troubleshooting porosity in SMAW welds made with E7018 on a humid day. The electrodes were left out of the oven overnight. Considering the cause of the porosity, what is the correct corrective procedure before continuing to weld this joint?", "options": {"A": "Apply more electrode pressure to push the gas out of the molten pool.", "B": "Increase travel speed so trapped gas escapes before the bead freezes.", "C": "Lower the amperage to keep the puddle calmer and reduce gas pickup.", "D": "Rebake or replace the electrodes and grind out the porous weld metal."}, "correct": "D", "explanation": "Porosity from E7018 left out overnight comes from moisture absorbed into the coating, which releases hydrogen during welding. The fix is to rebake the electrodes to the specified temperature or use fresh ones, and grind out the porous weld before rewelding. Adjusting travel or amperage cannot remove moisture already in the flux coating.", "image": "question_images/q533.png"}, {"id": 536, "domain": "welding_processes", "question": "A welder must tack a thin sheet metal assembly with GMAW without burning through or distorting it. The parts are clamped in a jig. Which procedure best produces sound tacks on thin material while keeping heat input and distortion low across the assembly?", "options": {"A": "Use long continuous tacks at high current to fuse the joint quickly.", "B": "Use maximum wire feed and voltage so each tack sets instantly.", "C": "Make small, evenly spaced tacks and skip around the joint as you go.", "D": "Place all tacks at one end first, then weld continuously to the other."}, "correct": "C", "explanation": "Thin sheet is tacked with small tacks spaced evenly and placed in a skip or staggered pattern to spread the heat. This keeps localized heat input low so the part does not warp or burn through. Long high-current tacks or clustering them at one end concentrate heat and pull the assembly out of shape."}, {"id": 546, "domain": "welding_processes", "question": "A welder is GMAW welding out of position and switches from short-circuit to a controlled waveform mode for better out-of-position control. Considering transfer modes, which GMAW transfer is best suited for all-position welding with good puddle control on steel?", "options": {"A": "Globular transfer.", "B": "Submerged transfer.", "C": "Conventional spray transfer.", "D": "Short-circuit or pulsed spray transfer, for a controllable low-heat puddle."}, "correct": "D", "explanation": "Short-circuit and pulsed spray transfer give a small, controllable puddle with lower average heat, making them well suited to out-of-position GMAW. Conventional spray transfer runs too hot and fluid to hold in vertical or overhead positions. Globular transfer is uncontrolled and spattery, and submerged arc is a flat and horizontal process only."}, {"id": 553, "domain": "welding_processes", "question": "A welder is GTAW welding a fillet and the bead is too cold with poor fusion at the root of the joint. The current is set near the low end for the tungsten. Considering the heat needed for a fillet root, which adjustment best improves fusion at the joint root?", "options": {"A": "Increase travel speed so the concentrated arc reaches the root sooner.", "B": "Lengthen the arc so the heat spreads over a wider surface area.", "C": "Add filler metal faster to physically force fusion at the cold root.", "D": "Increase the current and direct the arc more toward the joint root."}, "correct": "D", "explanation": "Cold root fusion in a GTAW fillet means the arc is not delivering enough heat into the corner of the joint. Raising the current and aiming the arc into the root gives the energy needed to fuse both members at the bottom of the joint. A longer arc, more filler, or faster travel all reduce the heat reaching the root."}, {"id": 557, "domain": "welding_processes", "question": "A welder is troubleshooting tungsten spitting and erratic arc on AC GTAW of aluminum. The balance control sets the ratio of cleaning to penetration half cycles. Considering this control, what happens when the welder increases the cleaning (electrode positive) portion?", "options": {"A": "Penetration increases sharply while the tungsten runs much cooler.", "B": "More oxide cleaning occurs but the tungsten heats and may need a larger size.", "C": "The cleaning action stops and the arc shifts fully to penetration only.", "D": "The shielding gas requirement drops because cleaning replaces gas coverage."}, "correct": "B", "explanation": "On AC GTAW the balance control sets how much of each cycle is electrode positive, which provides oxide cleaning. Increasing the cleaning portion removes more oxide but puts more heat into the tungsten, so a larger or balled tungsten may be needed. More cleaning reduces penetration, the opposite of increasing the electrode-negative portion."}, {"id": 562, "domain": "welding_processes", "question": "When sharpening a tungsten electrode for direct current electrode negative welding on stainless steel, a welder grinds the point on a dedicated wheel. To produce a stable, focused arc and avoid contamination, in which direction should the grinding marks run relative to the electrode?", "options": {"A": "Across the electrode width so marks circle around the tip.", "B": "Lengthwise along the electrode axis toward the pointed tip.", "C": "At a shallow forty five degree spiral toward the point.", "D": "Randomly, since grinding direction has no effect on arc."}, "correct": "B", "explanation": "Grinding marks should run lengthwise along the electrode axis toward the point so the arc follows a smooth path and the tip stays focused and clean. Circular marks across the width make the arc wander and can flake off into the weld. A 45 degree spiral also crosses the tip path, and grinding direction does in fact affect arc behavior."}, {"id": 564, "domain": "welding_processes", "question": "Two percent thoriated tungsten electrodes have long been popular for direct current welding of carbon steel and stainless steel. According to standard AWS color identification used in welding supply, what painted band color marks a two percent thoriated tungsten electrode?", "options": {"A": "A red colour band painted on the electrode end.", "B": "A gold or orange colour band painted on the end.", "C": "A green colour band painted on the electrode end.", "D": "A grey colour band painted on the electrode end."}, "correct": "A", "explanation": "Two percent thoriated tungsten is marked with a red band under standard AWS color coding. Green marks pure tungsten and gold or orange marks other oxide types, so those are wrong here. Grey is also used for a different electrode, so red is the correct identifier for thoriated tungsten."}, {"id": 566, "domain": "welding_processes", "question": "During TIG welding of titanium and reactive metals, post-flow shielding gas continues to flow after the arc is extinguished. A welder asks the supervisor why post-flow matters on the finished weld. What is the main purpose of an adequate post-flow setting?", "options": {"A": "It cools the torch handle and the welding cables faster.", "B": "It purges argon from the regulator before the next start.", "C": "It recharges the high frequency unit between separate welds.", "D": "It shields the hot tungsten and weld pool from oxidation."}, "correct": "D", "explanation": "Adequate post-flow keeps shielding gas over the hot tungsten and weld pool after the arc stops, protecting them from oxidation as they cool. It is not meant to cool the torch handle or cables. It does not recharge the high frequency unit, and its job is shielding rather than purging the regulator."}, {"id": 570, "domain": "welding_processes", "question": "Lanthanated tungsten electrodes have grown popular as a general replacement for thoriated types because they avoid radioactive thorium. A welder needs to grab the correct electrode from a colour-coded rack. Which painted band colour identifies a two percent lanthanated tungsten electrode?", "options": {"A": "A black colour band painted on the electrode end.", "B": "A blue colour band painted on the electrode end.", "C": "A white colour band painted on the electrode end.", "D": "A yellow colour band painted on the electrode end."}, "correct": "B", "explanation": "Two percent lanthanated tungsten is identified by a blue band under standard color coding. Black marks a different lanthanated level and white and yellow mark other electrode types. So blue is the correct band color for two percent lanthanated tungsten."}, {"id": 573, "domain": "welding_processes", "question": "A welder TIG welding aluminum on alternating current sees the tungsten forming a small molten ball at the tip during welding. The machine is a transformer style AC unit without advanced balance control. For pure tungsten on AC aluminum, this balled end is generally considered which of the following?", "options": {"A": "A defect requiring immediate regrinding to a sharp point.", "B": "Proof the electrode is contaminated by filler metal.", "C": "A sign the argon shielding gas has fully failed.", "D": "A normal and acceptable condition for AC aluminum welding."}, "correct": "D", "explanation": "A small molten ball forming on pure tungsten during AC aluminum welding is a normal and accepted condition that helps maintain a stable arc. It is not a defect needing immediate regrinding to a point. A balled tip does not mean the argon has failed, and it is not proof of contamination by filler metal."}, {"id": 574, "domain": "welding_processes", "question": "A welder accidentally dips the tungsten into the molten weld pool while TIG welding carbon steel. The arc becomes erratic and the bead turns dirty. According to good practice, what is the correct response before continuing to weld this joint?", "options": {"A": "Increase the argon flow rate to burn off the contamination.", "B": "Switch the machine from direct current to alternating current mode.", "C": "Stop and regrind the contaminated tungsten before welding again.", "D": "Continue welding since the heat will clean the tungsten."}, "correct": "C", "explanation": "After dipping the tungsten into the pool you must stop and regrind the contaminated tip before continuing, since the dirty tungsten causes an erratic arc and dirty bead. Raising the argon flow will not burn off the contamination. Switching to AC does not fix a contaminated DC steel weld, and continuing will only spread the contamination."}, {"id": 584, "domain": "welding_processes", "question": "Helium has different physical properties than argon, and this affects how a welder sets the gas. Compared to welding with pure argon, what generally must be done with the shielding gas flow rate when switching to a helium rich mixture for TIG?", "options": {"A": "The flow rate must usually be increased because helium is lighter.", "B": "The flow rate must usually be decreased because helium is heavier.", "C": "The flow rate stays exactly the same for either gas.", "D": "The gas flow must be turned off during the post-flow."}, "correct": "A", "explanation": "When switching to a helium rich mixture the flow rate usually must be increased because helium is lighter than air and rises away from the pool. It is not decreased on the idea that helium is heavier, since helium is lighter. The flow does not stay exactly the same, and the gas is not turned off during post-flow."}, {"id": 585, "domain": "welding_processes", "question": "A welder lifts the torch and ends the arc on a stainless tube, but the bright weld immediately turns straw coloured then blue at the crater. The base looked clean before welding. Which shielding fault most directly explains this oxidized crater colour?", "options": {"A": "Filler rod was fed too slowly during the weld.", "B": "Tungsten was ground to too sharp a point.", "C": "Insufficient post-flow allowed the hot crater to oxidize.", "D": "Amperage was set slightly below the recommended value."}, "correct": "C", "explanation": "Straw then blue oxidation colors at the crater of a clean stainless weld come from insufficient post-flow letting the hot crater oxidize before it cools under gas. Feeding filler too slowly does not cause crater oxidation colors. A too-sharp tungsten and slightly low amperage do not directly explain the oxidized crater the way lost shielding does."}, {"id": 586, "domain": "welding_processes", "question": "A welder is told to weld a thick copper bus bar and needs maximum arc heat from the TIG process. Pure argon alone struggles to give enough heat for the conductive copper. Which shielding gas choice would best raise the available arc heat?", "options": {"A": "Pure argon shielding set at a reduced flow rate.", "B": "An argon oxygen mixture used for spray transfer steel.", "C": "Pure carbon dioxide shielding for deeper copper penetration.", "D": "An argon helium mixture with a higher helium percentage."}, "correct": "D", "explanation": "An argon helium mixture with a higher helium percentage gives the most arc heat, which is what thick conductive copper needs. Pure argon at reduced flow gives less heat, not more. Pure carbon dioxide and an argon oxygen spray mix are GMAW gases that are wrong for manual TIG on copper."}, {"id": 588, "domain": "welding_processes", "question": "A welder wants to verify the polarity convention for TIG welding aluminum and stainless steel before starting a shift. In standard manual TIG practice taught in trade school, which statement correctly pairs each metal with its usual welding current type used in Canadian shops?", "options": {"A": "Aluminum uses direct current negative; stainless uses alternating current.", "B": "Aluminum uses alternating current; stainless uses direct current negative.", "C": "Both aluminum and stainless always use direct current positive.", "D": "Both aluminum and stainless always use alternating current only."}, "correct": "B", "explanation": "In standard TIG practice aluminum uses alternating current for its oxide cleaning and stainless uses direct current electrode negative for steady penetration. Option A reverses the two metals, which is wrong. Both metals do not always use DCEP, and both do not always use AC only, so the correct pairing is AC for aluminum and DCEN for stainless."}, {"id": 590, "domain": "welding_processes", "question": "A welder is preparing to TIG weld and reads that thoriated tungsten contains thorium, a low level radioactive material. While the radiation risk during welding is low, what is the most important practical hazard control when grinding thoriated tungsten electrodes?", "options": {"A": "Wear gloves to prevent the thorium from staining the hands.", "B": "Soak the electrode in water before any grinding begins.", "C": "Grind only on alternating current powered bench wheels.", "D": "Use local exhaust ventilation to avoid inhaling grinding dust."}, "correct": "D", "explanation": "The most important control when grinding thoriated tungsten is using local exhaust ventilation to avoid inhaling the radioactive grinding dust. Wearing gloves to stop staining does not address the inhalation hazard. Grinding on an AC powered wheel makes no difference, and soaking the electrode in water is not a recognized control."}, {"id": 595, "domain": "welding_processes", "question": "A welder sets up TIG equipment and the supervisor asks what AC balance control adjusts on a modern inverter machine welding aluminum. AC balance shifts the ratio of the two half cycles. What does increasing the cleaning portion of AC balance mainly do?", "options": {"A": "It eliminates the need for any argon shielding gas.", "B": "It deepens penetration while keeping the tungsten very cool.", "C": "It increases oxide removal but adds heat to the tungsten.", "D": "It converts the machine output to direct current automatically."}, "correct": "C", "explanation": "Increasing the cleaning portion of the AC balance removes more oxide but also puts more heat into the tungsten, so it can overheat the tip. It does not deepen penetration while keeping the tungsten very cool, since more cleaning heats the tungsten. It does not eliminate the need for argon shielding, and it does not convert the output to DC."}, {"id": 597, "domain": "welding_processes", "question": "A welder TIG welding carbon steel reaches for a common filler rod that contains extra deoxidizers to tolerate some surface mill scale and produce sound welds. Which carbon steel filler rod classification is the typical general purpose choice for this kind of work?", "options": {"A": "An ER70S-6 carbon steel filler rod for this job.", "B": "An ER4043 aluminum silicon filler rod for this job.", "C": "An ER308L stainless steel filler rod for this job.", "D": "An ERNi nickel filler rod intended for cast iron."}, "correct": "A", "explanation": "ER70S-6 is the typical general purpose carbon steel TIG filler because its extra deoxidizers tolerate some mill scale and still give sound welds. ER308L is a stainless filler and ER4043 is an aluminum filler, so neither matches carbon steel. ERNi nickel filler is for cast iron, not general carbon steel work."}, {"id": 604, "domain": "welding_processes", "question": "A welder TIG welding outdoors finds the welds porous and oxidized despite normal gas flow on the regulator. A light wind is blowing across the work area. Which factor most directly explains the loss of shielding and the poor weld quality?", "options": {"A": "Wind blowing the argon shielding away from the weld pool.", "B": "The tungsten being ground slightly too sharp for the job.", "C": "Using direct current electrode negative instead of positive.", "D": "Filler rod diameter being one size too small overall."}, "correct": "A", "explanation": "The answer is A because wind blows the argon shielding away from the pool, letting air in and causing porous, oxidized welds even when the regulator reads normal flow. A slightly sharp tungsten or a smaller filler rod would not strip the shielding gas. DCEN is the correct polarity for steel TIG, so it is not the cause."}, {"id": 612, "domain": "welding_processes", "question": "A welder sets the high frequency mode on a TIG machine welding aluminum on AC. On many AC machines the high frequency stays active continuously rather than only at start. Why is continuous high frequency commonly used during AC aluminum TIG welding?", "options": {"A": "To cool the tungsten between each half cycle automatically.", "B": "To restabilize the arc each time the AC current reverses.", "C": "To raise the argon flow rate during the cleaning half.", "D": "To convert the alternating current into direct current output."}, "correct": "B", "explanation": "The answer is B because on AC the current passes through zero and reverses each half cycle, so continuous high frequency restabilizes and re-strikes the arc at each reversal. High frequency does not cool the tungsten or raise argon flow. It does not convert AC into DC, so D is wrong."}, {"id": 613, "domain": "welding_processes", "question": "A welder reviews how electrode negative affects the weld profile when joining stainless steel parts. Direct current electrode negative is the standard polarity for steel and stainless TIG welding work. Compared with electrode positive, what bead profile does DCEN typically produce on these metals during welding?", "options": {"A": "A wide shallow bead with strong surface oxide cleaning.", "B": "A narrow deep penetrating bead with little oxide cleaning.", "C": "A bead identical in shape to electrode positive welding.", "D": "No penetration at all regardless of amperage selected."}, "correct": "B", "explanation": "The answer is B because DCEN puts most heat into the work, giving a narrow deep penetrating bead with little oxide cleaning on steel and stainless. Electrode positive is what produces the wide shallow bead with strong cleaning, so A is reversed. DCEN and DCEP give different profiles and DCEN does penetrate, ruling out C and D."}, {"id": 619, "domain": "welding_processes", "question": "A welder finds the TIG tungsten keeps getting contaminated even with good technique. Investigation shows the argon hose has a tiny leak drawing in air on the suction side near a fitting. How would this hidden air leak most likely show up in the welds?", "options": {"A": "Deeper penetration and a brighter, cleaner weld bead.", "B": "Porosity, oxidation, and rapid tungsten contamination during welding.", "C": "The machine refusing to start the high frequency arc.", "D": "A cooler tungsten that lasts far longer between grinds."}, "correct": "B", "explanation": "The answer is B because a leak on the suction side draws air into the argon line, causing porosity, oxidation, and rapid tungsten contamination. Air contamination ruins the weld rather than improving penetration or brightness, so A is wrong. The leak does not stop high frequency starting or make the tungsten last longer, ruling out C and D."}, {"id": 620, "domain": "welding_processes", "question": "A welder finishing a TIG weld releases the foot pedal and the current ramps down slowly before the arc stops. This downslope feature serves a clear purpose on the finished weld. What is the main benefit of using current downslope at the end of a TIG weld?", "options": {"A": "It increases the final penetration depth right at the crater.", "B": "It fills the crater gradually and reduces the risk of cracking.", "C": "It cleans the tungsten tip ready for the next weld.", "D": "It raises the post-flow gas pressure at the weld end automatically."}, "correct": "B", "explanation": "The answer is B because downslope ramps the current down gradually so the crater fills in and the risk of crater cracking drops. Downslope reduces final penetration at the crater rather than increasing it, so A is wrong. It does not clean the tungsten or raise post-flow pressure, ruling out C and D."}, {"id": 625, "domain": "welding_processes", "question": "In submerged arc welding the combination of electrode wire and flux is selected together because both contribute to the final weld chemistry. A standard wire is paired with an active flux on a single pass joint. What does the active flux contribute that a neutral flux generally does not provide?", "options": {"A": "It changes weld metal composition through manganese or silicon pickup.", "B": "It keeps the weld chemistry identical regardless of welding voltage used.", "C": "It prevents any slag formation across the entire finished weld bead.", "D": "It eliminates the requirement for a separate shielding gas supply line."}, "correct": "A", "explanation": "The answer is A because an active flux adds manganese or silicon to the weld and changes its composition, unlike a neutral flux. An active flux changes chemistry with voltage rather than keeping it identical, so B is wrong. Flux still forms slag and SAW does not use a separate shielding gas line, ruling out C and D."}, {"id": 634, "domain": "welding_processes", "question": "Electroslag welding is an advanced process sometimes grouped with high-deposition methods for very thick sections. Unlike submerged arc, the established electroslag weld is not truly an arc process once it is running. What actually melts the wire and base metal during steady electroslag operation?", "options": {"A": "A continuous open arc burning between the wire and the joint faces.", "B": "Resistance heating of the molten slag bath carrying the current.", "C": "A focused laser beam aimed directly into the joint groove.", "D": "Friction generated by spinning the consumable wire at high speed."}, "correct": "B", "explanation": "The answer is B because once electroslag welding is running it is not an arc process, and resistance heating of the conductive molten slag bath melts the wire and base metal. There is no continuous open arc in steady operation, so A is wrong. The process uses no laser and no friction spinning of the wire, ruling out C and D."}, {"id": 635, "domain": "welding_processes", "question": "A welder reads that a submerged arc procedure calls for a specific stick-out, also called electrical extension, on the wire. Increasing the electrical stick-out at constant voltage changes the welding behaviour. What is the most common effect of increasing wire stick-out in submerged arc welding?", "options": {"A": "Penetration deepens sharply while deposition rate drops noticeably.", "B": "Deposition rate rises from resistance heating while penetration decreases.", "C": "Both penetration and deposition rate fall to nearly zero at once.", "D": "The arc voltage automatically doubles to keep the bead width fixed."}, "correct": "B", "explanation": "The answer is B because longer stick-out adds resistance heating that raises deposition rate while penetration decreases at constant voltage. Penetration deepens with shorter stick-out, not longer, so A is reversed. Both do not fall to zero and the voltage does not automatically double, ruling out C and D."}, {"id": 641, "domain": "welding_processes", "question": "The heat affected zone, often shortened to HAZ, is a region of base metal next to a weld that did not melt but still changed. A welder must explain what defines this zone. Which description correctly identifies the heat affected zone in a welded steel joint?", "options": {"A": "The deposited filler metal that solidified from the molten weld pool.", "B": "Base metal whose microstructure changed from heat without melting.", "C": "The slag layer covering the finished bead after it cools down.", "D": "The unaffected parent metal far from any welding heat input."}, "correct": "B", "explanation": "The answer is B because the heat affected zone is base metal whose microstructure changed from welding heat without actually melting. The deposited filler and the slag layer are not the HAZ, so A and C are wrong. Unaffected parent metal far from the heat is outside the HAZ, ruling out D."}, {"id": 642, "domain": "welding_processes", "question": "A welder joins a thick quenched and tempered steel and worries about the heat affected zone becoming hard and brittle. The hardness in the HAZ rises mainly because of one metallurgical event during cooling. Which factor most directly causes a hard, brittle HAZ in hardenable steel?", "options": {"A": "Slow cooling that lets soft ferrite and pearlite form fully.", "B": "Rapid cooling that transforms the structure into hard martensite.", "C": "Low carbon content that prevents any phase change at all.", "D": "Extra flux that adds silicon to soften the affected region."}, "correct": "B", "explanation": "The answer is B because rapid cooling in hardenable steel transforms the HAZ into hard, brittle martensite. Slow cooling forms soft ferrite and pearlite, which is the opposite of a hard HAZ, so A is wrong. Low carbon would resist hardening and extra silicon from flux does not soften the HAZ this way, ruling out C and D."}, {"id": 651, "domain": "welding_processes", "question": "Moisture is a major source of diffusible hydrogen entering a steel weld. A welder finds a damp drum of submerged arc flux left open in a humid shop overnight. What should the welder do before using this flux to reduce the hydrogen cracking risk on the joint?", "options": {"A": "Use the damp flux directly since moisture improves arc stability.", "B": "Dry or rebake the flux per the manufacturer's drying instructions.", "C": "Mix the damp flux with water to create a smoother paste.", "D": "Add the wet flux to fresh flux to balance the moisture out."}, "correct": "B", "explanation": "The answer is B because damp flux should be dried or rebaked per the manufacturer's instructions to cut hydrogen before use. Using damp flux directly adds hydrogen and risk rather than improving the arc, so A is wrong. Mixing flux with water or adding it to fresh flux only spreads the moisture, ruling out C and D."}, {"id": 662, "domain": "welding_processes", "question": "Submerged arc welding deposits weld metal at high rates, so dilution from the base metal becomes important on a single pass. A welder defines dilution for an apprentice. What does the term dilution describe in a submerged arc or other arc welding deposit?", "options": {"A": "The amount of flux mixed into the final weld bead by volume.", "B": "The proportion of base metal melted into the final weld bead.", "C": "The amount of water added to cool the weld pool faster.", "D": "The percentage of slag remaining trapped inside the weld metal."}, "correct": "B", "explanation": "The answer is B because dilution is the proportion of melted base metal mixed into the final weld bead. It is not the amount of flux, water, or trapped slag in the weld, so A, C, and D are wrong. Higher dilution means more base metal chemistry ends up in the deposit."}, {"id": 663, "domain": "welding_processes", "question": "Cored wires are widely used in semi-automatic and automated welding for their high deposition. A metal-cored wire differs from a flux-cored wire in what fills the tubular sheath. What does a metal-cored electrode contain inside its tube compared with a flux-cored electrode?", "options": {"A": "Mostly metal powders and alloys with little slag-forming material.", "B": "Only granular slag-forming flux with no metallic powder at all.", "C": "A solid copper rod surrounded by a thin steel jacket.", "D": "Pure inert gas compressed inside the sealed wire core."}, "correct": "A", "explanation": "The answer is A because a metal-cored electrode is filled mostly with metal powders and alloys with little slag-forming material, unlike a flux-cored wire. It is not filled only with slag-forming flux, so B is wrong. It is a tubular wire with powder inside, not a solid copper rod or compressed gas, ruling out C and D."}, {"id": 682, "domain": "welding_processes", "question": "Based on the weld cross-section shown, a welder runs a GMAW root pass with travel speed too high and a low arc voltage on a thick groove joint. The radiograph later shows a straight dark line at the root with unfused sidewalls. Which discontinuity does this combination of parameters most directly produce in the weld?", "options": {"A": "Cluster porosity trapped just beneath the finished weld surface.", "B": "Transverse cracking running through the completed weld cap face.", "C": "Lack of fusion along the unmelted groove joint sidewalls.", "D": "Excessive reinforcement piled high above the base plate surface."}, "correct": "C", "explanation": "The answer is C because high travel speed with low voltage leaves the groove sidewalls unmelted, producing lack of fusion shown as a straight dark line. These parameters do not create cluster porosity or transverse cracking, so A and B are wrong. Low heat and fast travel give little reinforcement rather than excessive buildup, ruling out D.", "image": "question_images/q682.png"}, {"id": 683, "domain": "welding_processes", "question": "An inspector needs a non-destructive method that passes high-frequency sound waves into a weld and reads reflected echoes on a screen, allowing the operator to locate and size buried discontinuities such as lack of fusion deep inside a thick steel groove weld. Which method is described?", "options": {"A": "Magnetic particle testing using applied iron powder and a yoke.", "B": "Liquid penetrant testing with visible red dye and developer spray.", "C": "Visual testing aided by a fillet weld gauge and light.", "D": "Ultrasonic testing with a hand-held transducer probe and couplant."}, "correct": "D", "explanation": "The answer is D because ultrasonic testing passes high-frequency sound waves through the weld and reads reflected echoes to locate and size buried discontinuities like lack of fusion. Magnetic particle and liquid penetrant only find surface or near-surface flaws, so A and B are wrong. Visual testing cannot see deep inside the weld, ruling out C."}, {"id": 696, "domain": "welding_processes", "question": "Based on the weld cross-section shown, hydrogen-induced cracking can appear hours after a high-strength steel weld has cooled, often near the heat-affected zone. A welder wants to understand the cause. Which combination of conditions most strongly promotes this delayed cracking during the welding process on hardenable structural steel weldments out in the field?", "options": {"A": "Low strength filler with generous preheat and slow cooling.", "B": "Clean joint, dry electrodes, and full post-weld heat treatment.", "C": "Hydrogen, residual stress, and a hard heat-affected microstructure.", "D": "High travel speed alone on thin low-carbon sheet metal."}, "correct": "C", "explanation": "The answer is C because hydrogen-induced cracking needs hydrogen, residual stress, and a hard heat-affected microstructure together. Low strength filler with preheat and slow cooling, and clean dry electrodes with full PWHT, both reduce the risk, so A and B are wrong. High travel speed alone on thin low-carbon sheet does not drive this delayed cracking, ruling out D.", "image": "question_images/q696.png"}, {"id": 698, "domain": "welding_processes", "question": "A welder must select a process for a root pass on open-root pipe where back purging is impractical and good root penetration with slag-free fusion is required. Considering process behavior, which selection best matches an open-root pipe joint welded without backing?", "options": {"A": "Submerged arc welding flooding the open root with flux.", "B": "GTAW root pass providing controlled penetration and clean fusion.", "C": "Self-shielded flux-cored wire blown by strong outdoor wind.", "D": "Oxyacetylene brazing depositing filler below the melting point."}, "correct": "B", "explanation": "The answer is B because a GTAW root pass gives controlled penetration and clean, slag-free fusion, ideal for open-root pipe without backing. SAW floods the open root with flux and cannot run there, so A is wrong. Self-shielded wire in strong wind loses shielding and oxyacetylene brazing does not melt and fuse the base metal, ruling out C and D."}, {"id": 700, "domain": "welding_processes", "question": "A welder qualification test coupon is welded, then cut and bent in a guided bend jig to check for open discontinuities on the convex face. The bent face shows an open defect larger than the allowed limit. Under standard practice, what is the correct outcome of this test?", "options": {"A": "The coupon passes because bend tests ignore surface openings.", "B": "The coupon is retested only with radiography instead.", "C": "The welder is qualified once supervisor signs the paperwork.", "D": "The coupon fails the bend test and the welder is not qualified."}, "correct": "D", "explanation": "The answer is D because an open defect on the bent convex face larger than the allowed limit fails the guided bend test and the welder is not qualified. Bend tests do not ignore surface openings, so A is wrong. A failed coupon is not saved by switching to radiography or a supervisor signature, ruling out B and C."}, {"id": 706, "domain": "common_occupational_skills", "question": "A welder is about to grind a weld and reaches for an angle grinder. The guard has been removed by the previous user to reach a tight spot, and the disc shows a small chip on its edge. What should the welder do before starting to grind with this tool?", "options": {"A": "Use the chipped disc but keep the grinder pointed away from the body.", "B": "Grind carefully without the guard since the disc still spins fine.", "C": "Reinstall the guard and replace the chipped disc before grinding.", "D": "Tape over the chipped section of the disc and reattach the guard."}, "correct": "C", "explanation": "A chipped abrasive disc can shatter at high speed and the guard is the main protection against flying fragments. The welder must replace the damaged disc and reinstall the guard before any grinding. Operating a guardless grinder with a cracked disc risks serious injury."}, {"id": 707, "domain": "common_occupational_skills", "question": "Two welders share a tight work area and one is grinding while the other prepares to start GMAW nearby. Sparks from grinding are landing near the second welder's shielding gas hoses and a partly open box of consumables. Before work continues, what should they do?", "options": {"A": "Continue since grinding sparks rarely cause any problems in a shop.", "B": "Let the grinder finish first while the welder waits across the room.", "C": "Coordinate tasks and relocate hoses and combustibles away from sparks.", "D": "Cover the consumables box and keep grinding in the same direction."}, "correct": "C", "explanation": "Grinding sparks can damage gas hoses and ignite combustible materials, creating fire and equipment hazards in a shared space. Good communication and rearranging the work so sparks are directed away from hoses and supplies prevents incidents. Coordinating tasks is a core part of safe job-site planning."}, {"id": 734, "domain": "layout_and_fabrication", "question": "Referring to the joint cross-section shown, a welder is about to fit up a groove weld and the drawing specifies a 2 mm root face on the prepared edges. The current edges have been ground to a feather edge with no root face. What problem is likely if the welder proceeds without correcting this?", "options": {"A": "The weld will be too narrow because the gap is now too small.", "B": "The joint will need less filler metal and finish much faster.", "C": "The root will fuse better because thinner edges melt more easily.", "D": "The feather edge may burn through and cause excessive root melt."}, "correct": "D", "explanation": "A root face gives the edge enough material to control melting and prevent the arc from blowing through the root. A feather edge with no root face tends to burn through, causing excessive penetration and a melted-out root. The welder should grind the specified 2 mm root face before welding.", "image": "question_images/q734.png"}, {"id": 735, "domain": "layout_and_fabrication", "question": "A welder must transfer a complex curved profile from a paper template onto a steel plate for cutting. The shop has soapstone, a scriber, and centre punches available. To mark the cut line clearly on the dark mill scale, which marking choice is most suitable?", "options": {"A": "A fine scriber line because it shows best against the dark surface.", "B": "Soapstone to draw a visible line that contrasts with the mill scale.", "C": "A centre punch series alone to outline the entire curved profile.", "D": "A pencil line since graphite stands out clearly on steel plate."}, "correct": "B", "explanation": "Soapstone leaves a light coloured line that stands out clearly against dark mill scale and survives handling and heat. A scriber line is faint on rough scaled steel and a pencil barely shows. Soapstone is the practical choice for marking a visible cut line on plate."}, {"id": 755, "domain": "layout_and_fabrication", "question": "A long beam is to receive intermittent fillet welds shown as 50-150 on the weld symbol. The welder is unsure how to space them along the flange of the beam. Which layout correctly reflects this chain intermittent fillet call-out?", "options": {"A": "Continuous weld broken only where the beam happens to splice.", "B": "50 mm pitch with each weld segment measuring 150 mm long.", "C": "150 mm weld length with 50 mm gaps between the segments.", "D": "50 mm weld segments spaced at 150 mm pitch measured centre to centre."}, "correct": "D", "explanation": "In a 50-150 intermittent fillet call-out the first number is the weld segment length and the second is the pitch measured centre to centre. This means 50 mm welds are placed so the start of each weld is 150 mm from the start of the previous one, leaving approximately 100 mm of unwelded space between segments. A continuous weld, a 150 mm segment, or a 150 mm gap between segments would all misread the notation.", "image": "question_images/q755.png"}, {"id": 759, "domain": "layout_and_fabrication", "question": "A welder reads a weld symbol with a flag at the junction of the arrow and the reference line. The shop foreman asks what this flag tells the crew about how and where the weld must be made. Which statement correctly explains its meaning?", "options": {"A": "The weld is optional depending on the final assembly fit.", "B": "The weld requires inspection by a certified third party.", "C": "The weld must be completed in the field rather than the shop.", "D": "The weld should be ground flush after it is completed."}, "correct": "C", "explanation": "A flag symbol placed at the junction of the arrow and reference line designates a field weld. It tells the crew the joint is welded during site installation, not in the shop. This affects sequencing and which welds are completed before the assembly ships out.", "image": "question_images/q759.png"}, {"id": 765, "domain": "layout_and_fabrication", "question": "A welder is cutting several pieces from a single length of angle iron and wants to limit wasted material. The stock is 6000 mm long and the pieces needed are 1400, 1400, 1100, and 900 mm. Allowing a 3 mm kerf per cut, which approach is best?", "options": {"A": "Cut the largest pieces first without planning the full layout.", "B": "Skip kerf in planning since 3 mm is too small to affect the total.", "C": "Cut from both ends inward to balance the leftover drop length.", "D": "Lay out all of the cuts on paper including kerf before starting."}, "correct": "D", "explanation": "Planning the entire cut list on paper, including each kerf, confirms all pieces fit within the 6000 mm stock before any metal is cut. The four pieces total 4800 mm plus kerf losses, leaving a known drop. Skipping kerf can cause the last piece to fall short."}, {"id": 772, "domain": "layout_and_fabrication", "question": "A welder reads dimensions on a drawing using a datum system where all measurements originate from one edge. Partway through layout the welder is tempted to measure each feature from the previous one instead. Why should the welder keep measuring from the datum?", "options": {"A": "Datum measuring is simply faster than chaining each dimension.", "B": "Measuring from the datum prevents accumulated tolerance error.", "C": "Chained measurements are forbidden under all welding codes.", "D": "Datum lines are easier to mark with a chalk line each time."}, "correct": "B", "explanation": "When dimensions chain from one feature to the next, each small error adds to the next and the total drifts off location. Measuring every feature from the single datum keeps each one independent and prevents that buildup. This is why datum dimensioning is used for accurate hole placement."}, {"id": 776, "domain": "layout_and_fabrication", "question": "A welder must control shrinkage on a long butt joint in thin plate that tends to pull and buckle. The shop suggests using back-step welding for the seam. How does the back-step technique help reduce distortion along this seam?", "options": {"A": "It welds short sections opposite to the overall travel direction.", "B": "It preheats the entire plate evenly before any weld is started.", "C": "It deposits all of the weld in one continuous high-speed pass.", "D": "It places the tacks so far apart that shrinkage cannot build up."}, "correct": "A", "explanation": "Back-step welding lays short weld segments in the reverse direction of the overall progression along the joint. Each new segment shrinks toward the already-cooled weld, spreading the shrinkage forces and limiting buckling. This breaks up the continuous pull that warps thin plate."}, {"id": 778, "domain": "layout_and_fabrication", "question": "A welder lays out a bolt circle on a round flange and must space six holes evenly around it. The center is established and the bolt circle diameter is known. Which layout method most reliably divides the circle into six equal spaces?", "options": {"A": "Estimate the spacing by eye and then adjust the last hole.", "B": "Step the compass radius around the circle to mark six points.", "C": "Measure 60 mm between holes regardless of the diameter used.", "D": "Drill one hole and rotate the flange to copy all the rest."}, "correct": "B", "explanation": "On a circle the radius steps exactly six times around the circumference, dividing it into six equal arcs. Setting the compass to the bolt circle radius and stepping it around marks six evenly spaced points. Fixed 60 mm spacing ignores the diameter and only works by coincidence."}, {"id": 780, "domain": "layout_and_fabrication", "question": "A welder must fit a lap joint between two overlapping plates that will see shear loading. The drawing calls for a fillet along the exposed edge. During fit-up the welder notices a 2 mm gap between the overlapping faces. How should this be handled?", "options": {"A": "Insert shims into the gap and weld over them permanently.", "B": "Leave the gap and increase the fillet leg to bridge across it.", "C": "Close the gap by clamping the two plates tightly together.", "D": "Weld both edges so the gap is sealed on each outer side."}, "correct": "C", "explanation": "A lap joint relies on the plates sitting flat against each other for proper load transfer in shear. Clamping the overlapping faces together closes the gap before the fillet is welded. Bridging a gap with a larger fillet or filling it with shims weakens the connection and is poor practice."}, {"id": 787, "domain": "layout_and_fabrication", "question": "A welder reads a section view on a drawing and sees hatching lines drawn at 45 degrees across a cut component. A new helper asks what these diagonal lines represent on the view. What is the correct explanation of this section hatching?", "options": {"A": "They show hidden edges located behind the section cut plane.", "B": "They mark the surface that must be ground smooth after welding.", "C": "They indicate the weld itself must be made at a 45 degree angle.", "D": "They show where the part is cut to reveal the inside material."}, "correct": "D", "explanation": "Section hatching is the set of diagonal lines that shows the solid material exposed where a part is imagined to be cut through. It helps the reader understand the internal shape of a component on the drawing. The hatching has nothing to do with grinding or weld angle."}, {"id": 789, "domain": "layout_and_fabrication", "question": "A welder is laying out a complex part and the drawing is dimensioned in third-angle projection. The welder is more familiar with first-angle layouts. Why must the welder confirm which projection is used before interpreting the views on this drawing?", "options": {"A": "The two projections arrange the views in different positions.", "B": "Third-angle drawings never include any hidden lines at all.", "C": "First-angle projection always uses metric units exclusively.", "D": "The projection type directly changes the required weld sizes."}, "correct": "A", "explanation": "First-angle and third-angle projections place the side and top views on opposite sides of the front view. Misreading the projection can flip the part and cause features to be laid out on the wrong face. Confirming the projection symbol prevents this layout error before any cutting begins."}, {"id": 792, "domain": "layout_and_fabrication", "question": "A welder fabricating a box section must decide the order to weld the four corner seams to limit twist in the finished box. The section is long and slender. Which sequencing strategy best keeps the box straight and free of twist as it cools?", "options": {"A": "Alternate seams on opposite corners and reverse the directions.", "B": "Weld the two top seams completely before the bottom two seams.", "C": "Weld one full seam at a time from one end to the other end.", "D": "Weld all four seams in the same direction one right after another."}, "correct": "A", "explanation": "Welding opposite corners in alternation balances the shrinkage forces around the box section. Reversing weld direction between seams further spreads the pull so twist does not accumulate. Welding all seams the same way concentrates shrinkage and twists a long slender box."}, {"id": 798, "domain": "layout_and_fabrication", "question": "A welder fitting up a butt joint for a code weld must set the correct root face, also called the land. The procedure specifies a land of about 1.5 mm. What is the consequence of beveling the plates to a knife edge with almost no root face?", "options": {"A": "Burn-through and excessive melt-through become likely at the root.", "B": "The land controls only the bead width and not the root behavior.", "C": "The weld develops too little penetration down at the root area.", "D": "The joint gains extra strength from the much sharper bevel edges."}, "correct": "A", "explanation": "The root face, or land, gives the joint enough metal at the root to resist melting away under the arc. A near knife edge with no land melts too easily, causing burn-through and excessive melt-through. The specified 1.5 mm land balances penetration against the risk of melting the root."}, {"id": 801, "domain": "cutting_and_gouging", "question": "A welder is oxy-fuel cutting thick mild steel plate but the cut keeps stopping partway through and the kerf is rough and wide. The preheat flames look feathered and the tip is several sizes too large for the plate. What should the welder adjust first?", "options": {"A": "Raise the acetylene pressure until the preheat flames become long and bushy.", "B": "Increase the oxygen cutting pressure far above the recommended setting for that tip.", "C": "Slow the travel speed dramatically and hold the torch farther from the plate.", "D": "Switch to a properly sized tip and set a neutral preheat flame before cutting."}, "correct": "D", "explanation": "An oversized tip and feathered (carburizing) flame waste gas and produce a rough, wide kerf with poor cutting action. Selecting the correct tip size for the plate thickness and adjusting to a neutral flame restores clean, continuous cutting. Simply boosting oxygen pressure on the wrong tip causes turbulence and a worse cut."}, {"id": 803, "domain": "welding_processes", "question": "A welder running GMAW short-circuit transfer on thin sheet metal is getting excessive spatter, an unstable arc, and a popping sound. The wire stubs into the plate occasionally. Voltage seems low while wire feed speed appears high for the material thickness being joined. What adjustment best stabilizes the arc?", "options": {"A": "Switch the shielding gas to pure argon for better arc stability.", "B": "Increase wire feed speed further while leaving the voltage unchanged.", "C": "Raise the voltage slightly and reduce wire feed speed to balance the arc.", "D": "Lengthen the contact-tip-to-work distance well beyond the recommended range."}, "correct": "C", "explanation": "Stubbing, popping, and heavy spatter in short-circuit GMAW usually mean voltage is too low relative to wire feed speed. Raising voltage and trimming wire feed speed balances burn-off with deposition and smooths the arc. Pure argon is unsuitable for short-circuit steel welding and worsens transfer."}, {"id": 809, "domain": "welding_processes", "question": "A welder running SAW on a long automated seam notices the arc is being exposed because the flux hopper is feeding too little flux ahead of the wire. Sparks and ultraviolet flash are visible along the joint. What is the correct response to maintain a sound submerged-arc weld?", "options": {"A": "Lower the wire feed speed until the visible sparking disappears.", "B": "Continue welding since brief arc exposure does not affect SAW quality.", "C": "Restore adequate flux coverage so the arc stays fully submerged.", "D": "Increase travel speed to outrun the area of exposed arc flash."}, "correct": "C", "explanation": "Submerged-arc welding depends on a deep flux blanket that shields the arc, prevents spatter, and protects the weld pool from the atmosphere. Visible arc and sparking mean coverage is inadequate and porosity or contamination can result. Restoring proper flux feed keeps the arc submerged and the weld sound."}, {"id": 814, "domain": "welding_processes", "question": "A welder grinding a tungsten for DCEN GTAW on steel keeps getting a wandering, unstable arc that will not stay centered on the joint. The tungsten was ground with grinding marks running across the electrode rather than lengthwise. What grinding practice corrects the arc instability?", "options": {"A": "Grind a blunt flat tip with circular marks around the point.", "B": "Switch to a balled tungsten tip ground at random angles.", "C": "Leave the cross marks but increase the argon flow rate.", "D": "Grind the tungsten with marks running lengthwise toward the tip."}, "correct": "D", "explanation": "On DCEN GTAW the tungsten should be ground with the marks running lengthwise so electrons emit straight off the point. Cross grinding marks cause the arc to wander and emit unevenly. Lengthwise grinding produces a stable, focused, well-aimed arc."}, {"id": 823, "domain": "cutting_and_gouging", "question": "During oxy-fuel cutting, a welder hears a loud popping at the tip followed by a squealing sound and the flame appears to burn back inside the torch. This indicates a flashback condition is occurring. What is the immediate correct response to protect the welder and equipment?", "options": {"A": "Shut off the torch valves immediately, oxygen first, then fuel.", "B": "Keep cutting and let the flame reestablish itself at the tip.", "C": "Increase the oxygen pressure quickly to push the flame back out.", "D": "Lay the torch down and walk away until the squealing stops."}, "correct": "A", "explanation": "A flashback means the flame has burned back into the torch, which can travel toward the hoses and regulators and cause an explosion. Shutting the torch valves immediately, oxygen first then fuel, starves the flame and stops it. The equipment must then be inspected and flashback arrestors checked before reuse."}, {"id": 827, "domain": "common_occupational_skills", "question": "A welder is assigned to weld inside a large steel tank classified as a confined space. There is one entry hatch, limited airflow, and shielding gas will be used during the work. Before entering and beginning to weld, what is the essential safety requirement?", "options": {"A": "Enter alone quickly and prop the hatch open for some airflow.", "B": "Follow a confined-space entry permit with atmospheric testing and an attendant.", "C": "Wear a dust mask and rely on the shielding gas to displace bad air.", "D": "Run a small fan inside and begin welding without further checks."}, "correct": "B", "explanation": "Confined spaces can accumulate toxic fume and displace oxygen, especially when shielding gas is used. A confined-space entry permit requires atmospheric testing, continuous ventilation, and a trained attendant outside the space. Entering without these controls risks asphyxiation or being overcome with no rescue."}, {"id": 828, "domain": "common_occupational_skills", "question": "A welder receives a new welding consumable and is unsure of the hazards from its fume. A WHMIS-labelled container and a safety data sheet are available in the shop. To learn the health hazards and required protective measures, where should the welder look first?", "options": {"A": "Ask a nearby coworker what they think the product probably contains.", "B": "Check the price tag and packaging for any printed warnings.", "C": "Start using the product and stop only if symptoms appear later.", "D": "Read the safety data sheet and the WHMIS label for hazard information."}, "correct": "D", "explanation": "WHMIS requires that hazardous products carry standardized labels and have safety data sheets describing hazards, exposure controls, and first aid. The welder should read the safety data sheet and label before use to identify required protection. Guessing or relying on coworkers does not provide the verified hazard information."}, {"id": 834, "domain": "layout_and_fabrication", "question": "Referring to the joint cross-section shown, a welder preparing an open-root butt joint on plate needs the correct fit-up before welding the root pass. The blueprint specifies a root opening and a root face on the beveled edges. If the root opening is set much too wide, what problem is most likely during the root pass?", "options": {"A": "Incomplete penetration because the gap is too small to fill.", "B": "Burn-through and excessive root reinforcement that is hard to control.", "C": "Faster welding with no effect on the finished root quality.", "D": "A narrower bead that automatically improves the joint strength."}, "correct": "B", "explanation": "An excessively wide root opening leaves too much gap for the root pass to bridge cleanly, causing burn-through and uncontrolled root reinforcement. Following the specified root opening and root face gives proper penetration without melting through. Correct fit-up is essential for a sound root pass.", "image": "question_images/q834.png"}, {"id": 841, "domain": "welding_processes", "question": "Based on the weld cross-section shown, a welder makes a fillet weld and inspection reports undercut along the top toe of a horizontal weld. The welder ran high amperage, a long arc, and a fast travel speed with the wrong work angle. The job must pass visual inspection. What combination of changes reduces the undercut?", "options": {"A": "Speed up travel even more so less metal can undercut the edge.", "B": "Increase amperage further and keep the long arc for deeper penetration.", "C": "Lower amperage, shorten the arc, and correct the work angle and travel speed.", "D": "Point the electrode straight at the top plate and weld faster still."}, "correct": "C", "explanation": "Undercut at the toe usually comes from excessive amperage, a long arc, fast travel, or a poor work angle that melts the edge without filling it. Lowering amperage, holding a tight arc, and correcting the angle and speed lets the metal fill the toe. These adjustments eliminate the undercut groove.", "image": "question_images/q841.png"}, {"id": 843, "domain": "welding_processes", "question": "Using the welding position diagram shown, a welder must select an electrode for an out-of-position SMAW fillet on mild steel where a fast-freezing slag helps control the puddle overhead and vertical. The job calls for an all-position rod with good penetration. Which electrode classification is best suited to this work?", "options": {"A": "E6011, an all-position rod with a fast-freezing slag and good penetration.", "B": "E7027, a high-deposition rod intended for flat fillet welding only.", "C": "E7024, an iron-powder rod made mainly for flat and horizontal welds.", "D": "E6013 run at very high amperage for forced overhead deposition."}, "correct": "A", "explanation": "E6011 is an all-position cellulosic electrode with a fast-freezing slag and digging arc that suits vertical and overhead fillets. E7024 and E7027 are high-deposition rods designed for flat and horizontal positions, not out-of-position work. Choosing E6011 gives the puddle control needed overhead and vertical.", "image": "question_images/q843.png"}, {"id": 874, "domain": "cutting_and_gouging", "question": "A welder must bevel the edge of plate for a groove weld using oxy-fuel. He wants a smooth 45-degree bevel face with minimal cleanup. The plate is laid flat on the table. To control the angle and produce a consistent bevel, what is the best practice?", "options": {"A": "Hold the torch freehand and adjust the angle by feel as he goes.", "B": "Use a bevel guide or set the torch in a holder at the correct angle.", "C": "Cut straight down then grind the square edge to a 45-degree bevel.", "D": "Tilt the plate on edge and cut straight down through it."}, "correct": "B", "explanation": "A consistent bevel requires holding the torch at a steady, repeatable angle along the whole edge. A bevel guide or torch holder maintains the 45-degree angle far better than freehand cutting. Cutting square and grinding the entire bevel afterward wastes time and material."}, {"id": 876, "domain": "cutting_and_gouging", "question": "A welder is about to oxy-fuel cut over a concrete floor that has trapped moisture. A co-worker warns that molten slag could hit the wet concrete. To prevent injury from this hazard during cutting, what is the most appropriate precaution?", "options": {"A": "Cut anyway because concrete cannot react with hot slag.", "B": "Cut faster so less slag has time to land on the floor.", "C": "Pour water on the concrete first to cool it before cutting.", "D": "Shield the floor or use dry material so slag cannot reach wet concrete."}, "correct": "D", "explanation": "Hot slag landing on wet or sealed concrete can cause the trapped moisture to flash to steam and spall, throwing concrete and slag violently. Shielding the floor or laying down dry fire-resistant material stops the hot metal from reaching the wet surface. Adding more water increases the hazard rather than reducing it."}, {"id": 880, "domain": "cutting_and_gouging", "question": "A welder cuts several plates with a plasma torch and notices the consumables, especially the nozzle and electrode, are wearing out unusually fast. He has been starting many pilot arcs in mid-air without touching the plate. Why is this practice shortening consumable life?", "options": {"A": "Cutting in open air actually cools and protects the consumables.", "B": "Pilot arcs reduce wear by keeping the torch warm between cuts.", "C": "Consumable life depends only on plate thickness, not arc starts.", "D": "Frequent pilot-arc starts away from the work accelerate electrode and nozzle wear."}, "correct": "D", "explanation": "Each pilot-arc start places high stress on the electrode and nozzle, and excessive starts away from the work waste consumable life. Minimizing unnecessary starts and beginning cuts properly extends consumable service. The number and quality of arc starts strongly affect wear, not just plate thickness."}, {"id": 884, "domain": "welding_processes", "question": "A welder using FCAW self-shielded wire outdoors gets good results, then switches to a gas-shielded flux-cored wire on the same windy job. The new welds show porosity. He kept the same technique and settings. What is the most likely cause of the porosity?", "options": {"A": "Wind blew away the shielding gas the gas-shielded wire requires.", "B": "The flux in the wire was simply defective from the factory.", "C": "The travel speed was too slow for the gas-shielded process.", "D": "The base metal needed preheat that self-shielded wire did not."}, "correct": "A", "explanation": "Gas-shielded flux-cored wire depends on an external shielding gas that wind can easily disperse. Self-shielded wire makes its own protection and tolerates breezes, but gas-shielded wire does not. The wind blowing the gas away exposed the molten weld to air and caused porosity."}, {"id": 886, "domain": "welding_processes", "question": "A welder is setting up submerged arc welding on a long thick seam and must keep the granular flux covering the arc throughout the weld. Partway along, the flux hopper runs low and the arc becomes exposed briefly. Why must flux coverage be maintained?", "options": {"A": "Exposed arc in SAW gives better penetration into the joint.", "B": "Flux only improves appearance and does not affect weld soundness.", "C": "Flux coverage shields the molten weld and prevents arc flash exposure.", "D": "Running low on flux speeds up the weld and saves material."}, "correct": "C", "explanation": "In submerged arc welding the granular flux blankets the arc, protecting the molten metal from the air and containing the intense arc light. If the flux runs low and the arc is exposed, the weld can suffer contamination and operators face arc flash. Maintaining full flux coverage is essential to a sound, safe weld."}, {"id": 890, "domain": "welding_processes", "question": "A welder using GMAW on a thick carbon steel joint sees a high, narrow, ropey bead with poor fusion at the toes. The voltage looks low for the wire feed speed he has dialed in. To flatten the bead and improve fusion, what adjustment is most appropriate?", "options": {"A": "Increase travel speed to spread the bead out more.", "B": "Lower the wire feed speed and keep the same low voltage.", "C": "Reduce the gas flow to concentrate heat into the joint.", "D": "Increase the voltage to widen and flatten the bead profile."}, "correct": "D", "explanation": "A high, narrow, ropey bead with cold toes is a classic sign of voltage that is too low for the wire feed speed. Raising the voltage broadens the arc cone, flattening the bead and improving fusion at the toes. Balancing voltage to the wire feed speed corrects the profile."}, {"id": 898, "domain": "common_occupational_skills", "question": "A welder is part of a crew where a near-miss happened when a tool fell from scaffolding but hit no one. Some workers want to forget it since nobody was hurt. The welder believes reporting matters. Why should this near-miss be reported?", "options": {"A": "Reporting it helps identify and fix hazards before a real injury occurs.", "B": "Near-misses do not need reporting because no harm was done.", "C": "Reporting is only required when someone is actually injured.", "D": "Forgetting the event keeps the crew's safety record looking clean."}, "correct": "A", "explanation": "A near-miss is a warning that an unsafe condition exists and could cause a real injury next time. Reporting it lets the crew investigate and correct the hazard, such as securing tools at height. Ignoring near-misses allows the same conditions to lead to serious harm later."}, {"id": 899, "domain": "common_occupational_skills", "question": "A welder is told to use a damaged extension cord with exposed conductor near the plug because it is the only one available for a grinder. The job site is damp from recent rain. To work safely with power tools here, what should the welder do?", "options": {"A": "Use the cord but keep it raised off the damp ground.", "B": "Wrap the exposed area with electrical tape and use the cord.", "C": "Remove the damaged cord from service and get an undamaged one.", "D": "Plug it in carefully and avoid touching the damaged section."}, "correct": "C", "explanation": "A cord with exposed conductors is an electrocution hazard, especially in damp conditions. Tape is not a reliable repair and does not restore the cord's insulation. The damaged cord must be removed from service and replaced with one in good condition."}, {"id": 905, "domain": "common_occupational_skills", "question": "A welder notices the previous shift left a cluttered work area with trailing leads, oily rags, and offcuts near the welding station. The supervisor is busy and the next job is urgent. What is the most professional action before starting work?", "options": {"A": "Report the mess in writing and wait for housekeeping to arrive.", "B": "Start welding immediately to stay on schedule for the urgent job.", "C": "Move only the items directly under the welding position you need.", "D": "Clear combustibles, route leads safely, and tidy the area first."}, "correct": "D", "explanation": "Oily rags and offcuts near hot work are fire hazards, and trailing leads create trip and damage risks. A welder is responsible for a safe work area regardless of who left the mess or how urgent the job is. Clearing combustibles and routing leads safely takes minutes and prevents fires and injuries."}, {"id": 908, "domain": "layout_and_fabrication", "question": "A fabricator must lay out a 90 degree corner on a large steel plate but has no framing square big enough. Only a tape measure and chalk line are available. Which method gives an accurate square corner using just measurements?", "options": {"A": "Eyeball the corner and adjust until it appears square.", "B": "Fold the plate edge over to mirror the opposite side.", "C": "Measure equal lengths on both edges and connect them.", "D": "Use the 3-4-5 triangle method to set the right angle."}, "correct": "D", "explanation": "The 3-4-5 rule applies the Pythagorean relationship so any multiple of those lengths forms a true right angle. Marking 3 units along one line and 4 along the other gives a 5 unit diagonal when the corner is square. This method scales to large layouts where no square is big enough."}, {"id": 909, "domain": "layout_and_fabrication", "question": "Referring to the joint cross-section shown, a welder is preparing two 12 mm plates for a full penetration butt weld in the flat position using SMAW. The procedure calls for a single-V groove. When setting up the joint, what feature lets the root pass fuse fully without burn-through?", "options": {"A": "A tight zero root gap with a sharp feather edge.", "B": "A large 6 mm root face with no root opening at all.", "C": "An appropriate root face and a controlled root opening.", "D": "A wide 10 mm root opening with no root face land."}, "correct": "C", "explanation": "A single-V groove needs a root face land plus a controlled root opening so the root pass fuses to the bottom without melting through. Too little gap with a feather edge causes lack of fusion or blow-through, while too wide a gap risks burn-through. Matching the root face and gap to the procedure gives sound full penetration.", "image": "question_images/q909.png"}, {"id": 911, "domain": "cutting_and_gouging", "question": "A welder oxy-fuel cuts 25 mm plate and the cut starts well but the kerf becomes wide and the slag sticks badly partway through. The drag lines curve back sharply. Which adjustment would most likely correct the poor cut quality?", "options": {"A": "Increase travel speed to match the wider kerf forming.", "B": "Reduce cutting oxygen pressure until the slag clears itself.", "C": "Slow the travel speed and steady the torch standoff distance.", "D": "Raise the torch far from the plate to widen the preheat."}, "correct": "C", "explanation": "Sharp backward-curving drag lines and sticking slag indicate the torch is moving too fast for the plate thickness and the standoff is unsteady. Slowing travel and holding a consistent tip-to-work distance lets the cutting oxygen sever the full thickness cleanly. Steady standoff keeps the kerf narrow and the slag flowing off."}, {"id": 912, "domain": "cutting_and_gouging", "question": "A welder uses air carbon arc gouging to remove a defective weld before re-welding. After gouging, the groove has a shiny, hardened, carbon-streaked surface. Before depositing new weld metal into this groove, what step is necessary?", "options": {"A": "Weld directly into the groove since gouging already cleaned it.", "B": "Apply a thin oil film to prevent the groove from oxidizing.", "C": "Wipe the groove with a damp rag to cool the surface fast.", "D": "Grind the gouged surface to remove carbon and hardened layer."}, "correct": "D", "explanation": "Air carbon arc gouging leaves a carbon-rich, hardened surface and sometimes carbon deposits from the electrode. Welding over that layer causes porosity, cracking, and poor fusion. Grinding the groove back to clean, bright metal removes the carbon and hardened skin so the new weld bonds soundly."}, {"id": 914, "domain": "cutting_and_gouging", "question": "A welder must oxy-fuel cut a painted, galvanized steel beam in a shop with limited ventilation. The coating will burn off in the cut zone. Before starting the cut, what is the priority control for the welder's health?", "options": {"A": "Cut quickly so exposure to the fumes lasts the shortest time.", "B": "Pour water over the coating to keep the zinc from vaporizing.", "C": "Provide local exhaust ventilation and respiratory protection for the fumes.", "D": "Stand upwind and rely on the open shop door for airflow."}, "correct": "C", "explanation": "Burning zinc galvanizing and paint releases toxic fumes that cause metal fume fever and other illness, especially in poor ventilation. Local exhaust ventilation captures the fumes at the source and a suitable respirator protects the welder. Standing upwind alone does not control concentrated fumes in a confined shop."}, {"id": 929, "domain": "layout_and_fabrication", "question": "A welder reads a drawing and sees a weld symbol with a circle at the elbow where the arrow meets the reference line. The fabrication will be completed in the field rather than the shop. What does this circle on the weld symbol tell the welder?", "options": {"A": "The weld must be ground flush after completion in the shop.", "B": "The weld is a plug weld placed inside a drilled hole.", "C": "The weld must be made completely all the way around the joint.", "D": "The weld requires radiographic inspection before acceptance."}, "correct": "C", "explanation": "A circle at the junction of the arrow and the reference line is the weld-all-around symbol, which tells the welder to weld completely around the entire joint. A filled flag at the same junction is the field weld symbol, indicating work completed at the installation site rather than the shop. The circle in this question is the weld-all-around symbol, not a field weld indicator; plug welds and radiographic inspection symbols look nothing like a circle at the elbow.", "image": "question_images/q929.png"}, {"id": 939, "domain": "welding_processes", "question": "A welder must select an SMAW electrode to weld a dirty, rusty repair on a farm implement where the metal cannot be cleaned well. Penetration through contamination matters more than a low-hydrogen deposit. Which electrode characteristic best suits this situation?", "options": {"A": "A fast-freezing low-hydrogen E7018 for maximum cleanliness.", "B": "A heavy iron-powder E7024 for the highest deposition rate.", "C": "A deep-penetrating cellulosic electrode like E6010 for dirty steel.", "D": "A stainless electrode to resist the rust on the surface."}, "correct": "C", "explanation": "Cellulosic electrodes such as E6010 produce a digging, deep-penetrating arc that cuts through rust, scale, and contamination. That makes them well suited to dirty field repairs where the steel cannot be cleaned properly. Low-hydrogen and iron-powder rods need cleaner surfaces to perform well, so they are less suited here."}, {"id": 950, "domain": "common_occupational_skills", "question": "A welder smells gas near the oxy-fuel station and suspects a leak at a hose fitting. A coworker suggests holding a lit match near the fitting to find where the flame flickers. What is the correct method to locate the leak safely?", "options": {"A": "Apply approved leak-detection solution and watch for bubbles.", "B": "Hold a small flame near the fitting to spot the leak.", "C": "Run the gas at full pressure and listen for a hiss.", "D": "Spray a solvent on the fitting and feel for cold spots."}, "correct": "A", "explanation": "Using a flame to find a gas leak risks fire or explosion and must never be done. The safe method is brushing an approved leak-detection solution or soapy water on the fittings and watching for bubbles where gas escapes. Bubbling pinpoints the leak without any ignition source near the flammable gas."}, {"id": 954, "domain": "layout_and_fabrication", "question": "A welder must check that a fabricated frame is square before tacking the final corner. The frame is roughly two metres on each side and a framing square is too small to confirm the diagonals. Which method best verifies the frame is square across its full size?", "options": {"A": "Sight along one edge by eye and adjust the corner accordingly.", "B": "Measure both diagonals and adjust until the two readings are equal.", "C": "Use a small framing square at each of the four corners.", "D": "Tack all corners first and check for square afterward."}, "correct": "B", "explanation": "Equal diagonal measurements confirm a rectangular frame is truly square across its whole span. A small square only checks local corners and misses overall racking. Sighting by eye or tacking first risks locking in an out-of-square frame."}, {"id": 957, "domain": "layout_and_fabrication", "question": "A welder is assembling a long thin-wall rectangular duct from sheet steel and expects buckling and warping from welding heat. The seams must stay flat and straight for the duct to fit downstream sections. Which welding sequence best limits heat buildup and distortion on the seams?", "options": {"A": "Run one continuous weld from end to end on each seam.", "B": "Weld each seam fully before moving to the next seam.", "C": "Use staggered intermittent or back-step welds spread along the seam.", "D": "Increase amperage so each seam finishes faster overall."}, "correct": "C", "explanation": "Staggered intermittent or back-step welding distributes heat so no single area overheats and warps. Spreading the welds lets earlier sections cool before nearby ones are welded. Continuous passes or higher amperage concentrate heat and increase buckling on thin material."}, {"id": 978, "domain": "common_occupational_skills", "question": "A welder notices that scrap steel offcuts, used grinding discs, and empty solvent cans are all being thrown into one bin in the shop. The company wants to reduce waste sent to landfill and handle materials responsibly. Which practice best supports sustainable waste handling here?", "options": {"A": "Continue using one bin since sorting slows the workflow down.", "B": "Send everything to landfill together to keep the shop tidy.", "C": "Separate recyclable scrap metal and dispose of solvent cans as hazardous waste.", "D": "Burn the solvent cans on site to reduce the volume of waste."}, "correct": "C", "explanation": "Scrap steel is valuable and recyclable, so separating it keeps it out of landfill. Solvent cans can hold hazardous residue and must be handled through proper hazardous waste channels. Mixing waste, burning cans, or landfilling everything wastes resources and can create environmental hazards."}, {"id": 980, "domain": "common_occupational_skills", "question": "A welder will perform hot work in an area of the plant where no welding is normally done, near stored materials. The plant uses a permit system for such work. Sparks and heat will be present. What must be done before beginning this hot work?", "options": {"A": "Obtain a hot work permit and set up a fire watch with controls in place.", "B": "Start the work early so it finishes before anyone notices the sparks.", "C": "Move a single extinguisher nearby and begin welding right away.", "D": "Ask a coworker to glance over occasionally while you weld."}, "correct": "A", "explanation": "Hot work outside designated areas requires a permit that confirms hazards are assessed and controlled. A trained fire watch plus controls such as clearing combustibles and having extinguishers ready manage the fire risk. Starting early, one extinguisher alone, or a casual glance does not meet permit requirements."}, {"id": 987, "domain": "common_occupational_skills", "question": "A welder notices the shop floor near the welding bay has scattered offcuts, trailing leads, and a small puddle of cutting fluid in the walkway. A coworker nearly trips while carrying a part. The work area needs to stay productive. What should the welder do?", "options": {"A": "Keep working and step around the hazards carefully each time.", "B": "Clean up the offcuts, route the leads safely, and wipe the spill.", "C": "Place a warning cone by the puddle and leave the rest as is.", "D": "Tell the next shift to deal with the mess at cleanup time."}, "correct": "B", "explanation": "Scattered offcuts, trailing leads, and spills are slip and trip hazards that can cause injury. Clearing the debris, routing leads out of walkways, and wiping the spill restores a safe workspace. Stepping around, a single cone, or leaving it for later leaves the hazards in place."}, {"id": 991, "domain": "common_occupational_skills", "question": "A welder is about to start arc welding outdoors on a windy day and the shielding gas keeps getting blown away, causing porosity in the welds. The job must be completed outdoors. The wind is steady from one direction. What is the best way to handle this situation?", "options": {"A": "Turn the shielding gas flow up very high to fight the wind.", "B": "Set up wind screens or shelter the joint to protect the gas shield.", "C": "Weld faster so the gas covers the puddle before it blows off.", "D": "Continue welding and grind out the porosity afterward each time."}, "correct": "B", "explanation": "Wind blows the shielding gas off the weld puddle and causes porosity in gas shielded processes. Setting up wind screens or sheltering the joint keeps the gas in place for sound welds. Cranking the flow turns it turbulent, and welding fast or grinding later does not stop the porosity."}, {"id": 993, "domain": "common_occupational_skills", "question": "A welder is assigned a repetitive overhead welding task for several hours and begins to feel neck and shoulder fatigue that could affect weld quality and safety. A positioner and adjustable platform are available in the shop. How should the welder best manage this task?", "options": {"A": "Push through the fatigue to keep the production schedule on track.", "B": "Tighten the welds quickly to spend less time looking up.", "C": "Use the positioner to bring the work to a better position and take breaks.", "D": "Hold the torch with both hands to support the overhead reach."}, "correct": "C", "explanation": "Long overhead welding causes muscle fatigue that lowers weld quality and increases safety risk. Using a positioner to bring the joint into an easier position and taking breaks reduces the strain. Pushing through, rushing, or two-handed holding does not address the underlying fatigue from overhead work."}, {"id": 994, "domain": "common_occupational_skills", "question": "A welder is given a welding procedure specification and an inspector will check the finished welds against it. Partway through, the welder realizes the actual joint differs slightly from what the procedure covers. The deadline is near. What is the correct professional action?", "options": {"A": "Continue welding and hope the inspector accepts the close match.", "B": "Weld to the procedure exactly even though the joint is different.", "C": "Adjust your technique quietly to make the joint look conforming.", "D": "Stop and have the procedure reviewed so it covers the actual joint."}, "correct": "D", "explanation": "A welding procedure specification must match the actual joint for the weld to be qualified and acceptable. Stopping to have the procedure reviewed ensures the work is covered before the inspection. Hoping it passes, hiding the difference, or forcing a mismatched procedure risks rejection and rework."}, {"id": 999, "domain": "common_occupational_skills", "question": "A welder is part of a crew where a new apprentice is about to use a forklift to move steel without holding the required certification. The apprentice is confident and the job is behind schedule. The welder sees this happening. What is the most professional response?", "options": {"A": "Stop the operation and have a certified operator move the steel.", "B": "Let the apprentice proceed since the job is running behind.", "C": "Coach the apprentice through the lift from the side as it happens.", "D": "Allow the move but stand clear in case something goes wrong."}, "correct": "A", "explanation": "Operating a forklift without the required certification is unsafe and against regulations. Stopping the operation and having a certified operator move the steel protects the apprentice and others. Letting it proceed, coaching on the spot, or just standing clear ignores the legal and safety requirement."}, {"id": 1001, "domain": "common_occupational_skills", "question": "A welder finds a 20-litre pail of solvent on a shelf with a faded label showing only a flame pictogram. Under WHMIS 2015, before using this product the welder must first obtain reliable hazard information. Which document provides the full handling, storage, and first-aid details?", "options": {"A": "The product safety data sheet kept on the work site.", "B": "The shipping manifest that came with the delivery truck.", "C": "The manufacturer warranty card stored in the office.", "D": "The purchase invoice filed by the receiving clerk."}, "correct": "A", "explanation": "WHMIS 2015 requires a safety data sheet for every hazardous product on site. The sheet lists handling, storage, exposure limits, and first-aid measures in a fixed format. Workers must be able to access it before using the product."}, {"id": 1002, "domain": "common_occupational_skills", "question": "During overhead arc welding a worker wears a standard shade-10 helmet, leather gloves, and a cotton shirt with the sleeves rolled up to stay cool. The supervisor stops the job over a PPE violation. Which gap created the most direct burn and arc-flash exposure risk?", "options": {"A": "The shade-10 lens was too dark for the current.", "B": "The leather gloves trapped too much hand sweat.", "C": "The cotton shirt absorbed water from the air.", "D": "The exposed forearms had no protective flame-resistant cover."}, "correct": "D", "explanation": "Overhead welding drops sparks and spatter straight down onto the arms and torso. Rolled sleeves leave bare skin exposed to burns and ultraviolet arc radiation. Flame-resistant clothing must cover all skin near the arc."}, {"id": 1003, "domain": "common_occupational_skills", "question": "Hot work is scheduled inside a building beside stored cardboard. A fire watch is assigned. According to common hot work permit practice, for how long must the fire watch normally remain at the area after the welding and cutting work has stopped?", "options": {"A": "Until the next shift worker arrives on site.", "B": "Only until the metal feels cool to touch.", "C": "For at least thirty minutes after work ends.", "D": "For exactly five minutes after the last spark."}, "correct": "C", "explanation": "Hot work permits require a fire watch to stay after the job is done because hidden smouldering can ignite later. A minimum of thirty minutes is the common standard for monitoring the area. The watch must have firefighting equipment ready during this time."}, {"id": 1004, "domain": "common_occupational_skills", "question": "A rigger must lift a 1,800 kilogram steel plate using a two-leg sling at a 60 degree angle from horizontal. The crew asks how the sling angle affects the load each leg carries compared to a vertical lift. What happens to the tension in each sling leg as the angle gets smaller?", "options": {"A": "Tension in each leg decreases steadily toward zero.", "B": "Tension in each leg stays the same regardless of angle.", "C": "Tension shifts entirely onto one single sling leg.", "D": "Tension in each leg increases as the angle decreases."}, "correct": "D", "explanation": "As a sling angle drops toward horizontal, each leg must pull harder to support the same vertical load. Lower angles multiply the tension well beyond the actual weight. Riggers keep sling angles as steep as practical to reduce this force."}, {"id": 1005, "domain": "common_occupational_skills", "question": "A worker is about to enter a steel storage tank classified as a confined space to repair a cracked weld. The atmosphere has not yet been tested. Before any entry takes place, which action is the required first step under confined space entry procedure?", "options": {"A": "Begin grinding the cracked weld from inside.", "B": "Pass the welding leads down into the tank first.", "C": "Test the atmosphere for oxygen and hazardous gases.", "D": "Close the tank lid to keep dust out."}, "correct": "C", "explanation": "Confined spaces can hold low oxygen or toxic and flammable gases that are not visible. Atmospheric testing must happen before entry to confirm the space is safe. Entry is forbidden until acceptable readings are recorded and ventilation is arranged."}, {"id": 1006, "domain": "common_occupational_skills", "question": "A welder notices the cable insulation on the electrode holder lead is cracked and copper strands are showing near the connection. The machine is energized. Considering electrical safety on a welding power source, what is the correct response to this damaged lead?", "options": {"A": "Shut off the power source and replace the damaged lead.", "B": "Wrap the lead with cloth tape and keep welding.", "C": "Stand on a dry board and continue working carefully.", "D": "Pour cold water on the cable to cool it."}, "correct": "A", "explanation": "Exposed copper strands create a shock hazard and a risk of arcing to nearby metal. The power source must be shut off before anyone handles the damaged cable. The lead should be repaired properly or replaced before welding continues."}, {"id": 1007, "domain": "common_occupational_skills", "question": "A welder must convert measurements for a job. A drawing lists a plate thickness as 12.7 millimetres. The welder needs this value in inches to set up an imperial gauge. Using the standard conversion, what is 12.7 millimetres expressed in inches?", "options": {"A": "One quarter of an inch.", "B": "Three quarters of an inch.", "C": "One full inch exactly.", "D": "One half of an inch."}, "correct": "D", "explanation": "There are 25.4 millimetres in one inch. Dividing 12.7 by 25.4 gives 0.5, which equals one half inch. Welders use this conversion often when reading mixed metric and imperial drawings."}, {"id": 1008, "domain": "common_occupational_skills", "question": "A new apprentice is handed a fire extinguisher rated Class ABC and asked what kinds of fires it can fight. The shop has wood pallets, an oil drip pan, and live electrical panels. Which combination of fire types can a Class ABC extinguisher safely handle?", "options": {"A": "Combustibles, flammable liquids, and energized electrical equipment.", "B": "Only ordinary combustibles such as wood and paper.", "C": "Only flammable liquids and burning cooking grease.", "D": "Only energized electrical panels and motors."}, "correct": "A", "explanation": "Class A covers ordinary combustibles like wood and paper. Class B covers flammable liquids and Class C covers energized electrical equipment. An ABC extinguisher handles all three of these fire types."}, {"id": 1009, "domain": "common_occupational_skills", "question": "A welder is exposed to fumes from welding on galvanized steel without proper ventilation and later feels flu-like symptoms with chills and fever. This condition is a known hazard of certain coated metals. Which metal coating most commonly causes these symptoms when welded?", "options": {"A": "Zinc coating found on galvanized steel.", "B": "Nickel plating used on decorative trim.", "C": "Tin coating used on food containers.", "D": "Chromium plating used on shafts."}, "correct": "A", "explanation": "Galvanized steel is coated with zinc that vaporizes when heated by the arc. Breathing zinc oxide fumes causes metal fume fever with chills, fever, and flu-like aches. Good ventilation and respirators prevent this exposure."}, {"id": 1010, "domain": "common_occupational_skills", "question": "Before lifting a load, a rigger inspects an alloy chain sling and finds one link is stretched and slightly bent compared to the others. The crew is in a hurry to finish the lift. Based on sling inspection rules, what must the rigger do with this chain sling?", "options": {"A": "Use it only for this one final light lift.", "B": "Remove the sling from service immediately.", "C": "Hammer the bent link back to shape.", "D": "Reduce the rated load by one half."}, "correct": "B", "explanation": "A stretched or bent link shows the chain has been overloaded and weakened. Damaged slings can fail without warning under load. The sling must be tagged and removed from service, never repaired in the field."}, {"id": 1011, "domain": "common_occupational_skills", "question": "A welder needs to find the area of a rectangular steel plate to estimate its weight. The plate measures 2 metres long by 1.5 metres wide. The crew leader asks for the surface area of one face of the plate. What is the correct area calculation result?", "options": {"A": "Three point five square metres total.", "B": "Seven square metres total.", "C": "Three square metres total.", "D": "Three point zero five square metres."}, "correct": "C", "explanation": "Area of a rectangle equals length multiplied by width. Multiplying 2 metres by 1.5 metres gives 3 square metres. This area is then used with thickness and density to estimate plate weight."}, {"id": 1012, "domain": "common_occupational_skills", "question": "A lockout procedure is started on a powered grinding machine before maintenance. The worker shuts off the power and applies a personal lock to the disconnect. According to lockout practice, what critical verification step must follow before any repair work begins on the machine?", "options": {"A": "Remove the lock so the next worker can test it.", "B": "Leave the area while the machine cools down.", "C": "Try to start the machine to confirm zero energy.", "D": "Tape the start button so it cannot move."}, "correct": "C", "explanation": "Applying a lock alone does not confirm the energy is gone. The worker must attempt to start the machine using its normal controls to verify it stays off. This try-out step proves the lockout isolated the energy before repair starts."}, {"id": 1013, "domain": "common_occupational_skills", "question": "Two workers carry a long compressed gas cylinder of oxygen across the shop with the regulator still attached and the cylinder lying flat on a cart. A safety officer stops them. Considering safe cylinder handling, which practice was violated during this move?", "options": {"A": "Cylinders should be rolled on their bottom edge across floors.", "B": "Cylinders must always be carried by two workers together.", "C": "Cylinders must be moved with the protective cap on, regulator removed.", "D": "Cylinders should be moved only while completely full."}, "correct": "C", "explanation": "A regulator left on during transport can snap off if the cylinder is dropped or struck. The protective cap must be installed and the regulator removed before moving a cylinder. Cylinders should also be secured upright on a proper cart."}, {"id": 1014, "domain": "common_occupational_skills", "question": "A welder reads a WHMIS 2015 label and sees a pictogram showing an exclamation mark inside a red diamond border. The apprentice asks what category of hazard this symbol represents. Which type of hazard does the exclamation mark pictogram most commonly indicate?", "options": {"A": "Less serious health effects like skin or eye irritation.", "B": "Severe explosion and detonation hazard.", "C": "Pressurized gas stored in a cylinder.", "D": "Material that is highly corrosive to metal."}, "correct": "A", "explanation": "The exclamation mark pictogram warns of lower-level hazards. These include skin and eye irritation, allergic skin reactions, and mild toxicity. It signals caution but not the most severe health dangers."}, {"id": 1015, "domain": "common_occupational_skills", "question": "A grinding task throws sparks and fine metal particles toward the operator's face. The worker already wears safety glasses with side shields. The supervisor still requires more protection for this specific task. Which additional PPE best protects the full face during heavy grinding?", "options": {"A": "A face shield worn over the safety glasses.", "B": "A second pair of tinted sunglasses.", "C": "A cloth bandana tied across the nose.", "D": "Earmuffs to block the grinding noise."}, "correct": "A", "explanation": "Safety glasses protect the eyes but leave the rest of the face open to flying debris. A face shield adds coverage for the cheeks, nose, and chin during heavy grinding. The shield is worn over glasses, not instead of them."}, {"id": 1016, "domain": "common_occupational_skills", "question": "A welder must figure out the cost of filler wire for a job. One spool costs 48 dollars and the job needs 5 spools. The shop adds a 13 percent sales tax to the total. What is the final cost of the wire including the tax?", "options": {"A": "Two hundred forty dollars even.", "B": "Two hundred fifty three dollars even.", "C": "Two hundred seventy one dollars and twenty cents.", "D": "Two hundred eighty eight dollars even."}, "correct": "C", "explanation": "Five spools at 48 dollars each total 240 dollars before tax. Adding 13 percent tax means multiplying 240 by 1.13, which equals 271.20. The final cost is two hundred seventy one dollars and twenty cents."}, {"id": 1017, "domain": "layout_and_fabrication", "question": "A welder reads a blueprint and sees a weld symbol with a triangle below the reference line, the triangle opening to the left. The apprentice asks what joint and weld type this symbol calls for. What does a triangle on the weld symbol represent?", "options": {"A": "A surfacing weld build-up.", "B": "A square groove weld.", "C": "A plug or slot weld.", "D": "A fillet weld on the joint."}, "correct": "D", "explanation": "A triangle on a weld symbol always indicates a fillet weld. The position of the triangle relative to the reference line shows which side of the joint gets the weld. The size shown beside the triangle gives the leg length."}, {"id": 1018, "domain": "layout_and_fabrication", "question": "On a welding symbol the weld size or other information is placed on a specific side of the reference line to show which side of the joint the weld goes. A symbol drawn below the reference line tells the welder to weld on which side of the joint?", "options": {"A": "The arrow side of the joint.", "B": "Both sides of the joint equally.", "C": "The other side away from the arrow.", "D": "Whichever side is easier to reach."}, "correct": "A", "explanation": "On a weld symbol, a symbol placed below the reference line means the weld goes on the arrow side. A symbol above the line means the other side. This convention tells the welder exactly where to place the weld."}, {"id": 1019, "domain": "layout_and_fabrication", "question": "A fabricator needs to find the length of the hypotenuse of a right triangle bracket. One leg is 3 metres and the other leg is 4 metres. Using the Pythagorean theorem to lay out the diagonal brace, what is the length of the hypotenuse?", "options": {"A": "Seven metres in total length.", "B": "Five metres in total length.", "C": "Six metres in total length.", "D": "Twelve metres in total length."}, "correct": "B", "explanation": "The Pythagorean theorem states the hypotenuse squared equals the sum of the squares of the legs. Three squared plus four squared equals nine plus sixteen, which is twenty five. The square root of twenty five is five metres."}, {"id": 1020, "domain": "layout_and_fabrication", "question": "During fit-up of a butt joint in 10 millimetre plate, the welder must set a root opening, also called a root gap, between the two plates. The drawing calls for proper penetration on a single V-groove. What is the purpose of the root opening in this joint?", "options": {"A": "To speed up cooling of the finished weld.", "B": "To reduce the amount of filler metal used.", "C": "To make the plates easier to clamp together.", "D": "To allow full penetration at the bottom of the weld."}, "correct": "D", "explanation": "The root opening gives the arc room to reach the bottom of the joint. This space allows the weld metal to fuse fully through the root of the joint. Without enough gap, the root may lack penetration and fail."}, {"id": 1021, "domain": "layout_and_fabrication", "question": "A welder fabricates a steel frame and notices that after welding the corners, the frame has pulled out of square and bowed inward. This is caused by uneven heating and cooling. Which fabrication technique helps reduce this distortion before and during welding?", "options": {"A": "Welding all joints in one continuous fast pass.", "B": "Welding only one side of the frame fully.", "C": "Heating the whole frame red hot first.", "D": "Using tack welds and a balanced welding sequence."}, "correct": "D", "explanation": "Distortion comes from uneven shrinkage as welds cool. Tack welds hold parts in position and a balanced sequence spreads the heat evenly. Alternating welds across the part keeps shrinkage forces from pulling it out of shape."}, {"id": 1022, "domain": "layout_and_fabrication", "question": "A blueprint shows a circle drawn at the elbow of the weld symbol where the reference line meets the arrow line. The apprentice asks what this circle instructs the welder to do. What does a circle at the elbow of a weld symbol indicate?", "options": {"A": "The weld must be ground perfectly flush.", "B": "The weld must be done in the field.", "C": "The weld is to be made all around the joint.", "D": "The weld requires inspection before painting."}, "correct": "C", "explanation": "A circle at the junction of the arrow and reference line is the weld-all-around symbol. It tells the welder to make the weld completely around the joint. This is common on pipe-to-plate and tube connections."}, {"id": 1023, "domain": "layout_and_fabrication", "question": "A fabricator must mark a centre line down a 600 millimetre wide steel plate before cutting. The crew leader asks how far from each edge the centre line should fall. Working with simple division for layout, where does the centre line sit across this plate?", "options": {"A": "At two hundred millimetres from each edge.", "B": "At three hundred millimetres from each edge.", "C": "At four hundred fifty millimetres from one edge.", "D": "At one hundred fifty millimetres from each edge."}, "correct": "B", "explanation": "The centre line is found by dividing the width in half. Half of 600 millimetres is 300 millimetres. So the centre line sits 300 millimetres from each edge of the plate."}, {"id": 1024, "domain": "layout_and_fabrication", "question": "A welder studies a single bevel groove joint design on thick plate. The drawing shows one plate cut at an angle and the other plate left square. The apprentice asks why a bevel is cut on the joint edge before welding the groove. What is the main reason for the bevel?", "options": {"A": "To improve the painted appearance of the edge.", "B": "To make the plate lighter for handling.", "C": "To leave room for a backing strip only.", "D": "To allow the arc to reach and fuse the full thickness."}, "correct": "D", "explanation": "A bevel opens the joint so the arc can reach deep into the thickness. This lets the weld metal fuse through the full plate thickness for a sound joint. Without the bevel, thick plate would lack penetration at the root."}, {"id": 1025, "domain": "layout_and_fabrication", "question": "A fabricator needs the circumference of a round steel pipe to mark a wrap-around cut line. The pipe outside diameter is 200 millimetres. Using pi as 3.14, the welder calculates the distance around the pipe. What is the approximate circumference of this pipe?", "options": {"A": "About one thousand two hundred millimetres.", "B": "About four hundred millimetres around.", "C": "About three hundred fourteen millimetres.", "D": "About six hundred twenty eight millimetres."}, "correct": "D", "explanation": "Circumference equals pi multiplied by the diameter. Multiplying 3.14 by 200 millimetres gives 628 millimetres. This wrap-around distance is used to mark a straight cut line on round pipe."}, {"id": 1026, "domain": "layout_and_fabrication", "question": "A welding symbol shows a fillet weld with the size 8 written to the left of the triangle, and the numbers 50 and 150 to the right with a dash between them. The apprentice asks what these right-side numbers mean for an intermittent fillet weld. What do 50-150 represent?", "options": {"A": "Plate length of 50 and width of 150.", "B": "Throat depth of 50 and root gap of 150.", "C": "Weld length of 50 and pitch spacing of 150.", "D": "Travel speed of 50 and amperage of 150."}, "correct": "C", "explanation": "On an intermittent fillet weld, the first number is the length of each weld segment. The second number is the pitch, the centre-to-centre spacing between weld segments. So 50-150 means weld 50 long every 150 spacing."}, {"id": 1027, "domain": "layout_and_fabrication", "question": "A welder lays out hole centres on a flat bar at equal spacing. The first hole is at 25 millimetres and each following hole is 75 millimetres apart for a total of four holes. The crew asks for the centre location of the fourth hole from the end. Where is it?", "options": {"A": "At one hundred seventy five millimetres from the end.", "B": "At two hundred fifty millimetres from the end.", "C": "At three hundred millimetres from the end.", "D": "At one hundred millimetres from the end."}, "correct": "B", "explanation": "The first hole sits at 25 millimetres. Each later hole adds 75 millimetres, so hole two is 100, hole three is 175, and hole four is 250. The fourth hole centre is 250 millimetres from the end."}, {"id": 1028, "domain": "layout_and_fabrication", "question": "A welder reviews a drawing and sees a weld symbol with a flag at the elbow where the arrow meets the reference line. The supervisor asks the apprentice to explain what this flag tells the welding crew. What does a flag on a weld symbol indicate?", "options": {"A": "The weld must be tested by x-ray.", "B": "The weld is to be made in the field at the site.", "C": "The weld requires a special low-hydrogen rod.", "D": "The weld must be ground flush after welding."}, "correct": "B", "explanation": "A flag at the elbow of a weld symbol is the field weld symbol. It tells the crew the weld is to be done at the installation site rather than in the shop. This affects planning for equipment and access."}, {"id": 1029, "domain": "layout_and_fabrication", "question": "A fabricator must control distortion on a long butt weld in thin sheet. Instead of welding from one end straight to the other, the welder uses a method of welding short sections in the opposite direction of overall travel. What is this distortion control technique called?", "options": {"A": "Back-step welding along the joint.", "B": "Continuous high-speed welding.", "C": "Single-pass downhill welding.", "D": "Full preheat of the entire sheet."}, "correct": "A", "explanation": "Back-step welding means depositing short welds that progress backward against the overall direction of travel. Each short section shrinks against the previous one, balancing the pull. This spreads the heat and reduces overall distortion in thin material."}, {"id": 1030, "domain": "layout_and_fabrication", "question": "A drawing dimension reads 1500 millimetres but the welder works from a tape marked in metres and centimetres. The apprentice needs this length in metres to compare it to the steel stock on hand. What is 1500 millimetres expressed in metres?", "options": {"A": "Fifteen metres exactly.", "B": "One point five metres exactly.", "C": "Zero point one five metres.", "D": "One hundred fifty metres."}, "correct": "B", "explanation": "There are 1000 millimetres in one metre. Dividing 1500 by 1000 gives 1.5 metres. So 1500 millimetres equals one point five metres."}, {"id": 1031, "domain": "layout_and_fabrication", "question": "A welder must design a joint for two pieces of 6 millimetre plate meeting at a right angle, where one plate edge sits against the face of the other. The drawing calls for strength on both inside and outside corners. Which joint and weld type best suits this T-shaped connection?", "options": {"A": "A T-joint with fillet welds on both sides.", "B": "A butt joint with a single V-groove.", "C": "A lap joint with one plug weld.", "D": "An edge joint with a flare weld."}, "correct": "A", "explanation": "When one plate meets the face of another at a right angle, it forms a T-joint. Fillet welds along the inside corners join the pieces. Welding both sides gives strength on the inside and outside of the connection."}, {"id": 1032, "domain": "layout_and_fabrication", "question": "A fabricator calculates the weight of a steel plate. The plate volume is 0.01 cubic metres and steel density is about 7850 kilograms per cubic metre. The crew leader needs the plate weight before planning the lift. What is the approximate weight of this plate?", "options": {"A": "About eight kilograms total.", "B": "About seven point eight kilograms.", "C": "About seven hundred eighty five kilograms.", "D": "About seventy eight point five kilograms."}, "correct": "D", "explanation": "Weight equals volume multiplied by density. Multiplying 0.01 cubic metres by 7850 kilograms per cubic metre gives 78.5 kilograms. The plate weighs about seventy eight point five kilograms."}, {"id": 1033, "domain": "layout_and_fabrication", "question": "A welder fits up a lap joint where two flat plates overlap each other. The drawing specifies fillet welds along the overlapping edges. The apprentice asks how much the plates should overlap for a sound lap joint in structural work. What is a common minimum overlap guideline?", "options": {"A": "At least three times the thinner plate thickness.", "B": "Exactly one millimetre of overlap only.", "C": "Half the width of the wider plate.", "D": "At least ten times the plate thickness."}, "correct": "A", "explanation": "A lap joint needs enough overlap to develop the strength of the fillet welds. A common guideline is an overlap of at least three times the thickness of the thinner plate. This gives room for sound welds on both edges."}, {"id": 1034, "domain": "layout_and_fabrication", "question": "A blueprint shows a dimension with the letters TYP beside it next to one of several identical holes in a pattern. The apprentice asks what the abbreviation TYP means on a fabrication drawing. What does TYP tell the welder about that dimension?", "options": {"A": "The hole must be tapped with threads.", "B": "The dimension is only a rough estimate.", "C": "The dimension is typical and applies to all similar features.", "D": "The dimension is in inches not millimetres."}, "correct": "C", "explanation": "TYP stands for typical on a drawing. It means the marked dimension applies to all similar features without repeating the number on each one. This keeps the drawing clean while covering every identical hole or detail."}, {"id": 1035, "domain": "layout_and_fabrication", "question": "A welder must bend a steel bracket and needs to know where the metal will bend. The drawing references the neutral axis, the line in the material that neither stretches nor compresses during bending. Why does the fabricator care about this neutral axis when laying out a bend?", "options": {"A": "It tells the welder which side to grind.", "B": "It marks where the paint will crack first.", "C": "It shows where to drill the mounting holes.", "D": "It is used to calculate the correct flat blank length."}, "correct": "D", "explanation": "When metal bends, the outside stretches and the inside compresses, but the neutral axis stays the same length. Layout uses the neutral axis to figure the bend allowance. This gives the correct flat blank length before bending."}, {"id": 1036, "domain": "layout_and_fabrication", "question": "A fabricator sees a weld symbol where the reference line has a second weld symbol on both the top and bottom sides, mirrored across the line. The apprentice asks what this double symbol means. What does a weld symbol shown on both sides of the reference line indicate?", "options": {"A": "The weld must be done twice on one side.", "B": "Welds are required on both sides of the joint.", "C": "The joint must be inspected from both ends.", "D": "Two different welders must share the joint."}, "correct": "B", "explanation": "A symbol below the line means the arrow side and a symbol above means the other side. When symbols appear on both sides of the reference line, welds are needed on both sides of the joint. This is common for double fillet welds."}, {"id": 1037, "domain": "layout_and_fabrication", "question": "A welder lays out a rectangular tank base and must check that the corners are square before tacking. Using the 3-4-5 method, the welder measures 3 units along one side and 4 units along the other. For the corner to be exactly square, what must the diagonal measure?", "options": {"A": "Exactly seven units across the diagonal.", "B": "Exactly six units across the diagonal.", "C": "Exactly five units across the diagonal.", "D": "Exactly four units across the diagonal."}, "correct": "C", "explanation": "The 3-4-5 method uses a right triangle to check for square corners. When the sides measure 3 and 4 units, the diagonal must measure 5 units for a true right angle. Any other diagonal length means the corner is out of square."}, {"id": 1038, "domain": "layout_and_fabrication", "question": "A fabricator must minimize warping when welding a stiffener plate onto a large flat panel. The welder considers using a smaller weld size than first planned, since oversized welds add heat and shrinkage. How does choosing the correct minimum weld size help control distortion?", "options": {"A": "Smaller welds make the panel heavier and stiffer.", "B": "Less weld metal means less heat input and shrinkage.", "C": "Smaller welds cool slower and stay softer.", "D": "Less weld metal increases the joint strength."}, "correct": "B", "explanation": "Larger welds put more heat into the part and deposit more shrinking metal. Using the smallest weld that still meets strength needs lowers heat input. Less heat and less weld metal mean less shrinkage and less distortion."}, {"id": 1039, "domain": "cutting_and_gouging", "question": "A welder sets up an oxy-fuel torch to cut steel plate. The process works by heating the steel to its ignition temperature and then introducing a stream of high-pressure oxygen. What does the oxygen stream do that actually performs the cut in oxy-fuel cutting?", "options": {"A": "It rapidly oxidizes the heated steel and blows it away.", "B": "It cools the steel so it cracks apart cleanly.", "C": "It melts the steel using its own cold pressure.", "D": "It chemically softens the steel into a paste."}, "correct": "A", "explanation": "Oxy-fuel cutting first heats the steel to a bright red ignition temperature. Then the high-pressure oxygen jet rapidly oxidizes, or burns, the hot steel. The force of the oxygen stream blows the molten oxide out of the cut."}, {"id": 1040, "domain": "cutting_and_gouging", "question": "A welder tries to use an oxy-fuel torch to cut a thick aluminum plate but cannot get a clean cut no matter how the flame is set. The apprentice asks why oxy-fuel cutting fails on aluminum. What property of aluminum prevents standard oxy-fuel cutting from working?", "options": {"A": "It is too soft and simply bends away from the flame.", "B": "Its oxide melts at a higher temperature than the metal.", "C": "It conducts no heat away from the cutting zone.", "D": "It reflects the cutting oxygen back at the torch."}, "correct": "B", "explanation": "Oxy-fuel cutting relies on the metal oxidizing at a temperature below its melting point. Aluminum forms a tough oxide that melts hotter than the aluminum itself. This blocks the oxidation reaction, so oxy-fuel cannot cut it cleanly."}, {"id": 1041, "domain": "cutting_and_gouging", "question": "A welder lights an oxy-acetylene torch and adjusts it until the flame shows a sharp, well-defined bright inner cone with no excess feather and no smoky tips. This balanced flame is preferred for cutting steel. What type of oxy-acetylene flame has been set?", "options": {"A": "A carburizing flame with excess acetylene.", "B": "A neutral flame with balanced oxygen and fuel.", "C": "An oxidizing flame with too much oxygen.", "D": "A reducing flame with a long fuel feather."}, "correct": "B", "explanation": "A neutral flame has equal amounts of oxygen and acetylene burning together. It shows a sharp bright inner cone with no excess feather. This balanced flame is the standard setting for cutting and welding most steels."}, {"id": 1042, "domain": "cutting_and_gouging", "question": "A welder uses a plasma cutter to cut stainless steel and notices it cuts faster and cleaner than oxy-fuel would on the same metal. Plasma cutting works on a different principle than oxy-fuel. What allows plasma cutting to cut stainless steel and aluminum effectively?", "options": {"A": "It dissolves the metal with a chemical spray.", "B": "It oxidizes the metal the same way oxy-fuel does.", "C": "It freezes the metal then shatters it apart.", "D": "It melts the metal with a high-temperature ionized gas jet."}, "correct": "D", "explanation": "Plasma cutting forces gas through a constricted arc to create a jet of superheated ionized gas. This plasma jet melts the metal and blows the molten material away. Because it melts rather than oxidizes, it cuts stainless steel and aluminum that oxy-fuel cannot."}, {"id": 1043, "domain": "cutting_and_gouging", "question": "A welder performs air carbon arc gouging to remove a defective weld. The process uses a carbon electrode to create an arc that melts the metal, and then a separate stream blows the molten metal out of the groove. What is the source of that blowing stream?", "options": {"A": "A spray of cooling water around the arc.", "B": "A flow of pure oxygen from the cutting line.", "C": "A jet of compressed air built into the torch.", "D": "A stream of shielding argon gas."}, "correct": "C", "explanation": "Air carbon arc gouging melts metal with an arc from a carbon electrode. A high-velocity jet of compressed air built into the torch blows the molten metal out. This leaves a clean groove for removing welds or defects."}, {"id": 1044, "domain": "cutting_and_gouging", "question": "A welder is about to start air carbon arc gouging and the supervisor reminds the crew about a specific hazard of this process beyond the usual arc dangers. Air carbon arc gouging is known for producing one hazard far more than most other processes. Which hazard is it?", "options": {"A": "Freezing temperatures around the work area.", "B": "Strong magnetic fields that stop pacemakers.", "C": "Very loud noise that requires hearing protection.", "D": "Slippery oil residue on the finished groove."}, "correct": "C", "explanation": "The compressed air blowing through the arc makes air carbon arc gouging extremely loud. Noise levels often exceed safe limits and can damage hearing. Workers must wear proper hearing protection along with their usual arc PPE."}, {"id": 1045, "domain": "cutting_and_gouging", "question": "A welder finishes an oxy-fuel cut and the edge shows deep, irregular gouges and excessive slag clinging to the bottom. The cut traveled too slowly. Besides slow travel speed, which other setup error most commonly causes a rough, slag-heavy oxy-fuel cut edge?", "options": {"A": "Incorrect cutting oxygen pressure for the thickness.", "B": "Using a brand new sharpened soapstone marker.", "C": "Wearing gloves that were too thick to feel.", "D": "Standing on the wrong side of the plate."}, "correct": "A", "explanation": "A clean oxy-fuel cut needs the right oxygen pressure for the plate thickness. Pressure that is too low fails to blow out the molten oxide, leaving slag and a rough edge. Correct pressure and travel speed together produce a clean cut."}, {"id": 1046, "domain": "cutting_and_gouging", "question": "A welder must back gouge the root of a double-sided groove weld to remove any unfused metal before welding the second side. The crew can choose between grinding and air carbon arc gouging. Why is air carbon arc gouging often chosen for back gouging thick weld roots?", "options": {"A": "It requires no electrical power source at all.", "B": "It leaves a perfectly polished mirror finish.", "C": "It adds filler metal while removing the root.", "D": "It removes metal quickly and follows the joint contour."}, "correct": "D", "explanation": "Back gouging removes unsound root metal so the second side fuses to clean metal. Air carbon arc gouging cuts metal fast and follows the shape of the joint. This makes it efficient for cleaning out thick weld roots before back welding."}, {"id": 1047, "domain": "cutting_and_gouging", "question": "A welder sets up a plasma cutter and must connect the work clamp, also called the ground clamp, to the metal being cut. The apprentice asks why this clamp connection matters for the plasma process. What is the role of the work clamp in plasma cutting?", "options": {"A": "It supplies the compressed gas to the torch.", "B": "It completes the electrical circuit so the arc can transfer.", "C": "It holds the plate steady against the table.", "D": "It cools the torch tip during the cut."}, "correct": "B", "explanation": "Plasma cutting uses a transferred arc that travels from the torch to the workpiece. The work clamp completes the electrical circuit through the metal. Without a good clamp connection, the arc cannot transfer and the cut fails."}, {"id": 1048, "domain": "cutting_and_gouging", "question": "A welder is preheating a thick steel plate for oxy-fuel cutting and must position the torch correctly at the edge to start the cut. The preheat flames bring the steel to ignition temperature first. Where should the welder begin a cut on a plate edge?", "options": {"A": "In the exact centre of the plate face.", "B": "At the edge of the plate to start the cut cleanly.", "C": "At the farthest corner from the operator.", "D": "Anywhere the soapstone line is darkest."}, "correct": "B", "explanation": "Starting at the edge lets the preheat flames quickly bring a small area to ignition temperature. Once the edge is hot, the cutting oxygen begins the cut cleanly. Starting in the middle of solid plate requires piercing, which is harder and messier."}, {"id": 1049, "domain": "cutting_and_gouging", "question": "A welder notices a sustained flashback risk while using an oxy-fuel torch, where the flame burns back into the torch with a squealing sound. To guard against flashbacks traveling into the hoses and regulators, what safety device should be installed on an oxy-fuel system?", "options": {"A": "A second pressure gauge on each cylinder.", "B": "Flashback arrestors fitted to the torch or regulators.", "C": "A larger cutting tip for more gas flow.", "D": "A longer hose to keep the cylinders far away."}, "correct": "B", "explanation": "A flashback happens when the flame burns back into the torch and hoses. Flashback arrestors are check valves with flame barriers that stop this travel. They are fitted to the torch or regulators to protect the system and the operator."}, {"id": 1050, "domain": "cutting_and_gouging", "question": "A welder selects a carbon electrode for air carbon arc gouging and the supervisor specifies a copper-coated electrode rather than a plain one. The apprentice asks what advantage the copper coating provides during gouging. Why are copper-coated carbon electrodes commonly used?", "options": {"A": "The copper coating helps carry current and slows electrode burn-off.", "B": "The copper coating makes the groove perfectly smooth.", "C": "The copper coating adds filler metal to the joint.", "D": "The copper coating removes the need for compressed air."}, "correct": "A", "explanation": "The copper coating on a carbon electrode improves electrical conductivity along its length. This helps carry the high current the process needs and slows how fast the electrode burns away. The result is steadier gouging and longer electrode life."}, {"id": 1051, "domain": "cutting_and_gouging", "question": "A welder is plasma cutting 6 mm mild steel but the cut face shows a heavy bevel and rounded top edge. The travel speed seems correct and the air supply is clean. What consumable condition is the most likely cause of this poor cut quality?", "options": {"A": "The work clamp is attached to painted, non-conductive surface metal.", "B": "The nozzle orifice is worn and enlarged from extended use.", "C": "The gas pressure regulator is set far above maximum rating.", "D": "The torch standoff height is set far too low overall."}, "correct": "B", "explanation": "A worn nozzle orifice spreads the plasma arc into a wider, less focused column. This loss of focus produces a beveled cut face and a rounded top edge instead of a square cut. Replacing the nozzle restores a tight arc and a clean square cut."}, {"id": 1052, "domain": "cutting_and_gouging", "question": "During air carbon arc gouging on a carbon steel casting, the operator notices carbon deposits and a rough, ragged groove with poor metal removal. The current and electrode size match the manual. Which adjustment most directly improves the gouge quality in this situation?", "options": {"A": "Lower the air pressure well below thirty psi at torch.", "B": "Switch the machine polarity from DCEP to AC output.", "C": "Increase compressed air pressure and keep it ahead of arc.", "D": "Hold a much steeper electrode angle near ninety degrees."}, "correct": "C", "explanation": "Air carbon arc gouging relies on a strong air jet to blow molten metal out of the groove. Low pressure or air trailing behind the arc leaves carbon and a rough groove. Increasing pressure and keeping the air stream ahead of the arc clears metal cleanly."}, {"id": 1053, "domain": "cutting_and_gouging", "question": "A shop uses mechanized plasma cutting and reports excessive dross sticking to the bottom edge of cut mild steel plate. The amperage matches the chart for the thickness. Which single change is most likely to reduce this low-speed dross formation on the parts?", "options": {"A": "Reduce the plasma gas flow to half its setting.", "B": "Increase the cutting travel speed toward the chart value.", "C": "Raise the torch standoff far above the rated height.", "D": "Change the work lead to a smaller gauge cable."}, "correct": "B", "explanation": "Low-speed dross forms when travel speed is too slow for the amperage being used. The slow torch overheats the kerf and molten metal clings to the bottom edge. Increasing travel speed toward the recommended value reduces heat input and lowers dross."}, {"id": 1054, "domain": "cutting_and_gouging", "question": "A Red Seal welder must select the correct power source polarity for air carbon arc gouging with a copper-coated carbon electrode on steel. Choosing the wrong polarity causes erratic arc action and excessive electrode consumption. Which polarity setting is correct for standard DC carbon arc gouging?", "options": {"A": "Direct current electrode negative for deepest electrode penetration.", "B": "Alternating current to balance heat between both halves.", "C": "Direct current electrode positive for stable arc and clean removal.", "D": "Direct current electrode negative with reduced shielding airflow."}, "correct": "C", "explanation": "Standard air carbon arc gouging on steel uses direct current electrode positive, often called reverse polarity. This setting concentrates heat at the work and gives a stable arc with efficient metal removal. The wrong polarity produces an erratic arc and wastes the electrode quickly."}, {"id": 1055, "domain": "cutting_and_gouging", "question": "After plasma cutting, an inspector finds a beveled kerf where the top of the cut is wider than the bottom on a part cut with directional swirl gas. The operator wants square edges on the good side. What action restores a square edge on the part?", "options": {"A": "Position the good part on the correct side of the kerf.", "B": "Position the scrap side to the right of travel direction.", "C": "Disable swirl gas flow and use straight gas only.", "D": "Double the standoff distance to widen the arc cone."}, "correct": "A", "explanation": "Plasma torches use swirling gas that makes one side of the kerf square and the other side beveled. The square side falls on a predictable side based on the swirl rotation. Placing the good part on that square side gives the clean square edge needed."}, {"id": 1056, "domain": "cutting_and_gouging", "question": "A welder is gouging a defective root pass out of a groove weld before rewelding. The gouge must leave a clean, smooth surface free of carbon so the repair weld fuses properly. Which practice best prevents carbon pickup contaminating the gouged surface during air carbon arc gouging?", "options": {"A": "Stop the air flow just before the arc breaks off.", "B": "Use the longest possible arc length for wide coverage.", "C": "Grind the electrode tip flat before each gouging pass.", "D": "Maintain a steady electrode angle and avoid dwelling the tip."}, "correct": "D", "explanation": "Carbon pickup happens when the electrode dwells or the arc becomes unstable and deposits carbon into the molten metal. A steady angle and continuous forward motion keep the air jet clearing the groove cleanly. Any carbon left in the gouge must be ground out before welding."}, {"id": 1057, "domain": "welding_processes", "question": "A welder loads an E7018 electrode that has been sitting open in shop air overnight in humid conditions. Before using it on a code job, the welder must follow proper handling. What does the low-hydrogen designation of E7018 require regarding storage and conditioning before welding?", "options": {"A": "Storing in a heated rod oven to keep coating dry.", "B": "Soaking the electrodes in clean water before each use.", "C": "Freezing the rods overnight to lock out moisture.", "D": "Dipping the tips in flux paste before striking."}, "correct": "A", "explanation": "E7018 is a low-hydrogen electrode whose flux coating absorbs moisture from the air. Moisture introduces hydrogen that can cause cracking in the weld. Storing the rods in a heated holding oven keeps the coating dry and protects weld quality."}, {"id": 1058, "domain": "welding_processes", "question": "In the SMAW electrode classification E7018, each digit and letter carries meaning under CSA and AWS systems. A welder must read these correctly to pick the right rod. In the designation E7018, what does the third digit value of one indicate about the electrode?", "options": {"A": "The minimum tensile strength is seventy thousand psi.", "B": "It welds in all positions including vertical and overhead.", "C": "The coating is a low-hydrogen iron powder type.", "D": "It runs only on alternating current power sources."}, "correct": "B", "explanation": "The third digit of an SMAW electrode number gives the welding positions allowed. A value of one means the electrode can be used in all positions including flat, horizontal, vertical, and overhead. This lets the welder use the rod on joints in any orientation."}, {"id": 1059, "domain": "welding_processes", "question": "A GMAW welder sets the machine for short-circuit transfer to weld thin sheet metal in the vertical position. The shielding gas choice affects spatter and penetration in this mode. Which shielding gas is most commonly used for short-circuit GMAW on carbon steel sheet metal?", "options": {"A": "One hundred percent argon for a smooth quiet arc.", "B": "One hundred percent carbon dioxide for deepest penetration.", "C": "Seventy-five percent argon with twenty-five percent carbon dioxide.", "D": "One hundred percent helium for high heat input."}, "correct": "C", "explanation": "Short-circuit GMAW on carbon steel commonly uses a blend of seventy-five percent argon and twenty-five percent carbon dioxide. The argon stabilizes the arc and reduces spatter while the carbon dioxide adds penetration. This balance works well on thin sheet in all positions."}, {"id": 1060, "domain": "welding_processes", "question": "A GMAW operator wants spray transfer to weld thick aluminum plate in the flat position for high deposition. Spray transfer requires specific conditions in the arc. Which combination of current and shielding gas supports stable axial spray transfer in GMAW on aluminum?", "options": {"A": "Low current below the transition with carbon dioxide gas.", "B": "Pulsed low current with one hundred percent carbon dioxide.", "C": "High current above the transition with argon-rich shielding gas.", "D": "Very low current with a seventy-five percent helium blend."}, "correct": "C", "explanation": "Spray transfer needs current above the transition level so the wire melts into a fine stream of droplets. It also requires an argon-rich shielding gas because carbon dioxide will not support spray transfer. On aluminum, high current with pure argon gives stable spray transfer."}, {"id": 1061, "domain": "welding_processes", "question": "A pipe welder is making a root pass with GTAW on stainless steel and notices the back side of the weld is heavily oxidized and sugary. The face appears acceptable. Which shielding practice prevents this oxidation on the root side of the stainless steel weld?", "options": {"A": "Increasing the torch argon flow to twice the chart value.", "B": "Using a larger diameter tungsten electrode for more heat.", "C": "Switching the torch gas from argon to carbon dioxide.", "D": "Adding back purge gas inside the pipe during welding."}, "correct": "D", "explanation": "Sugaring is heavy oxidation that forms on the unshielded back side of a stainless steel weld. The root side needs its own shielding because the torch gas only protects the face. Adding a back purge of argon inside the pipe keeps oxygen away and prevents sugaring."}, {"id": 1062, "domain": "welding_processes", "question": "A GTAW welder is setting up to weld aluminum and must choose the correct current type. The process needs to break up the tough oxide layer on the aluminum surface during welding. Which current type provides the cleaning action required for GTAW on aluminum?", "options": {"A": "Direct current electrode negative for maximum penetration.", "B": "Direct current electrode positive for full-time cleaning.", "C": "High-frequency direct current with negative electrode only.", "D": "Alternating current to combine cleaning and penetration."}, "correct": "D", "explanation": "Aluminum forms a tough oxide layer that melts at a much higher temperature than the base metal. The electrode positive half of an AC cycle provides cleaning action that breaks up this oxide. Alternating current balances that cleaning with the penetration of the negative half."}, {"id": 1063, "domain": "welding_processes", "question": "A welder selects a tungsten electrode for GTAW on carbon steel using direct current electrode negative. The tip must hold a sharp point and resist contamination at high current. Which tungsten type and tip preparation suit DCEN welding of steel for a stable, focused arc?", "options": {"A": "Pure tungsten balled to a rounded end for AC use.", "B": "Zirconiated tungsten left with a rounded factory tip.", "C": "Thoriated or ceriated tungsten ground to a sharp point.", "D": "Pure tungsten ground to a long needle-like taper."}, "correct": "C", "explanation": "Direct current electrode negative on steel needs a tungsten that holds a sharp point at high current. Thoriated or ceriated tungsten resists contamination and keeps a stable, focused arc when ground to a point. Pure tungsten is better suited to AC where the tip is balled."}, {"id": 1064, "domain": "welding_processes", "question": "A FCAW welder is running a self-shielded flux-cored wire outdoors on a windy structural site. The supervisor asks why no external shielding gas bottle is connected to the machine. What feature of self-shielded FCAW makes it well suited to this windy outdoor work?", "options": {"A": "The flux core produces its own shielding gas and slag.", "B": "The solid wire core releases argon as it melts.", "C": "The polarity setting blocks air from the molten pool.", "D": "The high travel speed outruns any wind interference."}, "correct": "A", "explanation": "Self-shielded flux-cored wire has flux ingredients inside the tube that create shielding gas and slag as the wire burns. This internal shielding protects the weld pool without an external gas bottle. Because there is no gas cloud to blow away, it performs well in windy outdoor conditions."}, {"id": 1065, "domain": "welding_processes", "question": "A submerged arc welding setup is running a long fillet weld on a heavy beam. The operator must understand how SAW protects the molten pool since no arc light is visible during the process. What provides the shielding of the weld pool in submerged arc welding?", "options": {"A": "A granular flux blanket covering the arc and pool.", "B": "A continuous flow of argon from the welding nozzle.", "C": "A copper backing bar pressed against the joint.", "D": "A self-shielding coating baked onto the solid wire."}, "correct": "A", "explanation": "Submerged arc welding feeds a granular flux that covers the arc and the molten pool completely. This flux blanket shields the weld from the air and hides the arc light, which is why the arc is not visible. The flux also shapes the bead and slows cooling."}, {"id": 1066, "domain": "welding_processes", "question": "A welder reviews the meaning of polarity terms before setting a DC machine for SMAW. The terms DCEP and DCEN describe how current flows and where the most heat goes. In direct current electrode positive (DCEP), where is the greater concentration of heat located?", "options": {"A": "At the electrode, giving shallow penetration into base metal.", "B": "Split evenly between electrode and workpiece at all times.", "C": "At the ground clamp, away from the weld joint.", "D": "At the workpiece, giving deeper penetration into base metal."}, "correct": "D", "explanation": "In direct current electrode positive the electrode is connected to the positive terminal. With this setup the greater heat is concentrated at the workpiece, which produces deeper penetration into the base metal. This is why DCEP is often chosen for joints needing strong fusion."}, {"id": 1067, "domain": "welding_processes", "question": "A code inspector examines a SMAW butt weld and finds a long, narrow cavity running just under the weld surface, formed by trapped gas. The welder used a damp electrode. What is this discontinuity called and what is the most likely root cause in this case?", "options": {"A": "Undercut caused by excessive welding current and arc length.", "B": "Porosity caused by moisture introducing gas into the weld.", "C": "Overlap caused by too slow a travel speed.", "D": "Lamellar tearing caused by stress through the plate thickness."}, "correct": "B", "explanation": "Gas trapped in the solidifying weld forms cavities known as porosity. Moisture in a damp electrode coating breaks down in the arc and releases gas into the molten pool. Keeping low-hydrogen electrodes dry in an oven prevents this kind of porosity."}, {"id": 1068, "domain": "welding_processes", "question": "A GMAW welder running short-circuit transfer produces welds with poor fusion and a cold, ropey appearance even though wire is being deposited steadily. The inductance and voltage may be off. Which condition best describes the cause of cold lap or lack of fusion in short-circuit GMAW?", "options": {"A": "Heat input too low to fully melt the base metal.", "B": "Voltage too high creating excessive spatter and burnthrough.", "C": "Travel speed too slow causing overheating of the joint.", "D": "Shielding gas flow set far above the recommended range."}, "correct": "A", "explanation": "Short-circuit transfer is a low-heat process that can leave the base metal too cold to melt fully. When heat input is too low the deposited metal sits on the surface without fusing, called cold lap. Raising voltage and adjusting technique increases heat for proper fusion."}, {"id": 1069, "domain": "welding_processes", "question": "A welder must pick the right GMAW transfer mode to weld out-of-position joints on medium-thickness steel while controlling the puddle and reducing spatter compared with globular transfer. Which transfer mode uses a controlled current waveform to give spray-like quality at lower average heat?", "options": {"A": "Globular transfer with one hundred percent carbon dioxide gas.", "B": "Pulsed spray transfer cycling between peak and background current.", "C": "Short-circuit transfer at maximum voltage and wire speed.", "D": "Constant current transfer using a stick welding power source."}, "correct": "B", "explanation": "Pulsed spray transfer rapidly cycles the current between a high peak and a low background level. The peak detaches one droplet per pulse like spray transfer, while the low background keeps the average heat down. This control allows clean, low-spatter welds in all positions."}, {"id": 1070, "domain": "welding_processes", "question": "A welder examines an SMAW fillet weld and finds a groove melted into the base metal along the toe of the weld, leaving a notch that reduces the throat. The welder was traveling fast with high current. What is this defect and its likely cause?", "options": {"A": "Incomplete penetration caused by too small a root opening.", "B": "Slag inclusion caused by failing to clean prior passes.", "C": "Spatter caused by an excessively long arc length.", "D": "Undercut caused by high current and fast travel speed."}, "correct": "D", "explanation": "A groove melted into the base metal at the weld toe that is not filled is called undercut. High current combined with fast travel speed melts the edge faster than the filler can fill it. Lowering current and slowing down lets the weld metal fill the groove."}, {"id": 1071, "domain": "welding_processes", "question": "A welder is choosing between solid GMAW wire and metal-cored MCAW wire for high-deposition welding on clean structural steel in the flat position. The shop wants higher travel speeds and good penetration. What advantage does metal-cored wire offer over solid wire in this application?", "options": {"A": "It leaves a thick slag that must be chipped after welding.", "B": "It requires no shielding gas under any conditions.", "C": "It runs only in the vertical-up position on steel.", "D": "It deposits metal faster with a broad arc and good fusion."}, "correct": "D", "explanation": "Metal-cored wire is a tubular wire filled mostly with metal powder rather than slag-forming flux. It deposits metal faster with a broad, smooth arc and gives good fusion and penetration. This makes it well suited to fast, high-deposition welding on clean steel in the flat position."}, {"id": 1072, "domain": "welding_processes", "question": "A welder reads the FCAW wire classification E71T-1 and must understand the digits and letters. Each part tells the welder about strength, position, and usability. In the classification E71T-1, what does the digit one immediately after the letter E and seven indicate?", "options": {"A": "The wire is for flat and horizontal positions only.", "B": "The wire is suitable for all-position welding.", "C": "The wire requires direct current electrode negative.", "D": "The wire produces no slag during welding."}, "correct": "B", "explanation": "In the FCAW classification the digit right after the tensile strength figure shows position usability. A one in that spot means the wire is rated for all positions including vertical and overhead. A zero would mean flat and horizontal positions only."}, {"id": 1073, "domain": "welding_processes", "question": "A GTAW welder must start the arc on a thin titanium part without touching the tungsten to the work, which would contaminate both the weld and the electrode. The machine offers several arc-starting methods. Which arc-starting method avoids tungsten contact with the workpiece in GTAW?", "options": {"A": "Scratch start by dragging the tungsten across the metal.", "B": "Touch start by tapping the tungsten on the joint.", "C": "Hot start by holding the tungsten against the base metal.", "D": "High-frequency start that jumps the arc across a gap."}, "correct": "D", "explanation": "High-frequency starting sends a high-voltage spark that jumps the gap between the tungsten and the work. This ionizes the air and establishes the arc without the tungsten ever touching the metal. Avoiding contact keeps the tungsten and the weld free of contamination."}, {"id": 1074, "domain": "welding_processes", "question": "A welder is reviewing how preheat affects weld quality on thick, high-carbon steel. Welding cold thick sections can lead to cracking from rapid cooling and hard zones. What is the main metallurgical purpose of applying preheat before welding thick or hardenable steel?", "options": {"A": "It slows the cooling rate to reduce hard, crack-prone microstructure.", "B": "It increases the cooling rate to harden the weld faster.", "C": "It removes all alloying elements from the base metal.", "D": "It eliminates the need for any shielding gas coverage."}, "correct": "A", "explanation": "Preheat raises the temperature of the base metal before welding so the weld cools more slowly. Slower cooling reduces the formation of hard, brittle microstructure in the heat-affected zone. This lowers the risk of cracking in thick or hardenable steels."}, {"id": 1075, "domain": "welding_processes", "question": "A welder finishes a multi-pass SMAW groove weld and an inspector finds dark, non-metallic material trapped between passes inside the weld. The welder admits to rushing between passes. What is this defect and what practice would have prevented it during multi-pass welding?", "options": {"A": "Porosity prevented by increasing the shielding gas flow.", "B": "Undercut prevented by lowering the welding current setting.", "C": "Crater crack prevented by backfilling the end of weld.", "D": "Slag inclusion prevented by cleaning slag between passes."}, "correct": "D", "explanation": "Non-metallic material trapped inside a multi-pass weld is a slag inclusion. It happens when slag from a previous pass is not chipped and brushed away before the next pass. Thorough cleaning between passes removes the slag and prevents these inclusions."}, {"id": 1076, "domain": "welding_processes", "question": "A welder must set up SMAW with an E6010 electrode for a root pass on pipe. This electrode behaves differently from E7018 in the arc and requires a specific current type for its deep, digging arc. Which current type and characteristic best describe proper use of E6010?", "options": {"A": "AC only with a soft arc for fill passes.", "B": "DCEP with a deep digging arc good for root passes.", "C": "DCEN with a shallow arc to avoid burnthrough.", "D": "Low-hydrogen storage with a smooth low-spatter arc."}, "correct": "B", "explanation": "E6010 is a cellulosic electrode designed to run on direct current electrode positive. It produces a deep, digging arc that gives strong penetration ideal for open root passes on pipe. Its fast-freezing slag also helps control the puddle in all positions."}, {"id": 1077, "domain": "welding_processes", "question": "A GMAW welder notices very high spatter and a harsh, irregular arc while welding steel with one hundred percent carbon dioxide shielding gas at higher current. The transfer is not smooth spray. Which transfer mode is occurring and why does carbon dioxide promote it here?", "options": {"A": "Spray transfer because carbon dioxide narrows the arc cone.", "B": "Short-circuit transfer because the voltage is far too low.", "C": "Globular transfer because carbon dioxide prevents axial spray.", "D": "Pulsed transfer because the gas pulses the current waveform."}, "correct": "C", "explanation": "Carbon dioxide shielding gas does not support smooth axial spray transfer even at high current. Instead it produces globular transfer where large irregular droplets fall across the arc. These large drops cause the high spatter and harsh arc the welder is seeing."}, {"id": 1078, "domain": "welding_processes", "question": "A welder must control distortion on a long thin steel panel welded with several fillet welds. Heat from welding makes the metal expand and then shrink, pulling the panel out of shape. Which technique helps control distortion by spreading and balancing heat across the part?", "options": {"A": "Using a back-step and balanced welding sequence.", "B": "Welding one continuous pass quickly from end to end.", "C": "Increasing current to finish each weld faster.", "D": "Clamping nothing so the metal can move freely."}, "correct": "A", "explanation": "Distortion comes from uneven heating and the shrinkage that follows as the weld cools. A back-step sequence and balancing welds on opposite sides spread the heat and offset shrinkage forces. This keeps the panel closer to its original shape after welding."}, {"id": 1079, "domain": "welding_processes", "question": "A welder is told to perform postweld heat treatment on a thick pressure vessel weld after welding is complete. The crew asks what this step accomplishes for the finished joint. What is the primary purpose of postweld heat treatment on a welded steel component?", "options": {"A": "To add filler metal to fill any remaining gaps.", "B": "To clean slag and spatter from the weld surface.", "C": "To increase the carbon content of the weld metal.", "D": "To relieve residual stresses and temper the weld zone."}, "correct": "D", "explanation": "Welding leaves locked-in residual stresses and hard zones in and around the weld. Postweld heat treatment heats the part to relieve these stresses and temper the hardened microstructure. The result is a tougher, more stable joint less prone to cracking in service."}, {"id": 1080, "domain": "welding_processes", "question": "A GTAW welder reads the AWS filler rod marking ER70S-2 and needs to understand it before welding carbon steel. The letters and numbers describe the rod form and strength. In the designation ER70S-2, what does the letter combination ER tell the welder about the filler?", "options": {"A": "It is a covered stick electrode for SMAW use.", "B": "It is a solid bare rod or wire for GTAW or GMAW.", "C": "It is a tubular flux-cored wire for FCAW use.", "D": "It is a granular submerged arc flux product."}, "correct": "B", "explanation": "The letters ER on a filler designation stand for electrode and rod in solid bare form. This means the filler is a solid wire or rod used in processes like GTAW and GMAW. It is not a covered stick electrode or a flux-cored tube."}, {"id": 1081, "domain": "welding_processes", "question": "A welder examines the fracture surface of a failed steel weld and sees a stepped, terrace-like crack that runs parallel to the plate surface in the base metal near the joint. The plate was loaded through its thickness. What type of cracking does this describe?", "options": {"A": "Hot cracking that forms in the molten weld pool.", "B": "Crater cracking at the end of the weld bead.", "C": "Lamellar tearing from through-thickness stress on the plate.", "D": "Underbead cracking caused entirely by undercut notches."}, "correct": "C", "explanation": "A stepped, terrace-like crack running parallel to the plate surface is lamellar tearing. It occurs in the base metal when shrinkage stress pulls through the thickness of a plate containing inclusions. Joint redesign and cleaner steel reduce this type of tearing."}, {"id": 1082, "domain": "welding_processes", "question": "A welder must set GMAW wire feed speed and voltage for a given wire size. The relationship between wire feed speed and welding current is important to understand on a constant voltage machine. On a constant voltage GMAW power source, increasing wire feed speed primarily does what?", "options": {"A": "Decreases the welding current and reduces deposition.", "B": "Increases the welding current and the deposition rate.", "C": "Changes the arc voltage with no effect on current.", "D": "Lowers the shielding gas flow automatically at the torch."}, "correct": "B", "explanation": "On a constant voltage GMAW machine the welding current is set mainly by the wire feed speed. Feeding wire faster draws more current to melt it, raising the deposition rate. The voltage knob then sets the arc length and bead shape."}, {"id": 1083, "domain": "welding_processes", "question": "A welder must inspect completed welds without cutting them open and needs a method that finds surface and slightly subsurface cracks on ferromagnetic steel. The shop has limited equipment. Which nondestructive test method uses iron particles and a magnetic field to reveal such cracks?", "options": {"A": "Radiographic testing using X-rays through the joint.", "B": "Ultrasonic testing using high-frequency sound waves.", "C": "Hydrostatic testing using pressurized water in the part.", "D": "Magnetic particle testing using iron particles and a field."}, "correct": "D", "explanation": "Magnetic particle testing applies a magnetic field and fine iron particles to a steel part. Cracks at or near the surface disrupt the field and the particles gather there, making the flaw visible. This works only on ferromagnetic materials such as carbon steel."}, {"id": 1084, "domain": "welding_processes", "question": "A welder needs to find internal flaws like porosity and slag deep inside a thick weld and wants a permanent image record of the inside of the joint. Which nondestructive examination method passes penetrating radiation through the weld to create a film or digital image?", "options": {"A": "Liquid penetrant testing using dye on the surface.", "B": "Magnetic particle testing using surface iron powder.", "C": "Radiographic testing using X-rays or gamma rays.", "D": "Visual inspection using a bright light and gauge."}, "correct": "C", "explanation": "Radiographic testing passes X-rays or gamma rays through the weld onto film or a detector. Internal flaws like porosity and slag absorb radiation differently and show up on the image. This gives a permanent record of flaws deep inside the joint."}, {"id": 1085, "domain": "welding_processes", "question": "A welder finishes a GMAW bead and stops abruptly, leaving a small pit with a crack at the very end of the weld. The supervisor explains this is a common end-of-weld defect. What is this defect called and what technique prevents it when stopping a weld?", "options": {"A": "Undercut prevented by raising the welding voltage at end.", "B": "Porosity prevented by increasing travel speed at the finish.", "C": "Crater crack prevented by backfilling the crater before stopping.", "D": "Overlap prevented by lifting the gun straight up quickly."}, "correct": "C", "explanation": "When a weld stops abruptly the puddle shrinks into a low spot called a crater, which can crack as it cools. This is a crater crack caused by the stress of rapid solidification. Pausing to backfill the crater before breaking the arc prevents it."}, {"id": 1086, "domain": "welding_processes", "question": "A welder is reviewing how the heat-affected zone forms beside a weld. This zone is base metal that did not melt but was changed by the welding heat. What best describes the heat-affected zone and why its properties differ from the rest of the base metal?", "options": {"A": "Base metal altered by heat without melting, changing its structure.", "B": "Metal that fully melted and mixed with filler material.", "C": "Slag deposited on the surface during the welding pass.", "D": "A coating sprayed on after welding to resist corrosion."}, "correct": "A", "explanation": "The heat-affected zone is base metal next to the weld that got hot enough to change but did not melt. The heating and cooling alter its grain structure and hardness compared with the untouched base metal. Controlling heat input and cooling helps manage these property changes."}, {"id": 1087, "domain": "welding_processes", "question": "A submerged arc welder is setting the electrode polarity for a single-wire SAW fillet weld on carbon steel and wants the deepest penetration the process commonly provides. Which polarity is generally selected for maximum penetration in single-wire submerged arc welding?", "options": {"A": "Direct current electrode positive for deepest penetration.", "B": "Direct current electrode negative for shallowest penetration.", "C": "Alternating current only to prevent arc blow.", "D": "Low voltage with reversed ground for no penetration."}, "correct": "A", "explanation": "Single-wire submerged arc welding commonly uses direct current electrode positive when deep penetration is the goal. This polarity concentrates more heat in the joint and drives the arc deeper into the base metal. Electrode negative is used instead when higher deposition with less penetration is wanted."}, {"id": 1088, "domain": "welding_processes", "question": "A welder using DC stick welding near the end of a steel plate notices the arc wandering and being pushed away from the joint, making it hard to control. This is common at plate ends and corners. What phenomenon is causing this and how can the welder reduce it?", "options": {"A": "Porosity from gas, reduced by drying the electrode.", "B": "Arc blow from magnetic fields, reduced by repositioning the ground.", "C": "Undercut from current, reduced by slowing the travel.", "D": "Spatter from voltage, reduced by shortening the arc."}, "correct": "B", "explanation": "Arc blow happens when magnetic fields around the DC arc push it off course, often near plate ends and corners. The welder can reduce it by moving the ground clamp, welding away from the ground, or switching to AC. Shortening the arc length also helps control it."}, {"id": 1089, "domain": "welding_processes", "question": "A welder must select the correct contact tip to nozzle setup and stickout for GMAW spray transfer. Electrical stickout affects current and heat at the wire. What happens to the welding current when the electrical stickout is increased significantly on a constant voltage GMAW machine?", "options": {"A": "Current rises sharply due to lower wire resistance.", "B": "Current stays exactly the same regardless of stickout.", "C": "Current drops because longer stickout adds resistance heating.", "D": "Current reverses direction through the welding circuit."}, "correct": "C", "explanation": "Electrical stickout is the length of wire from the contact tip to the arc. A longer stickout adds resistance that preheats the wire and lowers the welding current at a set wire feed speed. This reduces penetration, so stickout must be kept consistent for stable welds."}, {"id": 1090, "domain": "welding_processes", "question": "A welder examines a groove weld cross section and finds the weld metal did not reach the bottom of the joint, leaving an unfused gap at the root. The root opening was too tight and current too low. What discontinuity is this and how is it corrected?", "options": {"A": "Excess reinforcement corrected by grinding the weld face flat.", "B": "Undercut corrected by adding a final cosmetic cover pass.", "C": "Spatter corrected by cleaning the surface after welding.", "D": "Incomplete joint penetration corrected by proper fit-up and current."}, "correct": "D", "explanation": "When weld metal fails to fill the root of the joint the defect is incomplete joint penetration. A root opening that is too tight or current that is too low keeps the weld from reaching the bottom. Correct fit-up, proper root opening, and adequate current restore full penetration."}, {"id": 1091, "domain": "welding_processes", "question": "A welder reviews the meaning of duty cycle marked on a welding machine before a long continuous job. The plate work requires welding at high current for extended periods. What does a duty cycle rating of sixty percent at three hundred amps tell the welder?", "options": {"A": "The machine outputs three hundred amps for sixty minutes straight.", "B": "The machine reaches sixty percent of three hundred amps maximum.", "C": "The machine can weld at three hundred amps six of ten minutes.", "D": "The machine needs sixty amps of input to run output."}, "correct": "C", "explanation": "Duty cycle is the share of a ten-minute period a machine can weld at a given current without overheating. A rating of sixty percent at three hundred amps means it can weld at that current for six of every ten minutes. The remaining four minutes let the machine cool."}, {"id": 1092, "domain": "welding_processes", "question": "A welder must join 6061 aluminum and selects a filler. Welding aluminum with the wrong filler can lead to cracking in the weld. The base alloy contains magnesium and silicon. Which filler choice is commonly used to weld 6061 aluminum while resisting hot cracking?", "options": {"A": "A plain low-carbon steel filler wire for strength.", "B": "A 4043 silicon-bearing aluminum filler to resist cracking.", "C": "A pure copper filler rod for better conductivity.", "D": "A nickel-based filler intended for stainless steel."}, "correct": "B", "explanation": "Aluminum alloy 6061 is prone to hot cracking when welded with an unsuitable filler. A 4043 filler adds silicon that lowers the melting range and reduces cracking sensitivity. This makes 4043 a common choice for welding 6061 in general fabrication."}, {"id": 1093, "domain": "welding_processes", "question": "A welder is welding thin stainless steel sheet and must limit heat to control warping and protect corrosion resistance. Too much heat can damage the chromium-rich layer and cause distortion. Which practice best limits heat input while welding thin stainless steel?", "options": {"A": "Use lower current, faster travel, and stringer beads.", "B": "Use high current and slow travel for a wide bead.", "C": "Use a large weave pattern across the joint repeatedly.", "D": "Preheat the stainless to a high temperature before welding."}, "correct": "A", "explanation": "Thin stainless steel warps easily and loses corrosion resistance when overheated. Using lower current, faster travel, and narrow stringer beads keeps the heat input down. This limits distortion and protects the chromium that gives stainless its corrosion resistance."}, {"id": 1094, "domain": "welding_processes", "question": "A welder reads a welding procedure specification that lists essential variables for a SMAW joint. The welder asks what an essential variable means for the procedure. What does an essential variable represent within a welding procedure specification under code rules?", "options": {"A": "A variable that may be changed freely without requalification.", "B": "A variable that only describes the color of the equipment.", "C": "A variable that requires requalification if changed beyond limits.", "D": "A variable that applies only to the welder's clothing choice."}, "correct": "C", "explanation": "An essential variable is a factor that affects the mechanical properties of the weld. If it is changed beyond the limits set in the code the procedure must be requalified by testing. Examples include changes in process, filler classification, or major changes in preheat."}, {"id": 1095, "domain": "welding_processes", "question": "A welder is assigned to weld a thick carbon steel joint and a colleague used E6010 for the root but the code job calls for low-hydrogen fill passes to avoid cracking. Which electrode is the appropriate low-hydrogen choice for the fill passes on this hardenable steel?", "options": {"A": "E7018 for a low-hydrogen deposit resisting cracking.", "B": "E6011 for an aggressive arc on AC power.", "C": "E6013 for a soft arc on thin sheet metal.", "D": "E6010 again for deeper digging penetration."}, "correct": "A", "explanation": "Hardenable steels need a low-hydrogen weld deposit to reduce the risk of hydrogen cracking. E7018 is a low-hydrogen electrode that produces a tough deposit with little dissolved hydrogen. Kept dry in an oven, it is the proper choice for fill passes on this joint."}, {"id": 1096, "domain": "welding_processes", "question": "A welder using GTAW notices the tungsten tip turning black and the weld becoming dirty after the arc stops, even though the gas flow looked fine during welding. The problem starts at the end of each weld. What gas-related setting most likely needs adjustment?", "options": {"A": "The postflow time is too short to shield the cooling tungsten.", "B": "The preflow time should be shortened to nearly zero.", "C": "The gas cup should be removed for better visibility.", "D": "The argon should be replaced with carbon dioxide gas."}, "correct": "A", "explanation": "After the arc stops the tungsten and weld remain hot and need continued gas coverage. If the postflow time is too short, air reaches the cooling tungsten and weld, causing oxidation and a black tip. Increasing the postflow time keeps gas flowing until the metal cools."}, {"id": 1097, "domain": "welding_processes", "question": "A welder must understand how shielding gas choice affects penetration profile in GMAW on steel. Different gases produce different bead shapes and depths. Compared with an argon-rich blend, how does adding more carbon dioxide to the shielding gas generally affect the weld penetration?", "options": {"A": "It produces a shallow, narrow finger of penetration only.", "B": "It completely stops any penetration into the base metal.", "C": "It prevents the arc from forming at the wire tip.", "D": "It produces a deeper, broader penetration profile in steel."}, "correct": "D", "explanation": "Carbon dioxide is a more active shielding gas than argon and adds heat to the weld zone. Increasing the carbon dioxide content generally deepens and broadens the penetration profile in steel. Argon-rich blends instead tend to give a narrower finger-shaped penetration."}, {"id": 1098, "domain": "welding_processes", "question": "A welder qualifies for a groove weld test in the 3G position and wants to know what positions the qualification covers for plate welding. Position qualifications follow code rules on which positions a passed test allows. Welding in which position does 3G refer to during a plate groove weld test?", "options": {"A": "Flat position with the plate lying horizontal.", "B": "Vertical position with the groove weld run up or down.", "C": "Overhead position with the plate above the welder.", "D": "Horizontal position with the axis running sideways."}, "correct": "B", "explanation": "Position 3G refers to a groove weld made in the vertical position. The plate stands upright and the weld is run vertically, either uphill or downhill. Passing a 3G test shows the welder can control the puddle against gravity in the vertical position."}, {"id": 1099, "domain": "welding_processes", "question": "A welder is reviewing safety and reads that GMAW and GTAW arcs give off invisible radiation that can burn skin and eyes. Proper personal protection guards against this hazard during arc welding. Which type of radiation from the welding arc is the main cause of arc eye and skin burns?", "options": {"A": "Ultraviolet and infrared radiation emitted by the arc.", "B": "Radio frequency waves emitted by the power cable.", "C": "Visible green light filtered out by clear glasses.", "D": "Microwave radiation produced by the shielding gas."}, "correct": "A", "explanation": "The welding arc emits strong ultraviolet and infrared radiation along with bright visible light. Ultraviolet rays cause arc eye and skin burns much like a severe sunburn. A proper welding helmet with the correct shade lens and protective clothing block this radiation."}, {"id": 1100, "domain": "welding_processes", "question": "A welder must choose a tungsten electrode color code for AC welding of aluminum and reaches for the bin. The electrode colors identify the alloy type added to the tungsten. Which tungsten electrode type, traditionally identified by a green color band, is commonly used for AC aluminum welding?", "options": {"A": "Thoriated tungsten with a red color band for DC steel.", "B": "Pure tungsten with a green color band for AC aluminum.", "C": "Ceriated tungsten with an orange band for thin steel.", "D": "Lanthanated tungsten with a blue band for all uses."}, "correct": "B", "explanation": "Pure tungsten carries a green color band and balls up nicely for alternating current work. This balled tip and its arc characteristics suit AC welding of aluminum. Thoriated tungsten with a red band is instead aimed at direct current welding of steel."}];
